local config = {
  ui_story_5070_50700101_1_dialog_content = "Ah! Isso é muito ruim...",
  ui_story_5070_50700101_2_dialog_content = "Estamos quase no fim das nossas reservas financeiras.",
  ui_story_5070_50700101_3_dialog_content = "Tenho estado muito ocupado para assumir trabalhos ultimamente, e Soroz acabou de passar por manutenção...",
  ui_story_5070_50700101_4_dialog_content = "De alguma forma, gastamos quase todo o nosso dinheiro.",
  ui_story_5070_50700101_5_dialog_content = "Se Vice descobrir, ela vai me colocar de novo em bolachas de ração e café instantâneo com prazo curto para todas as refeições—",
  ui_story_5070_50700101_6_dialog_content = "Oh? O que temos aqui?",
  ui_story_5070_50700101_7_dialog_content = "Vice! N-Não é nada, é só...",
  ui_story_5070_50700101_8_dialog_content = "É só que estamos à beira da falência, então temos que reativar nossos protocolos de racionamento em tempos de guerra. É isso?",
  ui_story_5070_50700101_9_dialog_content = "... Então você já sabia.",
  ui_story_5070_50700101_10_dialog_content = "Seria ainda mais estranho se eu não...",
  ui_story_5070_50700101_11_dialog_content = "Sinceramente, você precisa fazer um trabalho melhor no controle das despesas do Colossus. Eu não posso estar aqui para ajudar o tempo todo, sabe.",
  ui_story_5070_50700101_12_dialog_content = "Ainda assim, parece que o destino está do nosso lado. Dê uma olhada nisso!",
  ui_story_5070_50700101_13_dialog_content = "Um mensageiro acabou de nos trazer uma mensagem urgente da Guilda Lin—",
  ui_story_5070_50700101_14_dialog_content = "\"Caro PlayerName, o assunto a seguir diz respeito ao futuro da nossa guilda. Sendo assim, é nosso mais sincero desejo...\"",
  ui_story_5070_50700101_15_dialog_content = "\"...que como Navegador da Colossus e mestre das artes psíquicas, por favor, nos empreste sua ajuda.\"",
  ui_story_5070_50700101_16_dialog_content = "A Guilda Lin já nos ajudou várias vezes antes, mas agora eles precisam da nossa ajuda! Eles estão oferecendo uma recompensa enorme também!",
  ui_story_5070_50700101_17_dialog_content = "Uma chance de melhorar nosso relacionamento com a Família Lin E ganhar muito dinheiro?",
  ui_story_5070_50700101_18_dialog_content = "Ótimo! Vou traçar um curso para Umbraton imediatamente!",
  ui_story_5070_50700101_19_dialog_content = "Espere, o trabalho não é em Umbraton desta vez.",
  ui_story_5070_50700101_20_dialog_content = "Está em Twin Pavilions Bay.",
  ui_story_5070_50700101_21_dialog_content = "Mas se o trabalho diz respeito ao futuro inteiro da Guilda Lin, por que não iríamos primeiro à sede deles?",
  ui_story_5070_50700101_22_dialog_content = "Porque, segundo eles, Twin Pavilions Bay é tão importante quanto Umbraton... se não mais.",
  ui_story_5070_50700101_23_dialog_content = "Carleen?! Eu pensei que você ainda estava lendo no seu quarto!",
  ui_story_5070_50700101_24_dialog_content = "Ainda tenho tempo livre suficiente para acompanhá-lo desta vez... Além disso, sou o único aqui que conhece Twin Pavilions Bay.",
  ui_story_5070_50700101_25_dialog_content = "Para Lumópolis, o comércio entre Twin Pavilions Bay e Umbraton é vital para a economia.",
  ui_story_5070_50700101_26_dialog_content = "A distante terra de Longzhou traz todos os tipos de produtos para nossas costas...",
  ui_story_5070_50700101_27_dialog_content = "Incluindo muitos produtos valiosos e habilidades que não temos como reproduzir aqui em Astra.",
  ui_story_5070_50700101_28_dialog_content = "A Guilda Lin também é de Longzhou.",
  ui_story_5070_50700101_29_dialog_content = "Após enfrentar o vasto oceano para chegar aqui, o lugar onde eles primeiro pisaram em terra firme foi nada menos que Twin Pavilions Bay.",
  ui_story_5070_50700101_30_dialog_content = "Até hoje, serve como o único porto acessível de Astra para os navios mercantes de Longzhou. De certa forma, é a base das operações comerciais da família Lin.",
  ui_story_5070_50700101_31_dialog_content = "Considerando o quão urgente esse convite parece, eu não acho que eles estejam exagerando quando dizem que <color=#FFB400>o futuro da Guilda Lin</color> está em jogo.",
  ui_story_5070_50700101_32_dialog_content = "Então devemos ir para lá o mais rápido possível.",
  ui_story_5070_50700101_33_dialog_content = "Mas onde exatamente fica essa Twin Pavilions Bay?",
  ui_story_5070_50700101_34_dialog_content = "Deixe-me mostrar o caminho.",
  ui_story_5070_50700101_35_dialog_content = "Podemos chegar lá rapidamente seguindo o Rio Dourado até sua nascente.",
  ui_story_5070_50700101_36_dialog_content = "Incrível! Twin Pavilions Bay não se parece com nenhum outro lugar em Astra!",
  ui_story_5070_50700101_37_dialog_content = "É como se alguém pegasse um lugar de um mundo totalmente diferente e o colocasse bem aqui.",
  ui_story_5070_50700101_38_dialog_content = "Também só li sobre isso em livros.",
  ui_story_5070_50700101_39_dialog_content = "A Família Lin liderou o desenvolvimento desta área com as pessoas que primeiro viajaram pela rota oceânica que estabeleceram.",
  ui_story_5070_50700101_40_dialog_content = "Como resultado, cada vez mais visitantes de Longzhou começaram a chegar aqui.",
  ui_story_5070_50700101_41_dialog_content = "Isso, por sua vez, levou à criação de uma cidade no estilo de Longzhou nas margens de Astra.",
  ui_story_5070_50700101_42_dialog_content = "... É ainda mais maravilhoso pessoalmente do que as descrições em nossos livros.",
  ui_story_5070_50700101_43_dialog_content = "Pãezinhos no vapor, recém-saídos do fogão! Bem quentes e cheios de carne saborosa! Gostariam de alguns pãezinhos no vapor, meus amigos?",
  ui_story_5070_50700101_44_dialog_content = "Viajantes recém-chegados, certo? Então vocês devem experimentar nosso chá!",
  ui_story_5070_50700101_45_dialog_content = "Pré-Chuva Longjing, Yunmeng Silver Bud, Infinito Folha Grande e até mesmo Danshan Oolong: temos todos os tipos de chás famosos, diretamente dos campos de Longzhou!",
  ui_story_5070_50700101_46_dialog_content = "Cheira incrível aqui!",
  ui_story_5070_50700101_47_dialog_content = "Tantas coisas que nunca vi antes! Quando terminarmos nosso trabalho, definitivamente temos que voltar para fazer algumas compras.",
  ui_story_5070_50700101_48_dialog_content = "Falando do trabalho, a carta mencionou algo sobre onde encontrar a guilda?",
  ui_story_5070_50700101_49_dialog_content = "<color=#e8d9bb>De repente, uma rajada de vento passa.</color>",
  ui_story_5070_50700101_50_dialog_content = "Minha carta—!!!",
  ui_story_5070_50700101_51_dialog_content = "H-Hã? Aquela libélula dourada pegou minha carta?",
  ui_story_5070_50700101_52_dialog_content = "Espere, isso não é uma libélula normal... essa coisa é feita de metal?",
  ui_story_5070_50700101_53_dialog_content = "Se eu fosse você, seguraria as coisas com mais cuidado.",
  ui_story_5070_50700101_54_dialog_content = "Ah, uh... Obrigado.",
  ui_story_5070_50700101_55_dialog_content = "Sem problemas!",
  ui_story_5070_50700101_56_dialog_content = "... Era outra especialidade de Longzhou?",
  ui_story_5070_50700101_57_dialog_content = "Aí está você! Me desculpe, mas você é PlayerName?",
  ui_story_5070_50700101_58_dialog_content = "Sim, sou eu. Eu vim para ajudar os Lins!",
  ui_story_5070_50700101_59_dialog_content = "Sou um representante da Guilda Lin. Estamos muito gratos pela sua ajuda. Agora, se você não se importar, vou seguir em frente e discutir os detalhes com você.",
  ui_story_5070_50700101_60_dialog_content = "Tenho certeza de que todos vocês estão um pouco familiarizados com a Guilda Lin, certo?",
  ui_story_5070_50700101_61_dialog_content = "Nos especializamos no transporte e distribuição de mercadorias e tecnologias de Longzhou que normalmente não são encontradas em Astra.",
  ui_story_5070_50700101_62_dialog_content = "No entanto, o vasto oceano que divide nossos dois continentes está repleto de perigos.",
  ui_story_5070_50700101_63_dialog_content = "Como está, apenas os navios da família Lin podem fazer viagens sazonais ao longo das rotas estabelecidas pelos ancestrais.",
  ui_story_5070_50700101_64_dialog_content = "Mas o Shadowind, um dos nossos navios mercantes mais importantes, não foi visto há mais de meio ano por razões ainda desconhecidas.",
  ui_story_5070_50700101_65_dialog_content = "Sem contato por mais de meio ano? Será que algo aconteceu em Longzhou?",
  ui_story_5070_50700101_66_dialog_content = "Nós... também não temos como saber isso.",
  ui_story_5070_50700101_67_dialog_content = "Atualmente, a única maneira de informações viajarem entre nossas duas terras é através dos navios mercantes da Família Lin.",
  ui_story_5070_50700101_68_dialog_content = "Até mesmo a própria Lin Guild não tem outra maneira de se comunicar com seu povo em Longzhou.",
  ui_story_5070_50700101_69_dialog_content = "Infelizmente, a senhorita Carleen está certa.",
  ui_story_5070_50700101_70_dialog_content = "Nem Astra nem Longzhou desenvolveram um dispositivo de comunicação capaz de abranger o vasto oceano entre eles.",
  ui_story_5070_50700101_71_dialog_content = "No entanto, há dois dias, recebemos um sinal vindo da água - um sinal usado internamente pela família Lin.",
  ui_story_5070_50700101_72_dialog_content = "Acreditamos que veio de um dos navios mercantes que chegaram nesta temporada!",
  ui_story_5070_50700101_73_dialog_content = "Mas o sinal desapareceu repentinamente antes que pudéssemos responder, e não recebemos mais nada parecido desde então.",
  ui_story_5070_50700101_74_dialog_content = "Entendi. Você quer que a gente use a Colossus para procurar o navio desaparecido, certo?",
  ui_story_5070_50700101_75_dialog_content = "Exatamente! Dadas as circunstâncias, você é nossa melhor esperança de encontrar isso!",
  ui_story_5070_50700101_76_dialog_content = "Entendido. Faremos tudo o que pudermos.",
  ui_story_5070_50700101_77_dialog_content = "(Nos próximos dias, vasculhamos o oceano do alto da Colossus em busca de algum sinal do navio mercante.)",
  ui_story_5070_50700101_78_dialog_content = "Procuramos em cada canto do mar ao redor do porto, mas não vimos nem sequer um pedaço de madeira flutuante por aqui.",
  ui_story_5070_50700101_79_dialog_content = "Pelo menos, podemos descartar o desaparecimento do navio nas águas próximas. Isso é uma boa notícia, certo?",
  ui_story_5070_50700101_80_dialog_content = "Sim, mas agora parece que nossa única escolha é procurar ainda mais longe.",
  ui_story_5070_50700101_81_dialog_content = "Tá bom assim, PlayerName?",
  ui_story_5070_50700101_82_dialog_content = "Para ser honesto, não estou muito confiante sobre isso...",
  ui_story_5070_50700101_83_dialog_content = "Como está, o Soroz não está preparado para lidar com tempestades inesperadas em alto mar.",
  ui_story_5070_50700101_84_dialog_content = "Eu também não tenho muita experiência por aí. O mais longe que fui do continente é a Ilha das Nuvens.",
  ui_story_5070_50700101_85_dialog_content = "Se o navio desaparecesse ainda mais longe, o resgate seria ainda mais difícil.",
  ui_story_5070_50700101_86_dialog_content = "...",
  ui_story_5070_50700101_87_dialog_content = "Hã? Por que vocês dois estão me olhando assim em silêncio?",
  ui_story_5070_50700101_88_dialog_content = "Porque é você falando, e geralmente...",
  ui_story_5070_50700101_89_dialog_content = "mesmo quando não há esperança, você consegue encontrar uma solução, não é?",
  ui_story_5070_50700101_90_dialog_content = "Acho que vocês estão superestimando minha resistência... Mas, estão certos.",
  ui_story_5070_50700101_91_dialog_content = "Aceitamos o trabalho, afinal. O mínimo que podemos fazer é dar o nosso melhor.",
  ui_story_5070_50700101_92_dialog_content = "Vou usar todo o meu poder para escanear o máximo possível do mar ao nosso redor. Espero conseguir encontrar algo.",
  ui_story_5070_50700101_93_option_content = "Aumento de Força!",
  ui_story_5070_50700101_94_dialog_content = "Na direção do vento... Sim! Há um grande número de Aurorianos naquela direção ali!",
  ui_story_5070_50700101_95_dialog_content = "O oceano abundante provê! Parece que finalmente temos uma pista agora!",
  ui_story_5070_50700101_96_dialog_content = "Esperem, vocês dois, olhem ali. O céu está escurecendo, mas o mar atrás de nós está calmo e tranquilo como um espelho.",
  ui_story_5070_50700101_97_dialog_content = "Tem uma tempestade se aproximando à frente!",
  ui_story_5070_50700101_98_dialog_content = "Eu vejo o navio! É enorme!",
  ui_story_5070_50700101_99_dialog_content = "É um navio mercante da família Lin.",
  ui_story_5070_50700101_100_dialog_content = "Temos que salvá-los! Mas eu não sei se a Colossus consegue–",
  ui_story_5070_50700101_101_dialog_content = "Espere, PlayerName.",
  ui_story_5070_50700101_102_dialog_content = "Dê uma olhada mais de perto.",
  ui_story_5070_50700101_103_dialog_content = "As pessoas no navio... Posso sentir que estão um pouco nervosas, mas não estão entrando em pânico.",
  ui_story_5070_50700101_104_dialog_content = "Os passageiros no convés também estão se movendo com um propósito claro. É como se alguém estivesse dirigindo suas ações com uma mão firme.",
  ui_story_5070_50700101_105_dialog_content = "C-Capitão! Parece que há algo voando sobre nós...",
  ui_story_5070_50700101_106_dialog_content = "Não se preocupe com isso agora. Continue apertando os estais do navio e mantenha o leme estável.",
  ui_story_5070_50700101_107_dialog_content = "Mantenha os olhos na superfície da água.",
  ui_story_5070_50700101_108_dialog_content = "Estamos abrindo caminho à força!",
  ui_story_5070_50700101_109_dialog_content = "Sim sim, capitão!",
  ui_story_5070_50700101_110_dialog_content = "<color=#e8d9bb>As marés aumentam enquanto ondas colossais se erguem e quebram com um estrondo ensurdecedor.</color>",
  ui_story_5070_50700101_111_dialog_content = "<color=#e8d9bb>Mas, justo quando as ondas violentas se convergem em um redemoinho mortal, o navio consegue romper e chegar à segurança!</color>",
  ui_story_5070_50700101_112_dialog_content = "Graças a Deus eles conseguiram sair!",
  ui_story_5070_50700101_113_dialog_content = "Ufa...",
  ui_story_5070_50700101_114_dialog_content = "Isso foi muito perto! Achei que meu coração fosse parar!",
  ui_story_5070_50700101_115_dialog_content = "O capitão daquele navio deve ser uma pessoa incrível.",
  ui_story_5070_50700101_116_dialog_content = "O casco do navio está coberto de danos. Deve ter enfrentado muitas tempestades em seu caminho até aqui.",
  ui_story_5070_50700101_117_dialog_content = "Estou surpreso que ainda possa navegar tão suavemente.",
  ui_story_5070_50700101_118_dialog_content = "O resto da viagem deve ser tranquilo o suficiente. Acho que eles não encontrarão mais perigos.",
  ui_story_5070_50700101_119_dialog_content = "Vamos escoltá-lo pelo restante do caminho antes de encontrar um lugar para pousar.",
  ui_story_5070_50700101_120_dialog_content = "É o Shadowind! Finalmente voltou!",
  ui_story_5070_50700101_121_dialog_content = "Parece diferente do que antes!",
  ui_story_5070_50700101_122_dialog_content = "O que você sabe? Isso é porque é um navio completamente diferente do Shadowind anterior.",
  ui_story_5070_50700101_123_dialog_content = "Anos atrás, havia rumores de que Ye estava desenvolvendo um núcleo mecânico totalmente novo para os maiores navios de Ji...",
  ui_story_5070_50700101_124_dialog_content = "Isso deve ser um daqueles navios novos e melhorados!",
  ui_story_5070_50700101_125_dialog_content = "Mais forte, mais rápido e mais resistente do que nunca! A mais recente versão do Shadowind é a única do seu tipo!",
  ui_story_5070_50700101_126_dialog_content = "T-Tantas pessoas.",
  ui_story_5070_50700101_127_dialog_content = "Sempre que um navio chega ao porto, as pessoas desta cidade saem para recebê-los. É uma espécie de pequena cerimônia para eles.",
  ui_story_5070_50700101_128_dialog_content = "Haha... Mas com a animação desse público, mal conseguimos ver o próprio navio.",
  ui_story_5070_50700101_129_dialog_content = "PlayerName! Graças a Deus eu te encontrei!",
  ui_story_5070_50700101_130_dialog_content = "Huh? É da Guilda Lin...",
  ui_story_5070_50700101_131_dialog_content = "Sim, e como você pode ver, o Shadowind finalmente chegou em segurança ao nosso porto!",
  ui_story_5070_50700101_132_dialog_content = "O capitão também gostaria de falar com você. Por aqui, por favor.",
  ui_story_5070_50700101_133_dialog_content = "O capitão? Mas nós não fizemos nada...",
  ui_story_5070_50700101_134_dialog_content = "Isso quase não é verdade.",
  ui_story_5070_50700101_135_dialog_content = "Deixe-me me apresentar. Sou Mu Yuebai, o capitão do Shadowind.",
  ui_story_5070_50700101_136_dialog_content = "Talvez não tenha sido nada para o lendário Celestita, mas você ajudou o Shadowind mais do que imagina.",
  ui_story_5070_50700101_137_dialog_content = "A verdade é que nosso navio enfrentou um problema sério há meio ano atrás e perdemos contato com a família Lin.",
  ui_story_5070_50700101_138_dialog_content = "Nossa esfera armilar, uma ferramenta usada pela família Lin para navegar no mar com base nas posições das estrelas, também foi perdida em consequência disso.",
  ui_story_5070_50700101_139_dialog_content = "Como resultado, tivemos que confiar apenas na experiência e nas cartas náuticas para traçar um novo curso, meio cego, pelo oceano.",
  ui_story_5070_50700101_140_dialog_content = "Ao longo do caminho, enfrentamos tempestades selvagens e cruéis Eclipsitas, e aquele redemoinho que encontramos antes era igualmente perigoso.",
  ui_story_5070_50700101_141_dialog_content = "Se não fosse pela sua orientação, PlayerName...",
  ui_story_5070_50700101_142_dialog_content = "Mesmo que tivéssemos escapado do redemoinho, estaríamos perdidos no mar por dias antes de encontrar nosso caminho até aqui.",
  ui_story_5070_50700101_143_dialog_content = "Então, mesmo que você ache que não fez nada por nós, eu preciso expressar adequadamente minha gratidão pela sua orientação e proteção.",
  ui_story_5070_50700101_144_dialog_content = "De acordo com a tradição da guilda, aqueles que ajudam a Família Lin de maneira significativa devem ser recompensados em dobro, sendo acolhidos na guilda como convidados de honra.",
  ui_story_5070_50700101_145_dialog_content = "Se a filial de Twin Pavilions Bay não puder compensá-lo, então, com minha autoridade de capitão, eu mesmo o reembolsarei.",
  ui_story_5070_50700101_146_dialog_content = "A-Ahem! Não se precipite agora, Capitão Yuebai.",
  ui_story_5070_50700101_147_dialog_content = "Já chegamos a um acordo à maneira do Astra. Além disso, nosso estimado amigo não se alinha totalmente com nenhuma entidade específica...",
  ui_story_5070_50700101_148_dialog_content = "Preciso da sua resposta, PlayerName. Você vai se unir às forças da Família Lin?",
  ui_story_5070_50700101_149_dialog_content = "(Hã? Estou imaginando coisas, ou o capitão está tentando me fazer entrar oficialmente para o grupo?!)",
  ui_story_5070_50700101_150_dialog_content = "C-Capitão! Embora seja verdade que eu vim aqui em busca de uma grande recompensa...",
  ui_story_5070_50700101_151_dialog_content = "Eu só ajudei da menor maneira possível, essa é a verdade. E eu estava apenas cumprindo meu dever conforme o acordo.",
  ui_story_5070_50700101_152_dialog_content = "Falando em retribuição, a família Lin também tem sido gentil comigo. Funciona nos dois sentidos.",
  ui_story_5070_50700101_153_dialog_content = "É por isso que não posso aceitar esse tipo de recompensa, nem me juntar à família Lin, nesse caso.",
  ui_story_5070_50700101_154_dialog_content = "...",
  ui_story_5070_50700101_155_dialog_content = "Heheh, eu já conheço há muito tempo a maneira enérgica do Capitão Yuebai lidar com os outros. Sua benevolência é igualada apenas por sua imponente força...",
  ui_story_5070_50700101_156_dialog_content = "Imagine ser rejeitado, que situação divertida.",
  ui_story_5070_50700101_157_dialog_content = "Permita-me intervir em nome deste jovem...",
  ui_story_5070_50700101_158_dialog_content = "para que ele possa conversar com você em termos mais locais, isso seria aceitável?",
  ui_story_5070_50700101_159_dialog_content = "Sim! Não estou procurando uma aliança ou tratamento especial. Ser amigo da família Lin já é bom o suficiente para mim!",
  ui_story_5070_50700101_160_dialog_content = "Não me importaria de dar uma volta no Shadowind algum dia! Você também é bem-vindo a bordo do meu Colosso, Capitão Yuebai!",
  ui_story_5070_50700101_161_dialog_content = "... O Shadowind está muito danificado para receber convidados adequadamente no momento.",
  ui_story_5070_50700101_162_dialog_content = "Já que a Senhora Dantang deixou seus desejos claros, naturalmente os seguirei.",
  ui_story_5070_50700101_163_dialog_content = "Perdoe-me se eu cruzei a linha agora há pouco.",
  ui_story_5070_50700101_164_dialog_content = "Não se preocupe com isso! Você também pode me chamar pelo meu nome.",
  ui_story_5070_50700101_165_dialog_content = "O Shadowind ficará atracado aqui pelas próximas duas semanas, aproximadamente. Com todos os reparos necessários, talvez precisemos de seus serviços novamente em breve.",
  ui_story_5070_50700101_166_dialog_content = "Claro, você será generosamente compensado.",
  ui_story_5070_50700101_167_dialog_content = "Parece bom para mim! Alguns dos meus amigos ainda estão esperando por mim, mas estou ansioso para te ver novamente!",
  ui_story_5070_50700101_168_dialog_content = "Espere um momento, Capitão. Eu não fui informado que o Shadowind ficaria no porto por tanto tempo.",
  ui_story_5070_50700101_169_dialog_content = "Há algum outro pedido que—",
  ui_story_5070_50700101_170_dialog_content = "<color=#e8d9bb>Rachadura!</color>",
  ui_story_5070_50700101_171_dialog_content = "<color=#e8d9bb>Um som de rachadura ecoa do navio acima, enquanto um grande pedaço de madeira se solta repentinamente e cai no mar.</color>",
  ui_story_5070_50700101_172_dialog_content = "Isso responde à sua pergunta?",
  ui_story_5070_50700101_173_dialog_content = "E-Entendido... O Shadowind realmente precisa de reparos urgentes. Vou entrar em contato com Li e Sun imediatamente.",
  ui_story_5070_50700101_174_dialog_content = "Fique tranquilo, eles são especialistas. Eles supervisionam os reparos feitos em todos os navios que atracam na Twin Pavilions Bay.",
  ui_story_5070_50700101_175_dialog_content = "Temo que não será um trabalho fácil para eles.",
  ui_story_5070_50700101_176_dialog_content = "Por que PlayerName ainda não voltou? Não me diga que ele foi detido?!",
  ui_story_5070_50700101_177_dialog_content = "Ah, eu não posso ficar aqui e esperar. Eu tenho que ir procurá-lo!",
  ui_story_5070_50700101_178_dialog_content = "Então, isso é Twin Pavilions Bay?",
  ui_story_5070_50700101_179_dialog_content = "O estilo arquitetônico realmente lembra Longzhou, mas alguns detalhes foram um pouco exotizados. Interessante, para dizer o mínimo.",
  ui_story_5070_50700101_180_dialog_content = "Vamos fazer um tour pela cidade, Jiu.",
  ui_story_5070_50700101_181_dialog_content = "Acontece que eu sei que uma certa pessoa de Ye que está aqui há algum tempo...",
  ui_story_5070_50700101_182_dialog_content = "Tenho certeza que ela pode nos mostrar muitos pontos interessantes aqui.",
  ui_story_5070_50700101_183_dialog_content = "A viagem foi longa e cansativa, Alteza. Não deveríamos encontrar um lugar para você descansar primeiro?",
  ui_story_5070_50700101_184_dialog_content = "Nossa, nossa, parece que você está perdendo o ponto, Srta. Jiu.",
  ui_story_5070_50700101_185_dialog_content = "A melhor parte de qualquer jornada é apreciar as paisagens e percorrer as ruas à vontade do seu coração.",
  ui_story_5070_50700101_186_dialog_content = "Permita-me acompanhar vocês dois. Talvez eu possa encontrar um terreno ainda mais auspicioso para a Princesa Dantang pisar?",
  ui_story_5070_50700101_187_dialog_content = "Hmph. Estou cansado.",
  ui_story_5070_50700101_188_dialog_content = "Jiu está certo, devemos voltar para Yuebai e descansar pelo resto do dia.",
  ui_story_5070_50700101_189_dialog_content = "Ei... Espere por mim, Alteza!",
  ui_story_5070_50700101_190_dialog_content = "Posso ter muitos tipos de pessoas comigo. Amigos, guerreiros e até inimigos...",
  ui_story_5070_50700101_191_dialog_content = "Mas vigaristas não têm lugar ao meu lado.",
  ui_story_5070_50700101_192_dialog_content = "Não seja tão cruel, Alteza. E depois de tudo que passamos juntos também...",
  ui_story_5070_50700101_193_dialog_content = "(Ela é realmente bonita... Espere, aquele cara chamou ela de \"Alteza\"?!)",
  ui_story_5070_50700101_194_dialog_content = "Vice? Vice! O que você está olhando?",
  ui_story_5070_50700101_195_dialog_content = "Aaah! Você finalmente voltou!",
  ui_story_5070_50700101_196_dialog_content = "Eu estava apenas pensando que, além de trazer muitas mercadorias...",
  ui_story_5070_50700101_197_dialog_content = "O Shadowind também trouxe muitas pessoas interessantes. Algumas delas podem até se tornar nossas amigas!",
  ui_story_5070_50700101_198_dialog_content = "Ah, isso não vai funcionar. Se ao menos ainda fosse o antigo Shadowind.",
  ui_story_5070_50700101_199_dialog_content = "Mal consigo reconhecer as técnicas utilizadas neste novo modelo, seja na fornalha, nos dissipadores de calor ou na impermeabilização.",
  ui_story_5070_50700101_200_dialog_content = "E nem me fale de todos esses componentes Ye que eles adicionaram na mistura.",
  ui_story_5070_50700101_201_dialog_content = "Viu?",
  ui_story_5070_50700101_202_dialog_content = "...",
  ui_story_5070_50700101_203_dialog_content = "Perdoe-me... Qual parece ser o problema, pessoal?",
  ui_story_5070_50700101_204_dialog_content = "Princesa Dantang!",
  ui_story_5070_50700101_205_dialog_content = "Prefiro não incomodá-lo com os detalhes, Alteza. Afinal, você tem sua missão para cumprir.",
  ui_story_5070_50700101_206_dialog_content = "Você ainda está chateado comigo por ter ofuscado você mais cedo, Yuebai?",
  ui_story_5070_50700101_207_dialog_content = "Você está muito familiarizado com os negócios e disputas entre os oito reinos vassalos de Longzhou.",
  ui_story_5070_50700101_208_dialog_content = "Embora eu esteja aqui como representante de Ji, para eles, sempre serei um refém Ye.",
  ui_story_5070_50700101_209_dialog_content = "Ganhar a total confiança do reino Ji é extremamente difícil, considerando minha identidade.",
  ui_story_5070_50700101_210_dialog_content = "É exatamente por isso que me ofereci para navegar pelo mar e vir para Astra.",
  ui_story_5070_50700101_211_dialog_content = "Só posso esperar que minhas ações provem minha sinceridade.",
  ui_story_5070_50700101_212_dialog_content = "Tudo o que eu faço, faço pela paz e prosperidade mútua dos dois reinos.",
  ui_story_5070_50700101_213_dialog_content = "E já que o Shadowind está inextricavelmente ligado ao comércio, não deveria eu também estar preocupado com seu bem-estar?",
  ui_story_5070_50700101_214_dialog_content = "Se for assim, então naturalmente devo fazer tudo o que puder por sua causa.",
  ui_story_5070_50700101_215_dialog_content = "... São os reparos do Shadowind.",
  ui_story_5070_50700101_216_dialog_content = "Este novo navio está equipado com a tecnologia de ponta mais avançada, desenvolvida cuidadosamente pelos melhores técnicos da Ye. Não tem nada a ver com seu antecessor.",
  ui_story_5070_50700101_217_dialog_content = "Sem artesãos capazes de dominar essa nova tecnologia, receio que consertar o Shadowind será um projeto longo e difícil.",
  ui_story_5070_50700101_218_dialog_content = "A Baía dos Pavilhões Gêmeos possui muitos materiais brutos e construtores navais para trabalhar com eles, mas nenhum deles está preparado para lidar com o Shadowind...",
  ui_story_5070_50700101_219_dialog_content = "Ufa!",
  ui_story_5070_50700101_220_dialog_content = "Princesa Dantang?",
  ui_story_5070_50700101_221_dialog_content = "Se fosse qualquer outra coisa, realmente não teria conseguido ajudar em nada.",
  ui_story_5070_50700101_222_dialog_content = "Mas se você precisa de um talentoso artesão Ye, acho que sei a pessoa certa para o trabalho.",
  ui_story_5070_50700101_223_dialog_content = "Quanto tempo você planejava gastar nos reparos do Shadowind, Yuebai?",
  ui_story_5070_50700101_224_dialog_content = "Meio mês.",
  ui_story_5070_50700101_225_dialog_content = "Então deve haver tempo suficiente.",
  ui_story_5070_50700101_226_dialog_content = "Fiquem tranquilos. O maior artesão de Ye está bem aqui em Twin Pavilions Bay.",
  ui_story_5070_50700101_227_dialog_content = "Ao usar este pássaro transmissor que ela inventou, devo conseguir encontrá-la em breve!",
  ui_story_5070_50700101_228_dialog_content = "Agora que o Shadowind está atracado com segurança no porto, nosso trabalho aqui deve estar concluído... Suspiro...",
  ui_story_5070_50700101_229_dialog_content = "Algo está te incomodando?",
  ui_story_5070_50700101_230_dialog_content = "Eu sei o que é. PlayerName fez um grande e justo alarde ao recusar a oferta do Capitão Yuebai...",
  ui_story_5070_50700101_231_dialog_content = "Deve estar se lamentando por ter recusado um negócio tão bom, aposto.",
  ui_story_5070_50700101_232_dialog_content = "Se você soubesse que isso te incomodaria tanto, deveria ter aceitado naquela época.",
  ui_story_5070_50700101_233_dialog_content = "Não é possível...",
  ui_story_5070_50700101_234_dialog_content = "Mesmo que os reparos do Soroz e nossas despesas diárias tenham apertado as coisas ultimamente...",
  ui_story_5070_50700101_235_dialog_content = "Mesmo que eu não tenha ideia de onde encontrarei outro emprego...",
  ui_story_5070_50700101_236_dialog_content = "Não vou aceitar pagamento por algo que não fiz.",
  ui_story_5070_50700101_237_dialog_content = "Além disso, eu ainda sou bem jovem. Não quero passar os melhores anos da minha vida trabalhando como funcionário da Guilda Lin ou algo assim...",
  ui_story_5070_50700101_238_dialog_content = "Eu não acho que entrar para a Guilda Lin signifique necessariamente que você tenha que se tornar um funcionário.",
  ui_story_5070_50700101_239_dialog_content = "Acho que talvez você não esteja entendendo a questão aqui, Carleen.",
  ui_story_5070_50700101_240_dialog_content = "Meus companheiros de Twin Pavilions Bay!!!",
  ui_story_5070_50700101_241_dialog_content = "Nossa, isso está realmente alto! De onde está vindo?",
  ui_story_5070_50700101_242_dialog_content = "Eles instalaram um dos sistemas de alto-falantes militares da Illumina nos telhados ou algo assim?",
  ui_story_5070_50700101_243_dialog_content = "Após uma longa e árdua jornada de Longzhou, o Shadowind ficará no porto por aproximadamente duas semanas,",
  ui_story_5070_50700101_244_dialog_content = "e passará por muito necessários trabalhos de reparo!",
  ui_story_5070_50700101_245_dialog_content = "Com esse objetivo, estamos recrutando carregadores e artesãos habilidosos na área!",
  ui_story_5070_50700101_246_dialog_content = "Todos estão convidados a se inscrever! Aqueles que emprestarem seu conhecimento e trabalho aos nossos esforços de reparo",
  ui_story_5070_50700101_247_dialog_content = "colherá os benefícios que o Shadowind traz do outro lado do mar!",
  ui_story_5070_50700101_248_dialog_content = "(Respirando fundo) B-Chefe... Rápido, reúna os trabalhadores!",
  ui_story_5070_50700101_249_dialog_content = "Preciso contratar mais funcionários temporários imediatamente. Vou trabalhar em um anúncio agora mesmo.",
  ui_story_5070_50700101_250_dialog_content = "Eu acho que você não precisa! Tenho certeza de que toda a cidade já ouviu a notícia!",
  ui_story_5070_50700101_251_dialog_content = "Mas como? Eu não sabia que Twin Pavilions Bay tinha um sistema assim...",
  ui_story_5070_50700101_252_dialog_content = "Isso poderia ter algo a ver com o que o Capitão Yuebai disse mais cedo...?",
  ui_story_5070_50700101_253_dialog_content = "Que momento perfeito! Vamos ver se há algum bom emprego disponível!",
  ui_story_5070_50700101_254_dialog_content = "Podemos conseguir ganhar uma boa quantia de dinheiro enquanto estivermos aqui!",
  ui_story_5070_50700201_1_dialog_content = "E assim passamos duas semanas muito produtivas em Twin Pavilions Bay.",
  ui_story_5070_50700201_2_dialog_content = "Além de fazer todos os tipos de trabalhos estranhos para o Shadowind, eu também fiz muitas outras coisas...",
  ui_story_5070_50700201_3_dialog_content = "Por exemplo, houve um dia em que Carleen e eu estávamos observando os reparos sendo feitos no Shadowind.",
  ui_story_5070_50700201_4_dialog_content = "Um estranho adivinho segurando um monte de varas esquisitas apareceu e nos enganou para tirarmos um monte de varas da sorte estranhas.",
  ui_story_5070_50700201_5_dialog_content = "Também ajudei Vice a se preparar para uma dança especial que tem como objetivo trazer bênçãos e afastar desastres no mar.",
  ui_story_5070_50700201_6_dialog_content = "Esse também foi o dia em que conhecemos formalmente a Princesa Dantang, que anteriormente me salvou daquela situação desconfortável.",
  ui_story_5070_50700201_7_dialog_content = "No começo, eu estava preocupado que uma nobre de um país estrangeiro seria difícil de conversar, mas ela se mostrou muito acessível e inteligente.",
  ui_story_5070_50700201_8_dialog_content = "Depois, ela e seu servo de roupas pretas nos ensinaram tudo sobre a cultura única de Longzhou.",
  ui_story_5070_50700201_9_dialog_content = "Infelizmente, Carleen e Vice tiveram que voltar para Lumopolis e Illumina após receberem novas ordens.",
  ui_story_5070_50700201_10_dialog_content = "Mas isso não vai me impedir de ganhar ainda mais dinheiro para nós! Afinal, essa é uma oportunidade rara!",
  ui_story_5070_50700201_11_dialog_content = "... PlayerName?",
  ui_story_5070_50700201_12_dialog_content = "Hã? Ah! Desculpe, Princesa Dantang, eu apaguei por um minuto lá.",
  ui_story_5070_50700201_13_dialog_content = "Tudo bem, eu estava prestes a chegar na parte importante.",
  ui_story_5070_50700201_14_dialog_content = "Além disso, eu não te disse para simplesmente me chamar de Dantang?",
  ui_story_5070_50700201_15_dialog_content = "Sim, desculpe Pri—quero dizer Dantang.",
  ui_story_5070_50700201_16_dialog_content = "(Suspiros) Eu não vim aqui para ouvir desculpas, sabe.",
  ui_story_5070_50700201_17_dialog_content = "Prometi à Yuebai que encontraria o artesão perfeito para consertar o navio dela, não foi?",
  ui_story_5070_50700201_18_dialog_content = "Sob sua supervisão, os reparos do Shadowind têm corrido muito bem e o navio já está em sua última fase de manutenção.",
  ui_story_5070_50700201_19_dialog_content = "Por essa razão, começamos os preparativos para uma festa comemorativa para celebrar a conclusão dos reparos do Shadowind.",
  ui_story_5070_50700201_20_dialog_content = "Quanto à minha própria missão, meus esforços também se mostraram frutíferos.",
  ui_story_5070_50700201_21_dialog_content = "O enviado de Lumopolis finalmente retornou com uma resposta graças à Senhora Carleen.",
  ui_story_5070_50700201_22_dialog_content = "Eles concordaram em nos receber como visitantes de Longzhou e discutir tanto negociações comerciais quanto medidas contra os Eclipsitas.",
  ui_story_5070_50700201_23_dialog_content = "O enviado também participará da festa e viajará para Longzhou a bordo do Shadowind para visitar Ji.",
  ui_story_5070_50700201_24_dialog_content = "Parece uma missão bem-sucedida para mim, Dantang! Parabéns!",
  ui_story_5070_50700201_25_dialog_content = "Heheh, obrigado, PlayerName.",
  ui_story_5070_50700201_26_dialog_content = "Agora, o motivo pelo qual vim aqui hoje é para convidá-lo também para o banquete.",
  ui_story_5070_50700201_27_dialog_content = "Você quer dizer que eu posso ir também? Seria uma honra!",
  ui_story_5070_50700201_28_dialog_content = "E seria uma honra tê-lo lá conosco.",
  ui_story_5070_50700201_29_dialog_content = "Uma pena que a Srta. Vice e a Senhora Carleen não virão. Eu realmente queria expressar minha gratidão pela ajuda delas pessoalmente.",
  ui_story_5070_50700201_30_dialog_content = "Com certeza vou tratá-lo especialmente bem na ausência deles.",
  ui_story_5070_50700201_31_dialog_content = "Isso parece bom para mim. Vou terminar o resto do meu trabalho enquanto isso. Te vejo no banquete!",
  ui_story_5070_50700201_32_dialog_content = "Vamos ver...",
  ui_story_5070_50700201_33_dialog_content = "Entregar uma conta à loja na parte leste da cidade, feito. Recolher e devolver as ferramentas dos trabalhadores, feito.",
  ui_story_5070_50700201_34_dialog_content = "Entregue um carregamento de mercadorias neste depósito no final da Rua Chunxi, verifique... mas não realmente.",
  ui_story_5070_50700201_35_dialog_content = "*Suspira*",
  ui_story_5070_50700201_36_dialog_content = "Acordei cedo para entregar esta remessa, mas ninguém veio buscá-la ainda.",
  ui_story_5070_50700201_37_dialog_content = "Eu até tive tempo de fazer outras coisas enquanto isso. Eu me pergunto por que ninguém está aqui?",
  ui_story_5070_50700201_38_dialog_content = "Hoje é o dia do banquete do Shadowind. Vou me atrasar se o cliente não aparecer.",
  ui_story_5070_50700201_39_dialog_content = "Qual é o lance dessas caixas com formatos estranhos, afinal?",
  ui_story_5070_50700201_40_dialog_content = "Eles realmente precisam dessas coisas para consertar um navio?",
  ui_story_5070_50700201_41_dialog_content = "...Hã?",
  ui_story_5070_50700201_42_dialog_content = "Por que parece que tem algo estranho com essas caixas?",
  ui_story_5070_50700201_43_dialog_content = "<color=#e8d9bb>Rangido—Rangido—</color>",
  ui_story_5070_50700201_44_dialog_content = "O que é que foi isso?!",
  ui_story_5070_50700201_45_dialog_content = "<color=#e8d9bb>Rachadura!</color>",
  ui_story_5070_50700201_46_dialog_content = "É algum tipo de... monstro caranguejo? E-Espere, fique atrás!",
  ui_story_5070_50700201_47_dialog_content = "Essas pinças parecem perigosas, mas ainda bem que fui rápido o suficiente para evitá-las...",
  ui_story_5070_50700201_48_dialog_content = "Silvo-!",
  ui_story_5070_50700201_49_dialog_content = "Uau—Ele pode cuspir fogo?!",
  ui_story_5070_50700201_50_dialog_content = "<color=#e8d9bb>Um jorro de fogo escaldante irrompe da boca do monstro.</color>",
  ui_story_5070_50700201_51_dialog_content = "<color=#e8d9bb>De repente, um grande guarda-sol aparece.</color>",
  ui_story_5070_50700201_52_dialog_content = "<color=#e8d9bb>Brilhando intensamente enquanto gira rapidamente, o guarda-sol metálico dispersa rapidamente as chamas que se aproximam.</color>",
  ui_story_5070_50700201_53_dialog_content = "O tempo seco facilita a propagação de incêndios, então tome cuidado!",
  ui_story_5070_50700201_54_dialog_content = "<color=#e8d9bb>As chamas dos monstros parecem não ter fim, mas o guarda-chuva as mantém bem afastadas. Apenas um leve calor do fogo consegue passar.</color>",
  ui_story_5070_50700201_55_dialog_content = "Essa voz soa familiar... Ei, eu me lembro agora! Você usou aquela libélula para me ajudar a pegar minha carta antes!",
  ui_story_5070_50700201_56_dialog_content = "Mas o que há com este guarda-sol...?",
  ui_story_5070_50700201_57_dialog_content = "Ah, eu não tocaria nisso agora se eu fosse você. Eu não me responsabilizo por quaisquer ferimentos que você possa sofrer!",
  ui_story_5070_50700201_58_dialog_content = "Além disso, ainda preciso lidar com esses patifes.",
  ui_story_5070_50700202_1_dialog_content = "I-Incrível!",
  ui_story_5070_50700202_2_dialog_content = "(Parece apenas um guarda-sol comum, mas é mais afiado do que até mesmo a mais lendária das espadas!)",
  ui_story_5070_50700202_3_dialog_content = "(Quando está aberto, nenhuma quantidade de água ou fogo consegue passar por ele.)",
  ui_story_5070_50700202_4_dialog_content = "(Quando está fechada, ela se transforma em uma lâmina imparável.)",
  ui_story_5070_50700202_5_dialog_content = "(Meus olhos nem conseguem acompanhar os movimentos dela!)",
  ui_story_5070_50700202_6_dialog_content = "(Com um movimento rápido do pulso e uma torção de seu guarda-chuva, ela transformou aqueles monstros em um monte de sucata.)",
  ui_story_5070_50700202_7_dialog_content = "Sibilo—",
  ui_story_5070_50700202_8_dialog_content = "(Espera, eles são feitos de metal? Isso significa que alguém construiu essas coisas?)",
  ui_story_5070_50700202_9_dialog_content = "Por que diabos alguém iria querer criar caranguejos gigantes e mecânicos tão assustadores assim...?",
  ui_story_5070_50700202_10_dialog_content = "Esses caranguejos de fogo são apenas uma das muitas Criaturas Mecânicas que são regularmente utilizadas nas oficinas do reino de Ye.",
  ui_story_5070_50700202_11_dialog_content = "Eles são projetados para auxiliar na soldagem e construção de juntas, nada mais.",
  ui_story_5070_50700202_12_dialog_content = "Suas pinças e sua habilidade de liberar pequenas chamas controladas tornam-nas uma adição útil para qualquer oficina!",
  ui_story_5070_50700202_13_dialog_content = "Soldagem? Construção conjunta? Espere, isso significa que eles acharam que eu era matéria-prima ou algo assim?",
  ui_story_5070_50700202_14_dialog_content = "Bem... julgando pela sua força e resistência, você claramente não se encaixa no perfil.",
  ui_story_5070_50700202_15_dialog_content = "Logicamente falando, caranguejos de fogo não deveriam cometer um erro tão simples...",
  ui_story_5070_50700202_16_dialog_content = "Não sei como deveria me sentir sobre isso.",
  ui_story_5070_50700202_17_dialog_content = "Além disso, Ye tem regulamentos muito rigorosos sobre a disseminação e uso de Bestas Mecânicas.",
  ui_story_5070_50700202_18_dialog_content = "Para eles não apenas aparecerem neste lugar, mas também atacarem pessoas...",
  ui_story_5070_50700202_19_dialog_content = "Isso definitivamente significa que alguém está tramando algo ruim.",
  ui_story_5070_50700202_20_dialog_content = "Então você vai sair por conta própria, ou preciso dar o primeiro passo?",
  ui_story_5070_50700202_21_dialog_content = "(Tem mais alguém aqui?!)",
  ui_story_5070_50700202_22_dialog_content = "<color=#e8d9bb>Uma figura sombria repentinamente salta das sombras e corre em direção à porta.</color>",
  ui_story_5070_50700202_23_dialog_content = "Segure!",
  ui_story_5070_50700202_24_dialog_content = "(Ele se esquivou do ataque... Eu tenho que cortá-lo de alguma forma!)",
  ui_story_5070_50700202_25_dialog_content = "Aumento de Força!",
  ui_story_5070_50700202_26_dialog_content = "Relaxe, eu conheço as regras. Afinal, eu tenho feito esse tipo de coisa em Umbraton por anos.",
  ui_story_5070_50700202_27_dialog_content = "Após aceitar o pagamento de um cliente, é natural fazer as coisas de acordo com os desejos deles.",
  ui_story_5070_50700202_28_dialog_content = "Além disso, eles só estão me pedindo para aprender a lidar com esses, uh... Como é que você chama esses caranguejos gigantes mesmo?",
  ui_story_5070_50700202_29_dialog_content = "\"Caranguejos Forjados em Fornalha\" ou algo assim, certo?",
  ui_story_5070_50700202_30_dialog_content = "Vai ser um sofrimento, isso é certo.",
  ui_story_5070_50700202_31_dialog_content = "Mas essa dor não é nada se isso significa que vou fazer a Família Lin e o Shadowind sofrerem.",
  ui_story_5070_50700202_32_dialog_content = "(Ele está mirando no Shadowind? Mas por que...?)",
  ui_story_5070_50700202_33_dialog_content = "Sai do meu caminho!",
  ui_story_5070_50700202_34_dialog_content = "Ah...",
  ui_story_5070_50700202_35_dialog_content = "Cuidado.",
  ui_story_5070_50700202_36_dialog_content = "O-Obrigado por me pegar. Eu teria me machucado muito se você não tivesse. Quem era—",
  ui_story_5070_50700202_37_dialog_content = "Não ligue para ele. Não vale a pena perseguir uma presa encurralada, a menos que você queira ser mordido.",
  ui_story_5070_50700202_38_dialog_content = "Esse cara é apenas um fantoche insignificante.",
  ui_story_5070_50700202_39_dialog_content = "Quanto ao que está puxando suas cordas, já tenho minhas suspeitas.",
  ui_story_5070_50700202_40_dialog_content = "Vou ter que contar com as pessoas aqui em Twin Pavilions Bay para me ajudar a encontrar isso–",
  ui_story_5070_50700202_41_dialog_content = "E-Espere, essa voz!",
  ui_story_5070_50700202_42_dialog_content = "Não é à toa que você soa tão familiar! Você é quem colocou todos aqueles alto-falantes nas torres do portão da cidade!",
  ui_story_5070_50700202_43_dialog_content = "Quem exatamente é você?",
  ui_story_5070_50700202_44_dialog_content = "Hã? Você não sabe quem eu sou?",
  ui_story_5070_50700202_45_dialog_content = "O-Oi?",
  ui_story_5070_50700202_46_dialog_content = "Haha, estou apenas puxando sua perna! Eu não sou tão convencido a ponto de culpar alguém do outro lado do mar por não saber quem eu sou!",
  ui_story_5070_50700202_47_dialog_content = "Ainda assim, estou surpreso que Dantang não tenha me apresentado, considerando o quanto ela me falou sobre você.",
  ui_story_5070_50700202_48_dialog_content = "Isso não é nada justo!",
  ui_story_5070_50700202_49_dialog_content = "Enfim, permita-me apresentar-me.",
  ui_story_5070_50700202_50_dialog_content = "Meu nome é Xuan Ji. Sou um artesão.",
  ui_story_5070_50700202_51_dialog_content = "E assim como a Princesa Dantang, eu também sou da capital dos artesãos de Longzhou: o reino vassalo de Ye.",
  ui_story_5070_50700202_52_dialog_content = "Eu tenho morado em Twin Pavilions Bay por um tempo agora, passando o tempo e fazendo coisas como devolver objetos perdidos aos seus legítimos proprietários.",
  ui_story_5070_50700202_53_dialog_content = "Mas graças à forte recomendação da Princesa Dantang, agora sou o chefe técnico temporário do Shadowind.",
  ui_story_5070_50700202_54_dialog_content = "Não sou responsável apenas pelos reparos do Shadowind, mas também pela manutenção dos Pássaros Mecânicos de transmissão de voz que emprestei à Guilda Lin.",
  ui_story_5070_50700202_55_dialog_content = "Pássaros Mecânicos? Então foi assim que você fez isso...?",
  ui_story_5070_50700202_56_dialog_content = "Sim! Basicamente, eles são apenas alto-falantes voadores que nunca precisam ser pendurados.",
  ui_story_5070_50700202_57_dialog_content = "Mas isso não me impediu de cuidadosamente colocar bicos e penas neles!",
  ui_story_5070_50700202_58_dialog_content = "... Então você é o grande artesão que Dantang me contou.",
  ui_story_5070_50700202_59_dialog_content = "Você realmente faz jus ao seu nome!",
  ui_story_5070_50700202_60_dialog_content = "Devo mencionar algo também.",
  ui_story_5070_50700202_61_dialog_content = "Aqueles caranguejos grandes e aterrorizantes espalhados pelo chão? Eu também os projetei.",
  ui_story_5070_50700202_62_dialog_content = "?",
  ui_story_5070_50700301_1_dialog_content = "Sem mais delongas, por favor, recebam a Capitã Yuebai enquanto ela faz um discurso para o banquete de hoje à noite!",
  ui_story_5070_50700301_2_dialog_content = "Os reparos suaves e expedientes do Shadowind foram o resultado do trabalho árduo e perseverança de todos.",
  ui_story_5070_50700301_3_dialog_content = "O banquete desta noite é em homenagem a todos os presentes.",
  ui_story_5070_50700301_4_dialog_content = "A Família Lin sempre valorizou o trabalho árduo e honesto e está mais do que feliz em recompensar tais esforços notáveis.",
  ui_story_5070_50700301_5_dialog_content = "Então, por favor, comam, bebam e divirtam-se o máximo possível esta noite.",
  ui_story_5070_50700301_6_dialog_content = "Uau!!!",
  ui_story_5070_50700301_7_dialog_content = "Nunca pensei que um banquete tão animado como este pudesse ser realizado em um navio.",
  ui_story_5070_50700301_8_dialog_content = "Seu elogio é muito apreciado, Telema de Lumópolis.",
  ui_story_5070_50700301_9_dialog_content = "Eu me pergunto que outras surpresas Longzhou tem reservadas para mim? Estou ansioso para descobrir.",
  ui_story_5070_50700301_10_dialog_content = "Definitivamente.",
  ui_story_5070_50700301_11_dialog_content = "Longzhou é muito criteriosa ao receber convidados de longe. Como um enviado de Lumópolis, você será considerado um convidado raro e especial.",
  ui_story_5070_50700301_12_dialog_content = "Nada além do melhor tratamento será suficiente.",
  ui_story_5070_50700301_13_dialog_content = "Quando você fala assim, fico ainda mais animado para visitar o outro lado do mar!",
  ui_story_5070_50700301_14_dialog_content = "Mas Longzhou ainda está longe, então posso primeiro aprender um pouco mais sobre as características do Shadowind?",
  ui_story_5070_50700301_15_dialog_content = "Desde que cheguei à Baía dos Pavilhões Gêmeos, ouvi tantos rumores interessantes sobre a tecnologia deste navio.",
  ui_story_5070_50700301_16_dialog_content = "Com seus componentes meticulosamente elaborados e inúmeras funções, o Shadowind é considerado uma verdadeira obra de arte.",
  ui_story_5070_50700301_17_dialog_content = "De qualquer forma, parece muito mais agradável do que qualquer tecnologia volumosa e difícil de manusear usada na Illumina ou no deserto.",
  ui_story_5070_50700301_18_dialog_content = "Cada lugar possui suas próprias tecnologias únicas. Naturalmente, suas vantagens e desvantagens são igualmente variadas.",
  ui_story_5070_50700301_19_dialog_content = "Permita-me encontrar um guia adequado para apresentar suas funcionalidades.",
  ui_story_5070_50700301_20_dialog_content = "(Xuan Ji... Onde você foi parar?)",
  ui_story_5070_50700301_21_dialog_content = "Ah, Sol! Seu timing não poderia ser mais perfeito!",
  ui_story_5070_50700301_22_dialog_content = "S-Sua Alteza?! C-Como posso ser útil?",
  ui_story_5070_50700301_23_dialog_content = "Você seria tão gentil a ponto de mostrar algumas das características do Shadowind ao nosso amigo aqui? O enviado de Lumopolis está muito curioso sobre as várias funções do navio.",
  ui_story_5070_50700301_24_dialog_content = "Mas é claro!",
  ui_story_5070_50700301_25_dialog_content = "Eu tenho mexido com essas engenhocas nas últimas décadas. Você não encontrará um guia melhor do que eu!",
  ui_story_5070_50700301_26_dialog_content = "Então, deixarei o resto em suas mãos competentes.",
  ui_story_5070_50700301_27_dialog_content = "Até nos encontrarmos novamente, minha senhora.",
  ui_story_5070_50700301_28_dialog_content = "Ufa.",
  ui_story_5070_50700301_29_dialog_content = "O que foi, Sua Alteza? Precisa descansar?",
  ui_story_5070_50700301_30_dialog_content = "De jeito nenhum. É muito cedo para eu começar a me sentir cansado.",
  ui_story_5070_50700301_31_dialog_content = "Mas... Eu me pergunto onde PlayerName poderia estar?",
  ui_story_5070_50700301_32_dialog_content = "Será que o trabalho dele atrasou sua chegada?",
  ui_story_5070_50700301_33_dialog_content = "Eu sempre posso ir procurar por ele—",
  ui_story_5070_50700301_34_dialog_content = "Espere!",
  ui_story_5070_50700301_35_dialog_content = "O que é isso, Jiu?",
  ui_story_5070_50700301_36_dialog_content = "Esteja atento ao seu redor, Alteza.",
  ui_story_5070_50700301_37_dialog_content = "...",
  ui_story_5070_50700301_38_dialog_content = "Parece que terei que recitar o código de conduta do Shadowind para nossos passageiros em outra ocasião.",
  ui_story_5070_50700301_39_dialog_content = "O que é isso? O que tá acontecendo?!",
  ui_story_5070_50700301_40_dialog_content = "Oh, meu Deus, o que poderia ser agora? Já foi difícil conseguir um lugar para o banquete de hoje à noite...",
  ui_story_5070_50700301_41_dialog_content = "Um começo inauspicioso para a noite, devo dizer.",
  ui_story_5070_50700301_42_dialog_content = "Fiquem em guarda, pessoal!",
  ui_story_5070_50700301_43_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5070_50700301_44_dialog_content = "Ah! O navio está balançando para frente e para trás!",
  ui_story_5070_50700301_45_dialog_content = "Capitã! Algumas das Feras Mecânicas começaram a atacar as estruturas de suporte do Shadowind!",
  ui_story_5070_50700301_46_dialog_content = "Estamos no meio de um banquete, não é? Noite Branca nas alturas. O que está acontecendo aqui?!",
  ui_story_5070_50700301_47_dialog_content = "Exijo saber o que está acontecendo com este navio agora mesmo!",
  ui_story_5070_50700301_48_dialog_content = "...",
  ui_story_5070_50700301_49_dialog_content = "Por favor, fique aqui, Alteza. Eu vou cuidar das coisas.",
  ui_story_5070_50700301_50_dialog_content = "Muito bem, mas tome cuidado.",
  ui_story_5070_50700302_1_dialog_content = "O assunto foi resolvido, Vossa Alteza.",
  ui_story_5070_50700302_2_dialog_content = "Fico feliz em ouvir isso.",
  ui_story_5070_50700302_3_dialog_content = "Mas por que você parece tão perturbado? Não me diga que se machucou durante o caos—",
  ui_story_5070_50700302_4_dialog_content = "Estou bem, Jiu.",
  ui_story_5070_50700302_5_dialog_content = "Devido ao descontrole das Feras Mecânicas, a Guilda Lin está discutindo se deve ou não adiar a partida do Shadowind.",
  ui_story_5070_50700302_6_dialog_content = "Esta decisão não está sendo tomada por covardia.",
  ui_story_5070_50700302_7_dialog_content = "No entanto, o mar está repleto de perigos, como tempestades e Eclipsitas...",
  ui_story_5070_50700302_8_dialog_content = "Além de tudo isso, nossas Feras Mecânicas começaram a nos atacar inexplicavelmente.",
  ui_story_5070_50700302_9_dialog_content = "É muito perigoso sair do porto. Devemos ser pacientes e continuar observando qualquer mudança.",
  ui_story_5070_50700302_10_dialog_content = "Mas não temos tempo para simplesmente esperar e ver.",
  ui_story_5070_50700302_11_dialog_content = "Como muitos de vocês sabem, eu viajei para Astra com o objetivo de realizar duas metas.",
  ui_story_5070_50700302_12_dialog_content = "O primeiro passo é melhorar as relações com as facções governantes deste continente e formalizar acordos comerciais.",
  ui_story_5070_50700302_13_dialog_content = "A segunda é trocar conhecimentos técnicos e táticos para combater a ameaça Eclipsita.",
  ui_story_5070_50700302_14_dialog_content = "Todos sabem por que esses dois objetivos receberam tão alta prioridade?",
  ui_story_5070_50700302_15_dialog_content = "É porque as costas de Longzhou têm sofrido frequentes ataques de Eclipsitas nos últimos anos. Como resultado, nossos navios mercantes e suas viagens foram bastante afetados.",
  ui_story_5070_50700302_16_dialog_content = "Ji, um dos oito reinos vassalos com os quais estou afiliado, foi fundado no comércio. Como tal, sua prosperidade depende quase inteiramente de vias navegáveis seguras e transporte robusto.",
  ui_story_5070_50700302_17_dialog_content = "As várias guildas de Ji há muito tempo solicitaram que retificássemos esse problema.",
  ui_story_5070_50700302_18_dialog_content = "Mas a corte real ainda não encontrou uma solução duradoura. Não importa quantas vezes os expulsamos, mais ondas de Eclipsitas ocupam seu lugar. Isso fez com que muitos de nosso povo deixassem as áreas costeiras, tornando-as suscetíveis à ocupação de piratas.",
  ui_story_5070_50700302_19_dialog_content = "Nossos comerciantes e trabalhadores da indústria naval estão sob constante ameaça de ataque, e nosso povo não consegue levar vidas pacíficas.",
  ui_story_5070_50700302_20_dialog_content = "Por esse motivo, nosso rei decidiu nomear e enviar um nobre emissário para Astra. Ao fazer isso, ele espera encontrar uma solução na nossa luta contra os Eclipsitas.",
  ui_story_5070_50700302_21_dialog_content = "Convencer Lumópolis a permitir que um enviado me acompanhasse de volta a Longzhou para mais conversas não foi uma tarefa fácil...",
  ui_story_5070_50700302_22_dialog_content = "Mas agora...",
  ui_story_5070_50700302_23_dialog_content = "Quero sair deste navio neste exato momento.",
  ui_story_5070_50700302_24_dialog_content = "Você prometeu que era perfeitamente seguro, não foi? Ainda nem saímos do porto e já fomos atacados!",
  ui_story_5070_50700302_25_dialog_content = "É isso que vocês chamam de seguro?!",
  ui_story_5070_50700302_26_dialog_content = "Ninguém me disse que esses monstros mecânicos eram capazes de nos atacar!",
  ui_story_5070_50700302_27_dialog_content = "Ninguém mesmo!",
  ui_story_5070_50700302_28_dialog_content = "Eu... Eu...",
  ui_story_5070_50700302_29_dialog_content = "... Eu só posso dissuadir o enviado por algum tempo.",
  ui_story_5070_50700302_30_dialog_content = "Se não conseguirmos consertar o navio e colocá-lo em movimento rapidamente, temo que as coisas piorem. Se isso acontecer, então minha missão...",
  ui_story_5070_50700302_31_dialog_content = "Bom...",
  ui_story_5070_50700302_32_dialog_content = "A princesa tem um bom argumento, mas não podemos nos dar ao luxo de ser imprudentes, independentemente das circunstâncias.",
  ui_story_5070_50700302_33_dialog_content = "Você também estaria colocando sua própria vida em risco.",
  ui_story_5070_50700302_34_dialog_content = "Acredito que devemos esperar, Alteza.",
  ui_story_5070_50700302_35_dialog_content = "Se o enviado não estiver disposto a fazer a viagem, eu sempre posso convencê-lo de outras maneiras.",
  ui_story_5070_50700302_36_dialog_content = "Você se sacrificou muito para chegar até aqui. Eu me recuso a deixar tudo isso ser em vão.",
  ui_story_5070_50700302_37_dialog_content = "Ahem, gostaria de compartilhar seus pensamentos, Capitão?",
  ui_story_5070_50700302_38_dialog_content = "...",
  ui_story_5070_50700302_39_dialog_content = "Esta viagem é, sem dúvida, muito importante. O navio transporta mais do que apenas a princesa e nossa mercadoria.",
  ui_story_5070_50700302_40_dialog_content = "Também carrega o futuro da Família Lin.",
  ui_story_5070_50700302_41_dialog_content = "Já sofremos muitas perdas no mar... Receio que não seremos capazes de suportar mais um golpe pesado.",
  ui_story_5070_50700302_42_dialog_content = "O que é ainda mais motivo para ser cauteloso—",
  ui_story_5070_50700302_43_dialog_content = "Então, comece os reparos na estrutura do navio imediatamente.",
  ui_story_5070_50700302_44_dialog_content = "Zarpamos assim que o Shadowind estiver em condições de funcionamento.",
  ui_story_5070_50700302_45_dialog_content = "A-Aham!",
  ui_story_5070_50700302_46_dialog_content = "Capitão! C-Como você também pode...",
  ui_story_5070_50700302_47_dialog_content = "Hã? Espere... Capitão Yuebai!",
  ui_story_5070_50700302_48_dialog_content = "Sinceramente, por que todos os jovens são assim hoje em dia?!",
  ui_story_5070_50700302_49_dialog_content = "Exatamente! Você sabe o que eles dizem. \"A pressa é inimiga da perfeição; devagar se vai ao longe.\"",
  ui_story_5070_50700302_50_dialog_content = "Infelizmente, a situação atual não parece nos conceder o luxo do tempo. Um verdadeiro dilema!",
  ui_story_5070_50700302_51_dialog_content = "Huh? Quem é você...?",
  ui_story_5070_50700302_52_dialog_content = "Interessante, eu não me lembro de um vigarista ter sido convidado para este banquete?",
  ui_story_5070_50700302_53_dialog_content = "Ah, Sua Alteza.",
  ui_story_5070_50700302_54_dialog_content = "Dado tudo o que aconteceu aqui hoje, temo que poucas pessoas ainda tenham apetite.",
  ui_story_5070_50700302_55_dialog_content = "Seria uma pena deixar toda essa comida deliciosa ser desperdiçada, não acha? Felizmente, eu estou com um apetite bem saudável esta noite!",
  ui_story_5070_50700302_56_dialog_content = "Tudo tem um sabor requintado, embora eu ache o melão um pouco decepcionante.",
  ui_story_5070_50700302_57_dialog_content = "Na pressa de providenciar para o banquete, parece que os agricultores colheram essas melancias antes de estarem perfeitamente maduras e doces.",
  ui_story_5070_50700302_58_dialog_content = "Já estou farto do seu falatório...",
  ui_story_5070_50700302_59_dialog_content = "Eu estava apenas fazendo uma observação, nada mais. No final, cabe a você decidir se deve ou não esperar pelo momento certo.",
  ui_story_5070_50700302_60_dialog_content = "Mas às vezes, é melhor deixar a natureza seguir seu curso. Deixar o melão amadurecer e cair da videira é muito mais agradável do que forçar todos a participarem de uma fruta amarga e desagradável.",
  ui_story_5070_50700302_61_dialog_content = "Você não concordaria?",
  ui_story_5070_50700401_1_dialog_content = "Hmm, me dê um minuto para pensar em uma maneira de explicar essa tecnologia para que você possa entender.",
  ui_story_5070_50700401_2_dialog_content = "... Entendi! Compreendo que Astra realizou pesquisas extensas sobre as Quatro Forças...",
  ui_story_5070_50700401_3_dialog_content = "As Quatro Forças?",
  ui_story_5070_50700401_4_dialog_content = "Os quatro diferentes elementos da Lúmina.",
  ui_story_5070_50700401_5_dialog_content = "Minha área de especialização tecnológica está relacionada à combinação de diferentes materiais...",
  ui_story_5070_50700401_6_dialog_content = "E criando máquinas capazes de aproveitar o Lumina, assim como os Aurorianos e as feras espirituais.",
  ui_story_5070_50700401_7_dialog_content = "Isso faz mais sentido para você agora?",
  ui_story_5070_50700401_8_dialog_content = "Parece muito com a tecnologia Lúmina que temos aqui, mas o estilo é completamente diferente.",
  ui_story_5070_50700401_9_dialog_content = "Claro. Nossos objetivos são os mesmos; a diferença está apenas em nossas visões de mundo.",
  ui_story_5070_50700401_10_dialog_content = "O povo de Longzhou acredita que todas as coisas neste mundo contêm Lúmina.",
  ui_story_5070_50700401_11_dialog_content = "Uma vasta rede circulatória de Lumina pode ser observada desde a menor lâmina de grama até a árvore mais alta, e do menor inseto até a mais selvagem das feras.",
  ui_story_5070_50700401_12_dialog_content = "Nossas técnicas nos permitem infundir Lumina nos materiais usados para fazer componentes. Podemos então produzir diversos efeitos ao regular o fluxo dessa Lumina.",
  ui_story_5070_50700401_13_dialog_content = "Com os materiais adequados e estruturas precisas, nossa tecnologia pode até criar um mundo inteiramente novo!",
  ui_story_5070_50700401_14_dialog_content = "Uau, falar sobre sua tecnologia é como falar sobre a filosofia da criação!",
  ui_story_5070_50700401_15_dialog_content = "Hahaha, bem, você não está errado!",
  ui_story_5070_50700401_16_dialog_content = "Aqueles caranguejos de fogo de antes, bem como as minhas libélulas de cobre, são todas manifestações dessa mesma filosofia.",
  ui_story_5070_50700401_17_dialog_content = "Meu Guarda-sol Peculiar também não é exceção.",
  ui_story_5070_50700401_18_dialog_content = "Possui inúmeros mecanismos, por isso é capaz de atacar e defender.",
  ui_story_5070_50700401_19_dialog_content = "Quando compreendidos corretamente, os princípios da nossa tecnologia podem ser aplicados a muito mais do que apenas criaturas mecânicas.",
  ui_story_5070_50700401_20_dialog_content = "Eu não fazia ideia de que era tão impressionante... Acho que o estudo de máquinas não é tão simples quanto eu pensava.",
  ui_story_5070_50700401_21_dialog_content = "Claro que não. Afinal, essa tecnologia é a base de todo um reino vassalo, além de ser o motivo pelo qual a Família Lin conseguiu restabelecer suas rotas comerciais.",
  ui_story_5070_50700401_22_dialog_content = "No Reino de Ye, os céus estão cheios de pássaros mecânicos carregando mensagens, enquanto bois de madeira transportam nossos produtos no chão.",
  ui_story_5070_50700401_23_dialog_content = "Se você estiver com preguiça de colocar roupas, lavar o rosto ou preparar comida, há uma criatura mecânica para ajudá-lo a concluir qualquer tarefa.",
  ui_story_5070_50700401_24_dialog_content = "Se você encontrar tempo para visitar, ficarei feliz em mostrar a verdadeira extensão da nossa tecnologia.",
  ui_story_5070_50700401_25_dialog_content = "Parece bom para mim!",
  ui_story_5070_50700401_26_dialog_content = "Mas...",
  ui_story_5070_50700401_27_dialog_content = "O que exatamente estamos fazendo agora?",
  ui_story_5070_50700401_28_dialog_content = "Não é óbvio? Estamos procurando por um armazém que foi usado recentemente.",
  ui_story_5070_50700401_29_dialog_content = "Estou bem ciente disso, já que já verificamos alguns armazéns.",
  ui_story_5070_50700401_30_dialog_content = "(Algumas delas também estavam trancadas, mas eu não fui rápido o suficiente para impedir Xuan Ji de destrancá-las...)",
  ui_story_5070_50700401_31_dialog_content = "Mas não deveríamos estar perseguindo o inimigo agora?",
  ui_story_5070_50700401_32_dialog_content = "Sou um artesão, lembra? Trabalhar com máquinas é a minha especialidade, então deixe a busca para os pequenos informantes que espalhei por toda a cidade.",
  ui_story_5070_50700401_33_dialog_content = "Um grupo de bandidos escondidos nas sombras conseguiu, de alguma forma, obter minhas plantas de uma fonte desconhecida...",
  ui_story_5070_50700401_34_dialog_content = "Eles transformaram meus caranguejos de fogo em ferramentas para machucar pessoas e guardaram vários deles no depósito do Shadowind.",
  ui_story_5070_50700401_35_dialog_content = "A emboscada fracassada de agora há pouco claramente não era o objetivo real deles.",
  ui_story_5070_50700401_36_dialog_content = "Tenho certeza de que eles têm ainda mais armadilhas escondidas ao redor de Twin Pavilions Bay.",
  ui_story_5070_50700401_37_dialog_content = "... Estou realmente preocupado com a segurança do Shadowind.",
  ui_story_5070_50700401_38_dialog_content = "Pessoas normais não têm chance contra esses caranguejos de fogo.",
  ui_story_5070_50700401_39_dialog_content = "Os fortes não devem oprimir os fracos, os muitos não devem oprimir os poucos e os ricos não devem oprimir os pobres...",
  ui_story_5070_50700401_40_dialog_content = "Com a maquinaria vem um grande poder, e aqueles que o detêm nunca devem usá-lo para machucar os outros.",
  ui_story_5070_50700401_41_dialog_content = "Os artesãos da minha terra se uniram para criar este código de conduta e todos nós juramos segui-lo.",
  ui_story_5070_50700401_42_dialog_content = "Por essa razão, se eu conseguir encontrar o ladrão que roubou minhas plantas...",
  ui_story_5070_50700401_43_dialog_content = "(A voz dela de repente ficou fria como gelo...)",
  ui_story_5070_50700401_44_dialog_content = "Isso mesmo!",
  ui_story_5070_50700401_45_dialog_content = "Do jeito que você colocou, essas feras mecânicas podem simular o fluxo de Lumina em organismos vivos...",
  ui_story_5070_50700401_46_dialog_content = "Isso significa que talvez eu possa usar meus poderes para sentir a localização de mais caranguejos de fogo!",
  ui_story_5070_50700401_47_dialog_content = "Que conclusão interessante.",
  ui_story_5070_50700401_48_dialog_content = "Aqui vai—",
  ui_story_5070_50700401_49_dialog_content = "(Só preciso imaginar os caranguejos de fogo de antes e o mesmo tipo de Lúmina que eles emitiam... Pronto!)",
  ui_story_5070_50700401_50_dialog_content = "É fraco, mas pelo menos consigo sentir a direção deles! É por aqui!",
  ui_story_5070_50700401_51_dialog_content = "Eu nunca esperaria encontrar este pequeno armazém em um local tão fora do caminho.",
  ui_story_5070_50700401_52_dialog_content = "Isso foi realmente impressionante! Obrigado pela sua ajuda, PlayerName.",
  ui_story_5070_50700401_53_dialog_content = "<color=#e8d9bb>Dentro dos armazéns dilapidados, há todos os tipos de caixas estranhas, cada uma contendo—</color>",
  ui_story_5070_50700401_54_dialog_content = "Caranguejos de fogo, gaviões flutuantes, até escorpiões longos... E todos são feitos dos materiais de mais alta qualidade.",
  ui_story_5070_50700401_55_dialog_content = "O proprietário desses armazéns deve ter muito dinheiro para gastar.",
  ui_story_5070_50700401_56_dialog_content = "O que eles planejam fazer com tantas bestas mecânicas?",
  ui_story_5070_50700401_57_dialog_content = "Acha que pode me dar uma mão de novo, PlayerName?",
  ui_story_5070_50700401_58_dialog_content = "Precisamos abrir todas essas caixas e verificar as feras mecânicas em busca de marcas ou símbolos.",
  ui_story_5070_50700401_59_dialog_content = "Agora que você mencionou, você fez exatamente a mesma coisa com aqueles caranguejos de fogo mais cedo.",
  ui_story_5070_50700401_60_dialog_content = "Mas não vejo nenhuma marca nos animais mecânicos em nenhum desses armazéns.",
  ui_story_5070_50700401_61_dialog_content = "Como eu disse antes, o Reino Ye regula fortemente o uso de invenções mecânicas, bem como seus projetos e canais de transporte.",
  ui_story_5070_50700401_62_dialog_content = "Sejam produzidos em massa em uma oficina ou feitos sob medida por um único artesão...",
  ui_story_5070_50700401_63_dialog_content = "Cada máquina de mecanismo deve ser inscrita com uma marca única após a conclusão.",
  ui_story_5070_50700401_64_dialog_content = "Dessa forma, alguém sempre pode ser responsabilizado se surgirem problemas com a máquina.",
  ui_story_5070_50700401_65_dialog_content = "Então, se não conseguirmos encontrar nenhuma marca, isso significa que nossa investigação chegou a um beco sem saída?",
  ui_story_5070_50700401_66_dialog_content = "Não.",
  ui_story_5070_50700401_67_dialog_content = "Pelo menos, isso prova que essas máquinas não foram construídas em uma oficina do Reino Ye.",
  ui_story_5070_50700401_68_dialog_content = "Os componentes deles foram contrabandeados para fora do país e montados aqui.",
  ui_story_5070_50700401_69_dialog_content = "Há outras coisas sendo guardadas nesses armazéns também.",
  ui_story_5070_50700401_70_dialog_content = "Há um monte de outras mercadorias misturadas com as feras mecânicas.",
  ui_story_5070_50700401_71_dialog_content = "Espere um minuto, essas marcas... a Guilda Lin?",
  ui_story_5070_50700401_72_dialog_content = "Exatamente.",
  ui_story_5070_50700401_73_dialog_content = "Há alguns dias, quando o Shadowind chegou ao porto pela primeira vez, ouvi alguns dos passageiros falando sobre a mesma coisa.",
  ui_story_5070_50700401_74_dialog_content = "Algo sobre a família Lin se envolvendo em operações de contrabando em Longzhou e o chefe da família sendo preso pelos Escritórios de Comércio Marítimo...",
  ui_story_5070_50700401_75_dialog_content = "PlayerName, posso te pedir mais um favor?",
  ui_story_5070_50700401_76_dialog_content = "Preciso que você pergunte ao Capitão Yuebai...",
  ui_story_5070_50700401_77_dialog_content = "Se a Família Lin realmente estiver envolvida em contrabando.",
  ui_story_5070_50700401_78_dialog_content = "Tenho procurado armazéns desde que fui atacado por aqueles caranguejos de fogo mais cedo.",
  ui_story_5070_50700401_79_dialog_content = "Será que o banquete do Shadowind já acabou?",
  ui_story_5070_50700401_80_dialog_content = "Hã? Aconteceu alguma coisa a bordo do navio?",
  ui_story_5070_50700401_81_dialog_content = "Certamente você está ciente dos benefícios mútuos que nossa cooperação traria, Telema.",
  ui_story_5070_50700401_82_dialog_content = "Claro que estou ciente deles. Não insulte minha inteligência.",
  ui_story_5070_50700401_83_dialog_content = "Mas não importa o quão grandiosa seja Longzhou ou quão vital seja nossa missão, qual o sentido se não conseguirmos chegar à sua terra natal em segurança?",
  ui_story_5070_50700401_84_dialog_content = "Tomei várias precauções para garantir sua segurança a cada passo do caminho.",
  ui_story_5070_50700401_85_dialog_content = "Como um cidadão honrado de Lumópolis, eu realmente desejo acreditar em você.",
  ui_story_5070_50700401_86_dialog_content = "Mas... Com tudo o que aconteceu, receio que devo reconsiderar.",
  ui_story_5070_50700401_87_dialog_content = "Telema...",
  ui_story_5070_50700401_88_dialog_content = "(Não é aquele enviado de Lumópolis que Dantang estava falando? Por que a mudança repentina de opinião?)",
  ui_story_5070_50700401_89_dialog_content = "O último local suspeito que resta para procurar é esta farmácia.",
  ui_story_5070_50700401_90_dialog_content = "Esse sentimento... Parece haver um poderoso usuário das Artes da Força Flamejante aqui dentro.",
  ui_story_5070_50700401_91_dialog_content = "Agora, vamos ver quem está se escondendo logo atrás desta porta.",
  ui_story_5070_50700401_92_dialog_content = "<size=45>Toc, toc, toc!</color>",
  ui_story_5070_50700401_93_dialog_content = "O que foi?",
  ui_story_5070_50700401_94_dialog_content = "Perdoe minha intromissão, mas tenho algumas perguntas que gostaria de fazer.",
  ui_story_5070_50700401_95_dialog_content = "Você conhece o dono daquele armazém ali?",
  ui_story_5070_50700401_96_dialog_content = "Se não, então você é familiarizado com a Família Lin?",
  ui_story_5070_50700401_97_dialog_content = "...",
  ui_story_5070_50700401_98_dialog_content = "(A porta está abrindo? É melhor se preparar para uma luta! Completo—)",
  ui_story_5070_50700401_99_dialog_content = "...",
  ui_story_5070_50700401_100_dialog_content = "?",
  ui_story_5070_50700401_101_dialog_content = "Por que há uma criança atendendo a porta? Desculpe, mas eu poderia falar com um adulto?",
  ui_story_5070_50700401_102_dialog_content = "Quem disse que eu sou uma criança?!",
  ui_story_5070_50700401_103_dialog_content = "Bem, você é claramente um...",
  ui_story_5070_50700401_104_dialog_content = "<color=#e8d9bb>Ding—!</color>",
  ui_story_5070_50700401_105_dialog_content = "Você é rápido no pé.",
  ui_story_5070_50700401_106_dialog_content = "Eu sabia que deveria ter consultado o almanaque antes de sair hoje. Tenho certeza de que ele teria me alertado sobre vir a um lugar onde recebem visitantes sacando suas espadas.",
  ui_story_5070_50700401_107_dialog_content = "<size=45>Graaah—</size>",
  ui_story_5070_50700401_108_dialog_content = "Oh? Nossa, isso é realmente uma comissão de boas-vindas inesperada.",
  ui_story_5070_50700402_1_dialog_content = "Esses caras simplesmente não sabem quando desistir, né?",
  ui_story_5070_50700402_2_dialog_content = "Continuamos matando-os, mas eles continuam surgindo do nada...",
  ui_story_5070_50700402_3_dialog_content = "Huh? Ei! Você não vai lutar com ela, Zhong Xu?",
  ui_story_5070_50700402_4_dialog_content = "Um guarda-sol de metal, uma libélula de cobre e criações mecânicas tão bem trabalhadas.",
  ui_story_5070_50700402_5_dialog_content = "Você seria talvez... Ministra Armilla?",
  ui_story_5070_50700402_6_dialog_content = "Espere, você conhece ela?",
  ui_story_5070_50700402_7_dialog_content = "Nunca nos encontramos, mas já ouvi muito sobre ela.",
  ui_story_5070_50700402_8_dialog_content = "Um artesão genial do Reino Ye pertencente à seita Qianyun.",
  ui_story_5070_50700402_9_dialog_content = "Aos quinze anos, ela chocou a nação inteira com seus fantoches mecânicos realistas que tocavam música.",
  ui_story_5070_50700402_10_dialog_content = "Pouco tempo depois, ela se tornou uma conselheira estratégica para o rei de Ye.",
  ui_story_5070_50700402_11_dialog_content = "Minha compreensão é que os títulos concedidos pelo Reino Ye são baseados em invenções famosas. Para que você receba o título de \"Armilla\", significa que seu reino realmente reconhece sua genialidade.",
  ui_story_5070_50700402_12_dialog_content = "Ah, eu não iria tão longe. Além disso, me aposentei da cena política há muito tempo; agora sou apenas um simples artesão.",
  ui_story_5070_50700402_13_dialog_content = "Mas você? Um mestre espadachim de cabelos vermelhos e com conhecimento da política de Longzhou...",
  ui_story_5070_50700402_14_dialog_content = "Você deve ser o Sr. Zhong Xu, o estimado associado da Família Lin, conhecido e respeitado por todas as guildas do Reino Ji.",
  ui_story_5070_50700402_15_dialog_content = "Suas palavras são mais gentis do que eu mereço, minha senhora.",
  ui_story_5070_50700402_16_dialog_content = "Liqing.",
  ui_story_5070_50700402_17_dialog_content = "Essa jovem mulher não é nossa inimiga.",
  ui_story_5070_50700402_18_dialog_content = "Não necessariamente.",
  ui_story_5070_50700402_19_dialog_content = "Ei! O que isso quer dizer?! Não tem modos?!",
  ui_story_5070_50700402_20_dialog_content = "Silêncio, pequenino. Os adultos estão conversando agora.",
  ui_story_5070_50700402_21_dialog_content = "Eu já disse que não sou criança!",
  ui_story_5070_50700402_22_dialog_content = "Há meio ano, o Reino de Ji estava rastreando uma remessa de mercadorias contrabandeadas.",
  ui_story_5070_50700402_23_dialog_content = "Após uma investigação minuciosa, descobriram que os navios mercantes da família Lin eram os únicos com acesso aos registros de partida.",
  ui_story_5070_50700402_24_dialog_content = "A Guilda Lin também não conseguiu fornecer uma explicação válida sobre o assunto.",
  ui_story_5070_50700402_25_dialog_content = "E daí? Você acha que pode culpá-los baseado apenas em coincidências?",
  ui_story_5070_50700402_26_dialog_content = "Você tem razão.",
  ui_story_5070_50700402_27_dialog_content = "Embora os únicos suspeitos no caso sejam a Família Lin, muitas pessoas ainda consideram o assunto altamente questionável.",
  ui_story_5070_50700402_28_dialog_content = "Mas depois de procurar nos armazéns próximos agora há pouco...",
  ui_story_5070_50700402_29_dialog_content = "Encontrei uma grande quantidade de bestas mecânicas do Reino Ye, cujas peças provavelmente também foram contrabandeadas para fora do país.",
  ui_story_5070_50700402_30_dialog_content = "Também encontrei uma boa quantidade de carga com a marca da Lin Guild misturada com as feras mecânicas.",
  ui_story_5070_50700402_31_dialog_content = "Como um ilustre associado da Família Lin, certamente você deve saber algo sobre isso, não é?",
  ui_story_5070_50700402_32_dialog_content = "Seria tão gentil em explicar?",
  ui_story_5070_50700402_33_dialog_content = "...",
  ui_story_5070_50700402_34_dialog_content = "É verdade. Um navio mercante da Família Lin realmente transportou mercadorias contrabandeadas.",
  ui_story_5070_50700402_35_dialog_content = "(Como essa pessoa Telema pode ser tão teimosa? Não importa o quanto Dantang tente, ela não parece estar chegando a lugar algum.)",
  ui_story_5070_50700402_36_dialog_content = "(O que vai acontecer com a missão dela se isso continuar?)",
  ui_story_5070_50700402_37_dialog_content = "... Entendo.",
  ui_story_5070_50700402_38_dialog_content = "Respeitarei e cumprirei sua decisão, Telema de Lumópolis.",
  ui_story_5070_50700402_39_dialog_content = "Que bom que você finalmente concorda comigo.",
  ui_story_5070_50700402_40_dialog_content = "Eu sempre soube que uma bela e nobre dama como você poderia simpatizar com as dificuldades dos outros.",
  ui_story_5070_50700402_41_dialog_content = "Da mesma forma, peço que você também entenda minha própria situação, Telema.",
  ui_story_5070_50700402_42_dialog_content = "Hã?",
  ui_story_5070_50700402_43_dialog_content = "PlayerName.",
  ui_story_5070_50700402_44_dialog_content = "Você estaria disposto a ocupar o lugar de Telema como emissário de Astra e retornar a Longzhou comigo?",
  ui_story_5070_50700402_45_dialog_content = "... Eu?!?",
  ui_story_5070_50700501_1_dialog_content = "N-De jeito nenhum! Como eu poderia servir como um emissário?!",
  ui_story_5070_50700501_2_dialog_content = "E por que não?",
  ui_story_5070_50700501_3_dialog_content = "Bem, para começar, eu não represento um grande poder como Lumópolis ou a Federação Illumina.",
  ui_story_5070_50700501_4_dialog_content = "Sim, mas como uma parte neutra, você não acha que está na melhor posição para representar os interesses de Astra?",
  ui_story_5070_50700501_5_dialog_content = "Além disso, suas experiências nesta terra são tão vastas quanto a rede de aliados que você construiu ao longo do tempo.",
  ui_story_5070_50700501_6_dialog_content = "Você é mais do que conhecedor dos assuntos de Astra, bem como de suas estratégias para se defender dos Eclipsitas.",
  ui_story_5070_50700501_7_dialog_content = "Isso não se alinha com nosso objetivo de estabelecer uma ponte de comunicação entre nossos dois continentes?",
  ui_story_5070_50700501_8_dialog_content = "Mas isso é...",
  ui_story_5070_50700501_9_dialog_content = "Concordo!!",
  ui_story_5070_50700501_10_dialog_content = "PlayerName é famoso em Astra! Eu só ouvi elogios sobre ele, mesmo antes de termos a chance de nos conhecer!",
  ui_story_5070_50700501_11_dialog_content = "Como representante oficial de Lumópolis, estou disposto a colocar as responsabilidades desta missão diplomática para Longzhou em suas mãos!",
  ui_story_5070_50700501_12_dialog_content = "E-Espera... Ainda preciso pensar nisso!",
  ui_story_5070_50700501_13_dialog_content = "(Lumópolis, hein... Carleen disse que sempre apoiou essa troca. Tenho certeza de que ela ficaria desapontada se não desse certo.)",
  ui_story_5070_50700501_14_dialog_content = "(Dantang e seus aliados também têm enfrentado todos os tipos de problemas desde que chegaram em Astra.)",
  ui_story_5070_50700501_15_dialog_content = "(Muitas pessoas estão depositando suas esperanças nesta missão, já que envolve o futuro de dois continentes. Se eu sou a única pessoa para o trabalho no momento, então...)",
  ui_story_5070_50700501_16_dialog_content = "Vou tentar o meu melhor.",
  ui_story_5070_50700501_17_dialog_content = "PlayerName... Estou tão feliz em ouvir isso!!!",
  ui_story_5070_50700501_18_dialog_content = "Tem certeza disso?",
  ui_story_5070_50700501_19_dialog_content = "Capitão Yuebai? Então você também ouviu tudo?",
  ui_story_5070_50700501_20_dialog_content = "Você pode simplesmente me chamar de Yuebai.",
  ui_story_5070_50700501_21_dialog_content = "Já que está decidido, então como capitão do Shadowind...",
  ui_story_5070_50700501_22_dialog_content = "Dou as boas-vindas a PlayerName como o emissário de todo o Astra.",
  ui_story_5070_50700501_23_dialog_content = "A viagem será traiçoeira, então esteja preparado tanto fisicamente quanto psicologicamente para ela.",
  ui_story_5070_50700501_24_dialog_content = "Sim, eu sei.",
  ui_story_5070_50700501_25_dialog_content = "Espere, Capitão Yuebai... Quero dizer, Yuebai. Posso incomodá-lo por um minuto?",
  ui_story_5070_50700501_26_dialog_content = "Você vê, um amigo meu me pediu para perguntar a você sobre a Família Lin.",
  ui_story_5070_50700501_27_dialog_content = "É verdade. Um navio mercante da Família Lin realmente transportou mercadorias contrabandeadas.",
  ui_story_5070_50700501_28_dialog_content = "Por que você está contando tudo isso para ela, Zhong Xu?!",
  ui_story_5070_50700501_29_dialog_content = "Ela apareceu na nossa porta com um monte de acusações mal formuladas! Apenas diga algumas palavras e mande-a embora!",
  ui_story_5070_50700501_30_dialog_content = "Eu ouvi isso, sabe!",
  ui_story_5070_50700501_31_dialog_content = "Mas falar sobre essas coisas tão abertamente... Não me diga que pretende lutar comigo, Sr. Zhong Xu?",
  ui_story_5070_50700501_32_dialog_content = "Não tenho intenção de fazer isso.",
  ui_story_5070_50700501_33_dialog_content = "Mas se uma única frase foi suficiente para fazer você hesitar, Ministra Armilla...",
  ui_story_5070_50700501_34_dialog_content = "Então talvez você não tenha paciência para ouvir o resto da verdade.",
  ui_story_5070_50700501_35_dialog_content = "Ah?",
  ui_story_5070_50700501_36_dialog_content = "Então você só está disposto a compartilhar seu conhecimento com aqueles que estão dispostos a ouvir? É isso?",
  ui_story_5070_50700501_37_dialog_content = "De nada, minha senhora.",
  ui_story_5070_50700501_38_dialog_content = "Eu simplesmente quero dizer que estou com a saúde debilitada e me canso muito facilmente. Por isso, achei melhor te dar uma resposta concisa agora.",
  ui_story_5070_50700501_39_dialog_content = "Entendi. Então, por favor, me conte a versão longa da história.",
  ui_story_5070_50700501_40_dialog_content = "Afinal, seria rude da minha parte não ouvir quando você está sendo tão honesto comigo, Sr. Zhong Xu.",
  ui_story_5070_50700501_41_dialog_content = "Heh, então você está disposto a ouvir os outros de vez em quando.",
  ui_story_5070_50700501_42_dialog_content = "Isso é porque eu sou um adulto, pequeno.",
  ui_story_5070_50700501_43_dialog_content = "Pare de me chamar assim! Entenda isso de uma vez por todas!",
  ui_story_5070_50700501_44_dialog_content = "Então, o que exatamente o navio mercante da família Lin encontrou no mar meio ano atrás?",
  ui_story_5070_50700501_45_dialog_content = "Piratas.",
  ui_story_5070_50700501_46_dialog_content = "Como de costume, os navios da Família Lin partem do Reino Ji no início do trimestre.",
  ui_story_5070_50700501_47_dialog_content = "Mas ao entrarem nas águas de Astra, a tripulação descobriu um carregamento de mercadorias não identificadas e não registradas escondidas no porão de carga.",
  ui_story_5070_50700501_48_dialog_content = "Logo depois, um número de piratas foi descoberto entre os passageiros do navio.",
  ui_story_5070_50700501_49_dialog_content = "Então, eles estavam usando o navio da Família Lin para contrabandear produtos ilegais?",
  ui_story_5070_50700501_50_dialog_content = "Exatamente.",
  ui_story_5070_50700501_51_dialog_content = "Mas o plano deles foi descoberto ao longo do caminho, então os piratas recorreram à violência para sequestrar o navio mercante.",
  ui_story_5070_50700501_52_dialog_content = "No final, os únicos dois sobreviventes foram Liqing, que atuava como médico do navio na época, e eu mesmo.",
  ui_story_5070_50700501_53_dialog_content = "Zhong Xu também caiu ao mar depois de ficar gravemente ferido. Ele quase não conseguiu.",
  ui_story_5070_50700501_54_dialog_content = "Usei toda minha força apenas para mantê-lo vivo, então não consegui salvar suas pernas. Foi assim que ele acabou assim.",
  ui_story_5070_50700501_55_dialog_content = "Você não tem motivo para se culpar, Liqing. Já sou eternamente grato a você por salvar minha vida.",
  ui_story_5070_50700501_56_dialog_content = "Se você está realmente agradecido, então deve me ouvir e descansar mais.",
  ui_story_5070_50700501_57_dialog_content = "Sempre que nossos visitantes indesejados aparecem à nossa porta, você sempre corre para enfrentá-los sem se preocupar consigo mesmo—",
  ui_story_5070_50700501_58_dialog_content = "Convidados indesejados?",
  ui_story_5070_50700501_59_dialog_content = "Graaah!",
  ui_story_5070_50700501_60_dialog_content = "Falando no diabo, lá estão eles de novo!",
  ui_story_5070_50700501_61_dialog_content = "Eles sempre aparecem no segundo em que paramos de prestar atenção. Isso torna comer e dormir um verdadeiro incômodo!",
  ui_story_5070_50700501_62_dialog_content = "Cheio—",
  ui_story_5070_50700501_63_dialog_content = "A Cinzas!",
  ui_story_5070_50700501_64_dialog_content = "...",
  ui_story_5070_50700501_65_dialog_content = "O que eu acabei de dizer, Zhong Xu?! É exatamente por isso que você está demorando tanto para se recuperar!",
  ui_story_5070_50700501_66_dialog_content = "O que resta da minha vida não é mais importante.",
  ui_story_5070_50700501_67_dialog_content = "Mas o Mestre da Guilda Lin...",
  ui_story_5070_50700501_68_dialog_content = "Fiz uma promessa a ele naquela época. Como eu poderia deixá-lo morrer na prisão quando ele foi preso injustamente?",
  ui_story_5070_50700501_69_dialog_content = "É por isso que eu não posso morrer. Ainda não.",
  ui_story_5070_50700501_70_dialog_content = "Juro que voltarei a Longzhou e limparei o nome dele antes de dar meu último suspiro.",
  ui_story_5070_50700501_71_dialog_content = "Sem dúvida vocês dois foram tão cautelosos comigo quando eu cheguei pela primeira vez.",
  ui_story_5070_50700501_72_dialog_content = "Você tem lutado contra essas feras mecânicas todo esse tempo?",
  ui_story_5070_50700501_73_dialog_content = "Também não faltaram mercenários ocidentais atrás de nós!",
  ui_story_5070_50700501_74_dialog_content = "Parece que esses piratas têm o apoio de poderes ainda maiores no mundo.",
  ui_story_5070_50700501_75_dialog_content = "Com tantos assassinos constantemente nos caçando, temo que esses poderes queiram nos ver enterrados nessas terras estrangeiras, junto com a verdade.",
  ui_story_5070_50700501_76_dialog_content = "Se eles tiverem sucesso, a Família Lin nunca será inocentada desses crimes falsos.",
  ui_story_5070_50700501_77_dialog_content = "Mesmo em um momento como este, tudo o que você consegue pensar é na família Lin... Eu realmente não sei se isso é bom ou ruim, Zhong Xu.",
  ui_story_5070_50700501_78_dialog_content = "Graaah!",
  ui_story_5070_50700501_79_dialog_content = "Argh! De novo não!",
  ui_story_5070_50700501_80_dialog_content = "Por favor, perdoe minha grosseria agora há pouco, Ministra Armilla. Eu não estava ciente de sua verdadeira identidade.",
  ui_story_5070_50700501_81_dialog_content = "Não desejo que você se envolva em nossos problemas, então, por favor, escape enquanto pode.",
  ui_story_5070_50700501_82_dialog_content = "Você não se preocuparia em me envolver.",
  ui_story_5070_50700501_83_dialog_content = "Se for o caso, eu sou o culpado aqui.",
  ui_story_5070_50700501_84_dialog_content = "Fui eu quem projetou essas feras mecânicas...",
  ui_story_5070_50700501_85_dialog_content = "Mas eles nunca foram feitos para serem explorados e transformados em armas por vilões se escondendo nas sombras!",
  ui_story_5070_50700501_86_dialog_content = "No começo, eu estava preocupado que não encontraria mais pistas, mas os tolos as entregaram diretamente nas minhas mãos.",
  ui_story_5070_50700501_87_dialog_content = "Sinceramente, eu deveria estar agradecendo aos dois.",
  ui_story_5070_50700501_88_dialog_content = "Você está com sorte, Sr. Zhong Xu. Parece que temos um inimigo em comum.",
  ui_story_5070_50700501_89_dialog_content = "... Então, mesmo depois de tudo isso, nunca fomos inimigos desde o início?!",
  ui_story_5070_50700501_90_dialog_content = "Nossos inimigos provavelmente riram à beça, nos vendo discutir o dia inteiro!",
  ui_story_5070_50700501_91_dialog_content = "Não fique chateado, pequenino. Depois de cuidarmos desses malvados, vou fazer todos os tipos de brinquedos divertidos para você brincar.",
  ui_story_5070_50700501_92_dialog_content = "Que tal uma bola bonita e brilhante?",
  ui_story_5070_50700501_93_dialog_content = "Também posso consertar a cadeira de rodas do Sr. Zhong Xu e adicionar algumas novas funções a ela, se você quiser?",
  ui_story_5070_50700501_94_dialog_content = "Sua boa vontade é muito apreciada.",
  ui_story_5070_50700501_95_dialog_content = "Mas essa cadeira de rodas é apenas meu meio de transporte. Não requer nenhuma modificação desnecessária.",
  ui_story_5070_50700501_96_dialog_content = "Hahaha! Você pode não ser um artesão, Sr. Zhong Xu, mas com certeza entende o verdadeiro significado do nosso ofício.",
  ui_story_5070_50700501_97_dialog_content = "E isso te torna cem vezes mais poderoso do que os covardes que manipulam toda essa conspiração.",
  ui_story_5070_50700502_1_dialog_content = "E isso... foi o que aconteceu com a Família Lin.",
  ui_story_5070_50700502_2_dialog_content = "Ouvi rumores sobre o envolvimento da Guilda Lin em um incidente de contrabando há seis meses, bem como o dano que isso causou ao nome deles. No entanto, esta é a primeira vez que me contam os detalhes do assunto.",
  ui_story_5070_50700502_3_dialog_content = "Se o que você diz é verdade, o veredicto neste caso parece bastante arbitrário.",
  ui_story_5070_50700502_4_dialog_content = "Não há prova conclusiva de que a Família Lin esteja contrabandeando, mas tudo o mais parece indicar isso.",
  ui_story_5070_50700502_5_dialog_content = "Isso, sem dúvida, coloca a Família Lin em desvantagem. Tudo o que eles podem fazer é suportar a vergonha desse crime.",
  ui_story_5070_50700502_6_dialog_content = "Isso também explica por que a família Lin estava tão determinada a enfrentar os mares, mesmo após perderem seu astrolábio.",
  ui_story_5070_50700502_7_dialog_content = "Eles estão desesperados por uma oportunidade para restabelecer suas rotas comerciais e revitalizar sua guilda.",
  ui_story_5070_50700502_8_dialog_content = "*Suspiro* A tripulação do Shadowind tem enfrentado problemas desde o começo.",
  ui_story_5070_50700502_9_dialog_content = "É por isso que eles estão tão ansiosos para zarpar e retornar a Longzhou.",
  ui_story_5070_50700502_10_dialog_content = "PlayerName.",
  ui_story_5070_50700502_11_dialog_content = "O que foi, Dantang? E por que você está com essa cara tão séria?",
  ui_story_5070_50700502_12_dialog_content = "O mar é um lugar imprevisível. Desde tempos imemoriais, inúmeros navios não conseguiram retornar em segurança de viagens tão longas quanto esta.",
  ui_story_5070_50700502_13_dialog_content = "Além das rotas marítimas em constante mudança e emboscadas inimigas, a jornada à frente estará cheia de outros perigos ocultos.",
  ui_story_5070_50700502_14_dialog_content = "Se você está disposto a embarcar no Shadowind, também deve estar disposto a se aventurar no desconhecido.",
  ui_story_5070_50700502_15_dialog_content = "Yuebai tem o dever de restaurar a Guilda Lin e eu tenho minhas próprias responsabilidades, das quais não posso abrir mão.",
  ui_story_5070_50700502_16_dialog_content = "Todos nós temos nossos motivos para enfrentar o mar e aceitamos as consequências disso.",
  ui_story_5070_50700502_17_dialog_content = "Mas você é diferente, PlayerName.",
  ui_story_5070_50700502_18_dialog_content = "... Como Princesa Zhuohua, arrastar você para nossos problemas foi a única solução que eu pude pensar naquele momento.",
  ui_story_5070_50700502_19_dialog_content = "Mas como seu amigo, Dantang... Eu me preocupo com a sua segurança.",
  ui_story_5070_50700502_20_dialog_content = "Eu entenderia completamente se você escolhesse recusar minha oferta.",
  ui_story_5070_50700502_21_dialog_content = "Sinceramente, eu não sei o que eu esperava que você dissesse.",
  ui_story_5070_50700502_22_dialog_content = "Hã?",
  ui_story_5070_50700502_23_dialog_content = "Você diz que me \"arrastou\" para os seus problemas.",
  ui_story_5070_50700502_24_dialog_content = "Mas se eu sou o enviado de Astra, ou o último dos Celestitas, ou mesmo apenas o velho e simples eu.",
  ui_story_5070_50700502_25_dialog_content = "Sempre levo essas situações em consideração cuidadosa antes de tomar qualquer decisão.",
  ui_story_5070_50700502_26_dialog_content = "E como seu amigo, naturalmente também quero te ajudar.",
  ui_story_5070_50700502_27_dialog_content = "PlayerName... Se for esse o caso, então eu juro que farei tudo ao meu alcance para proteger você nesta jornada.",
  ui_story_5070_50700502_28_dialog_content = "Eu só rezo para que não enfrentemos muitos desafios ao longo do caminho...",
  ui_story_5070_50700502_29_dialog_content = "Oh? Por que o navio ainda não partiu? E por que todos parecem estar prestes a chorar?",
  ui_story_5070_50700502_30_dialog_content = "...",
  ui_story_5070_50700502_31_dialog_content = "Apenas relaxem, pessoal! Aconteceu de eu encontrar um veterano de combate experiente e um médico lendário para trazer na viagem.",
  ui_story_5070_50700502_32_dialog_content = "E se o pior acontecer, também estarei por perto!",
  ui_story_5070_50700502_33_dialog_content = "Eu posso não ser mais um conselheiro do rei de Ye, mas enfrentaria uma montanha de lâminas e um mar de chamas se a princesa ordenasse.",
  ui_story_5070_50700502_34_dialog_content = "Sua Alteza, a Senhora Xuan Ji retornou!",
  ui_story_5070_50700502_35_dialog_content = "Sim, eu pude perceber pelo barulho que era ela.",
  ui_story_5070_50700502_36_dialog_content = "Suas palavras são tão excêntricas quanto sempre, Ministra Armilla.",
  ui_story_5070_50700502_37_dialog_content = "Cuidado, ou eu posso te colocar nesse tipo de dilema perigoso.",
  ui_story_5070_50700502_38_dialog_content = "Hahahaha! Tudo bem, chega de piadas por enquanto.",
  ui_story_5070_50700502_39_dialog_content = "Ouvi dizer que o Shadowind foi atacado mais cedo, então preciso inspecionar o casco dele mais uma vez.",
  ui_story_5070_50700502_40_dialog_content = "Nunca pensei que meus caranguejos de fogo seriam usados para atacar um navio um dia.",
  ui_story_5070_50700502_41_dialog_content = "Parece que também terei que reforçar ou modificar os sistemas de fornecimento de energia e navegação.",
  ui_story_5070_50700502_42_dialog_content = "Não se preocupe, vou fazer o meu melhor para tornar este navio o mais seguro possível antes de irmos para o mar!",
  ui_story_5070_50700601_1_dialog_content = "(Queridos Vice e Carleen.)",
  ui_story_5070_50700601_2_dialog_content = "(Desculpe pela resposta tão tardia. Num piscar de olhos, nosso dia de partida finalmente chegou.)",
  ui_story_5070_50700601_3_dialog_content = "(Estamos no meio dos preparativos finais para a viagem, então todos têm estado realmente ocupados ultimamente.)",
  ui_story_5070_50700601_4_dialog_content = "Armador Li! Peça à sua equipe para aplicar uma camada resistente ao fogo nas seções críticas do casco!",
  ui_story_5070_50700601_5_dialog_content = "Precisamos estar preparados para incêndios inesperados e também para ataques de caranguejos de fogo!",
  ui_story_5070_50700601_6_dialog_content = "Vou inspecionar o navio em busca de sinais de vazamento.",
  ui_story_5070_50700601_7_dialog_content = "Além disso, alguém sabe onde a capitã está? Preciso convencê-la a comprar mais alguns dispositivos de armazenamento de energia antes de sairmos de Astra.",
  ui_story_5070_50700601_8_dialog_content = "Qualquer coisa pode acontecer no mar, e ter reservas extras de energia nos ajudará a estar sempre preparados.",
  ui_story_5070_50700601_9_dialog_content = "Sr. Zhong Xu?",
  ui_story_5070_50700601_10_dialog_content = "Perdoe-me por não ter falado com você antes. Os últimos dias têm sido muito ocupados...",
  ui_story_5070_50700601_11_dialog_content = "Obrigado por me contar a verdade sobre o incidente de contrabando. Com essa informação, o bom nome da família Lin finalmente pode ser restaurado.",
  ui_story_5070_50700601_12_dialog_content = "Tenho certeza de que o Lin Guildmaster também ficará ainda mais encorajado com seu retorno seguro. Não deveremos ter problemas para superar esses obstáculos até lá.",
  ui_story_5070_50700601_13_dialog_content = "Estou apenas cumprindo meu dever... Afinal, fui eu quem falhou em protegê-lo.",
  ui_story_5070_50700601_14_dialog_content = "Ainda assim, não há como prever quando os piratas atacarão novamente.",
  ui_story_5070_50700601_15_dialog_content = "Durante nosso encontro seis meses atrás, consegui discernir aproximadamente o método de ataque deles.",
  ui_story_5070_50700601_16_dialog_content = "Podemos usar essas informações para formular nossas contramedidas.",
  ui_story_5070_50700601_17_dialog_content = "Sândalo, capim em pó, hortelã, araruta...",
  ui_story_5070_50700601_18_dialog_content = "Você tem essas ervas em estoque? Se sim, eu vou levar tudo que você tem!",
  ui_story_5070_50700601_19_dialog_content = "Isso é um pedido bem grande, jovem.",
  ui_story_5070_50700601_20_dialog_content = "Ei, eu não escolhi ser responsável pela saúde de uma nave inteira.",
  ui_story_5070_50700601_21_dialog_content = "Preciso estocar tudo que possa ser usado para tratar coisas como calafrios e enjoo. Quanto mais, melhor!",
  ui_story_5070_50700601_22_dialog_content = "Todos estão ocupados fazendo sei-lá-o-quê, então alguém precisa garantir que tenhamos suprimentos médicos suficientes para a viagem, certo?",
  ui_story_5070_50700601_23_dialog_content = "Agora só preciso comprar comida suficiente para manter todos em boa saúde enquanto estivermos no mar!",
  ui_story_5070_50700601_24_dialog_content = "Já terminou de escrever suas cartas de despedida, Jiu?",
  ui_story_5070_50700601_25_dialog_content = "Sim, Sua Alteza. Na verdade, eu não preciso me despedir de muitas pessoas.",
  ui_story_5070_50700601_26_dialog_content = "Mas você realmente precisa enviar tantas cartas assim?",
  ui_story_5070_50700601_27_dialog_content = "Fizemos muitos amigos e conhecemos várias pessoas importantes durante nosso tempo aqui, afinal.",
  ui_story_5070_50700601_28_dialog_content = "Devemos manter nossas boas relações se quisermos trabalhar juntos no futuro.",
  ui_story_5070_50700601_29_dialog_content = "Isso me lembra que ainda preciso escrever uma carta para a Associação de Guildas de Twin Pavilions Bay.",
  ui_story_5070_50700601_30_dialog_content = "Cúmplices de piratas apareceram na cidade e precisam ser capturados o mais rápido possível.",
  ui_story_5070_50700601_31_dialog_content = "(Mesmo eu tive que fazer algumas viagens a Umbraton para ajudar todos a comprar coisas que só podem ser encontradas em Astra.)",
  ui_story_5070_50700601_32_dialog_content = "(Honestamente, isso me fez sentir muito mais como um verdadeiro emissário de Astra.)",
  ui_story_5070_50700601_33_dialog_content = "(Uma vez que eu enviar esta carta, o Shadowind zarpará logo em seguida.)",
  ui_story_5070_50700601_34_dialog_content = "(Espero corresponder às expectativas de todos e completar minha missão sem muitos problemas.)",
  ui_story_5070_50700601_35_dialog_content = "(Quando eu voltar, com certeza trarei muitas histórias de Longzhou para todos ouvirem!)",
  ui_story_5070_50700601_36_dialog_content = "Bem, se não é PlayerName!",
  ui_story_5070_50700601_37_dialog_content = "Ei, você é aquele vidente de antes!",
  ui_story_5070_50700601_38_dialog_content = "Sem mais uma palavra, meu amigo! Meus poderes de adivinhação me dizem que você acabou de enviar uma carta. Estou certo?",
  ui_story_5070_50700601_39_dialog_content = "...",
  ui_story_5070_50700601_40_dialog_content = "Do que você está falando? Você claramente acabou de me ver sair da Courier Union.",
  ui_story_5070_50700601_41_dialog_content = "Heheh, estou só brincando.",
  ui_story_5070_50700601_42_dialog_content = "Assim como você, também sou um passageiro a bordo do Shadowind.",
  ui_story_5070_50700601_43_dialog_content = "Gostaria de voltar ao navio comigo?",
  ui_story_5070_50700601_44_dialog_content = "Acho que não. Você também estava enviando uma carta?",
  ui_story_5070_50700601_45_dialog_content = "É melhor não discutirmos isso.",
  ui_story_5070_50700601_46_dialog_content = "Eu queria saborear uma última refeição em Astra antes de voltar para casa, mas não tive muita sorte hoje.",
  ui_story_5070_50700601_47_dialog_content = "Apesar de ter andado pela cidade por meio dia, não tive a sorte de encontrar pessoas ricas.",
  ui_story_5070_50700601_48_dialog_content = "Uma pena, realmente.",
  ui_story_5070_50700601_49_dialog_content = "O que pessoas ricas têm a ver com você comendo uma refeição?",
  ui_story_5070_50700601_50_dialog_content = "Você pode não estar ciente disso, mas apesar da minha aparência simples...",
  ui_story_5070_50700601_51_dialog_content = "Na verdade, sou ainda mais pobre do que pareço. Na verdade, não tenho um único Nightium no meu nome!",
  ui_story_5070_50700601_52_dialog_content = "E você... escolheu viajar o mundo mesmo assim?",
  ui_story_5070_50700601_53_dialog_content = "Bem, eu sou bastante diferente dos outros passageiros. Não tenho nenhum motivo especial para falar, propriamente dito.",
  ui_story_5070_50700601_54_dialog_content = "Minha curiosidade em conhecer terras distantes é o que me impulsiona a viajar. Para mim, a jornada é o que mais aprecio.",
  ui_story_5070_50700601_55_dialog_content = "Não faz diferença se estou viajando para outro continente ou para o outro lado de um lago.",
  ui_story_5070_50700601_56_dialog_content = "... Está bem então.",
  ui_story_5070_50700601_57_dialog_content = "(Mesmo entendendo muito pouco do que ele disse, de alguma forma faz sentido.)",
  ui_story_5070_50700601_58_dialog_content = "Você me acha um pouco prolixo, não é, meu amigo?",
  ui_story_5070_50700601_59_dialog_content = "Então, por que não te dou uma adivinhação sincera e verdadeira?",
  ui_story_5070_50700601_60_dialog_content = "Minha Adivinhação do Hexagrama Celestial inclui ratos, bois, tigres, coelhos e todos os outros animais do zodíaco, dividindo-os em yin e yang.",
  ui_story_5070_50700601_61_dialog_content = "Com isso, posso discernir os próprios segredos dos céus e prever o futuro. Não posso garantir que você terá outra oportunidade como essa!",
  ui_story_5070_50700601_62_dialog_content = "Ratos e bois? Mas esses não são apenas animais? O que eles podem mostrar para você?",
  ui_story_5070_50700601_63_dialog_content = "Uma riqueza de conhecimento, meu amigo.",
  ui_story_5070_50700601_64_dialog_content = "Vamos usar o Shadowind como exemplo. Vamos, podemos caminhar enquanto conversamos.",
  ui_story_5070_50700601_65_dialog_content = "Você está ciente de que os doze animais do zodíaco estão a bordo do navio?",
  ui_story_5070_50700601_66_dialog_content = "Bem, ratos em um navio não são novidade, mas ainda não vi nenhum boi.",
  ui_story_5070_50700601_67_dialog_content = "As pessoas de Longzhou são muito específicas sobre imagens. Na verdade, certas coisas são nomeadas com base nas imagens que se assemelham.",
  ui_story_5070_50700601_68_dialog_content = "Vê aquela cunha usada para estabilizar o mastro do navio? Em nossas terras, é conhecida como \"ponte do rato.\"",
  ui_story_5070_50700601_69_dialog_content = "E as grades de proteção ao longo das bordas do convés? Essas são chamadas de \"cercas de boi\".",
  ui_story_5070_50700601_70_dialog_content = "As tábuas no convés são chamadas de \"faces de cavalo\", enquanto a estrutura do navio é chamada de \"esqueleto do dragão\". Preciso explicar mais?",
  ui_story_5070_50700601_71_dialog_content = "Não percebi que eles tinham nomes tão criativos.",
  ui_story_5070_50700601_72_dialog_content = "De fato, e assim como este navio, meus hexagramas ecoam toda a existência, permitindo-me ver o futuro.",
  ui_story_5070_50700601_73_dialog_content = "Então você consegue ver o que vai acontecer com este navio durante nossa viagem?",
  ui_story_5070_50700601_74_dialog_content = "De novo... É melhor você não perguntar. Apenas saiba que eu também fiz uma previsão quando o Shadowind foi atacado anteriormente.",
  ui_story_5070_50700601_75_dialog_content = "O resultado foi o boi yin e o cavalo yin.",
  ui_story_5070_50700601_X75_dialog_content = "\"O boi morto não se mexe e o cavalo morto não relincha.\" A princípio, eu entendi que isso significava que o navio não conseguiria sair do porto...",
  ui_story_5070_50700601_76_dialog_content = "Mas o Shadowind está prestes a partir!",
  ui_story_5070_50700601_77_dialog_content = "De fato, isso significa que minha previsão requer uma interpretação mais aprofundada. Talvez eu possa obter mais inspiração a partir dos rostos de cavalo e cercas de boi a bordo do navio?",
  ui_story_5070_50700601_78_dialog_content = "É sábio não ouvir os delírios de um mentiroso, PlayerName.",
  ui_story_5070_50700601_79_dialog_content = "Vamos lá, Sua Alteza. Minha arte é apenas um meio para me sustentar, nada mais.",
  ui_story_5070_50700601_80_dialog_content = "Não ligue para ele, PlayerName. A maioria dos passageiros já está no navio, então por favor, embarque.",
  ui_story_5070_50700601_81_dialog_content = "... Permita-me verificar a lista de passageiros uma última vez.",
  ui_story_5070_50700601_82_dialog_content = "Sr. Zhong Xu, Doutor Liqing, Princesa Dantang, Srta. Jiu e PlayerName.",
  ui_story_5070_50700601_83_dialog_content = "Li, Sun e Senhora Xuan Ji também se juntarão à nossa viagem para Longzhou como técnicos do Shadowind.",
  ui_story_5070_50700601_84_dialog_content = "Todos estão presentes e contabilizados agora.",
  ui_story_5070_50700601_85_dialog_content = "...",
  ui_story_5070_50700601_86_dialog_content = "Como capitão do navio, eu deveria ser a última pessoa a aumentar as preocupações dos passageiros.",
  ui_story_5070_50700601_87_dialog_content = "Mas, devido às circunstâncias especiais de nossa viagem, sinto que devo deixar algo muito claro para todos.",
  ui_story_5070_50700601_88_dialog_content = "Sem a nossa esfera armilar, a localização do Shadowind não pode ser determinada enquanto navegamos pelos altos mares.",
  ui_story_5070_50700601_89_dialog_content = "Cabe a nós determinar o rumo do navio.",
  ui_story_5070_50700601_90_dialog_content = "Tempestades repentinas, cruéis Eclipsitas e até inimigos invisíveis também devem ser esperados lá fora.",
  ui_story_5070_50700601_91_dialog_content = "Os perigos que nos aguardam serão muito maiores do que qualquer coisa que enfrentamos em viagens anteriores.",
  ui_story_5070_50700601_92_dialog_content = "Se alguém deseja sair do navio, agora é a hora de fazê-lo.",
  ui_story_5070_50700601_93_dialog_content = "(Como esperado, ninguém está mexendo um músculo. Todos estão determinados a fazer a viagem de volta.)",
  ui_story_5070_50700601_94_dialog_content = "Já que todos vocês escolheram confiar no Shadowind, então, como capitão do navio, eu juro levar-nos com segurança às margens de Longzhou.",
  ui_story_5070_50700601_95_dialog_content = "O Shadowind zarpa agora!",
  ui_story_5070_50700701_1_dialog_content = "<color=#e8d9bb>Respingo... Respingo...</color>",
  ui_story_5070_50700701_2_dialog_content = "(Já faz alguns dias desde que partimos. Esta é a primeira vez que saio de Astra de navio.)",
  ui_story_5070_50700701_3_dialog_content = "(O céu azul, ondas rolando, brisa refrescante do mar e um destino desconhecido... Além de um pouco de solidão.)",
  ui_story_5070_50700701_4_dialog_content = "Você está tão fixado. O que está em sua mente?",
  ui_story_5070_50700701_5_dialog_content = "Ah, Xuan Ji!",
  ui_story_5070_50700701_6_dialog_content = "Eu estava pensando que a sensação de atravessar o oceano de navio é totalmente diferente de andar em um Colossus.",
  ui_story_5070_50700701_7_dialog_content = "Ah? Como está no Colosso?",
  ui_story_5070_50700701_8_dialog_content = "É raro você mencionar esse assunto. De modo geral, a Colossus é uma máquina, certo?",
  ui_story_5070_50700701_9_dialog_content = "Não é um pouco amplo?",
  ui_story_5070_50700701_10_dialog_content = "Esse não é o ponto.",
  ui_story_5070_50700701_11_dialog_content = "O ponto é, você realmente consegue controlar aquele gigante maior que o Shadowind sozinho?",
  ui_story_5070_50700701_12_dialog_content = "Quão rápido é? Qual o consumo de combustível? Como os materiais lidam com as mudanças de estações?",
  ui_story_5070_50700701_13_dialog_content = "Como uma máquina voadora, além da propulsão, sua forma também afeta a aerodinâmica e a sustentação...",
  ui_story_5070_50700701_14_dialog_content = "Você nunca me explicou bem isso antes.",
  ui_story_5070_50700701_15_dialog_content = "E-Espere um segundo... Eu acabei de abrir uma caixa de Pandora...?",
  ui_story_5070_50700701_16_dialog_content = "Bem, se é confidencial, devemos mantê-lo assim!",
  ui_story_5070_50700701_17_dialog_content = "Não é confidencial. Apenas que, mesmo eu não consigo oferecer uma resposta adequada para algumas perguntas.",
  ui_story_5070_50700701_18_dialog_content = "Pense nisso! O corrimão, o leme, o mastro do Shadowind...",
  ui_story_5070_50700701_19_dialog_content = "Yuebai e sua equipe precisam lidar com tudo no navio manualmente.",
  ui_story_5070_50700701_20_dialog_content = "Se houver alguma mudança na velocidade ou direção do vento, eles devem decidir como modificar o navio imediatamente.",
  ui_story_5070_50700701_21_dialog_content = "Mas as informações em seu banco de dados permitem que o Soroz lide com todos esses tipos de coisas.",
  ui_story_5070_50700701_22_dialog_content = "É apenas em momentos críticos que preciso guiá-lo com palavras ou melodias.",
  ui_story_5070_50700701_23_dialog_content = "Então, vai além do simples controle, permitindo que ele execute rotinas lógicas e apenas execute comandos.",
  ui_story_5070_50700701_24_dialog_content = "Isso é como um mito se tornando realidade.",
  ui_story_5070_50700701_25_dialog_content = "Mito? Longzhou?",
  ui_story_5070_50700701_26_dialog_content = "Correto. Livros de história antiga falavam sobre gênios tão grandes que podiam bloquear o sol.",
  ui_story_5070_50700701_27_dialog_content = "Operado por pessoas chamadas \"Atendentes de Djinn\" para atravessar a terra e o mar em conquistas.",
  ui_story_5070_50700701_28_dialog_content = "Uau, isso é incrível... Soroz não consegue bloquear o sol.",
  ui_story_5070_50700701_29_dialog_content = "Por mais alto que você voe, o céu e a lua sempre parecem estar fora de alcance...",
  ui_story_5070_50700701_30_dialog_content = "Não tenho certeza sobre isso.",
  ui_story_5070_50700701_31_dialog_content = "Hã?",
  ui_story_5070_50700701_32_dialog_content = "Subi no convés para medir a altitude do sol.",
  ui_story_5070_50700701_33_dialog_content = "Isso não é o nome de algo, é? O sol acima de nós?",
  ui_story_5070_50700701_34_dialog_content = "Há uma antiga escola de astrologia em Longzhou.",
  ui_story_5070_50700701_35_dialog_content = "Tudo que você precisa é de um astrolábio para calcular a distância entre o sol, a lua ou até mesmo duas estrelas.",
  ui_story_5070_50700701_36_dialog_content = "Considerando que podemos calcular a altitude e a trajetória...",
  ui_story_5070_50700701_37_dialog_content = "Não será difícil ajustar a estrutura da sua Colossus para bloquear o sol!",
  ui_story_5070_50700701_38_dialog_content = "É obviamente um exagero, mas vindo de você, não soou como uma piada...",
  ui_story_5070_50700701_39_dialog_content = "Então serei grato pela sua confiança em mim.",
  ui_story_5070_50700701_40_dialog_content = "Mas eu conheço o princípio de que devagar se vai ao longe, construindo um dispositivo uma peça de cada vez.",
  ui_story_5070_50700701_41_dialog_content = "Embora não possamos chegar lá agora...",
  ui_story_5070_50700701_42_dialog_content = "Mas ainda podemos fazer muito sabendo a posição, ângulo e outros dados do sol.",
  ui_story_5070_50700701_43_dialog_content = "Como complementar os mapas de Lin para descobrir as coordenadas atuais do Shadowind.",
  ui_story_5070_50700701_44_dialog_content = "Enquanto você estiver sempre ciente de sua posição, nunca se perderá no mar!",
  ui_story_5070_50700701_45_dialog_content = "Mais fácil falar do que fazer. O mar é muito imprevisível para que estimativas artificiais permaneçam consistentes e precisas.",
  ui_story_5070_50700701_46_dialog_content = "É por isso que o esfera armilar, capaz de mostrar constelações e localizações precisas, é valorizada como o tesouro dos Lins.",
  ui_story_5070_50700701_47_dialog_content = "Isso torna impossível até mesmo desviar intencionalmente um navio do curso com um astrônomo competente a bordo.",
  ui_story_5070_50700701_48_dialog_content = "Que pena, no entanto...",
  ui_story_5070_50700701_49_dialog_content = "Esfera armilar... Eu me lembro que estava naquele navio da Família Lin que foi sequestrado por piratas, desaparecendo junto com o navio.",
  ui_story_5070_50700701_50_dialog_content = "Sim, é por isso que estou preenchendo.",
  ui_story_5070_50700701_51_dialog_content = "Tudo foi feito por aparelhos no passado, então é chocante ver um artesão substituindo a máquina.",
  ui_story_5070_50700701_52_dialog_content = "Mas, dessa forma, Xuan Ji também pode ser considerado o navegador do Shadowind.",
  ui_story_5070_50700701_53_dialog_content = "Apenas temporariamente.",
  ui_story_5070_50700701_54_dialog_content = "Não se menospreze, Ministra Armilla.",
  ui_story_5070_50700701_55_dialog_content = "O nome Xuan Ji significa Armilla, que é outro nome para a esfera armilar.",
  ui_story_5070_50700701_56_dialog_content = "Armilla é o título perfeito para você.",
  ui_story_5070_50700701_57_dialog_content = "É apropriado, então, que Xuan Ji substitua a esfera.",
  ui_story_5070_50700701_58_dialog_content = "Estou imaginando coisas? Como pode parecer que Xuan Ji não estava fazendo um trabalho adequado antes?",
  ui_story_5070_50700701_59_dialog_content = "Um conselheiro-chave deixa um cargo vital sem permissão, deixando apenas uma carta para trás.",
  ui_story_5070_50700701_60_dialog_content = "Uma proeminente artesã renomada abandonando sua oficina e uma infinidade de itens maravilhosos, a favor de viajar sozinha com apenas um guarda-sol na mão.",
  ui_story_5070_50700701_61_dialog_content = "Como explicaria a propriedade disso, Ministra Armilla?",
  ui_story_5070_50700701_62_dialog_content = "Sua Alteza...",
  ui_story_5070_50700701_63_dialog_content = "Sua Alteza, tenho certeza de que a Senhora Xuan Ji tem seus motivos.",
  ui_story_5070_50700701_64_dialog_content = "...",
  ui_story_5070_50700701_65_dialog_content = "Vamos, não é tão complicado assim.",
  ui_story_5070_50700701_66_dialog_content = "Um rascunho de projeto foi roubado e minha escola acabou me pedindo para recuperar um artefato do Astra.",
  ui_story_5070_50700701_67_dialog_content = "Aconteceu tão rápido que não tive tempo de me despedir direito.",
  ui_story_5070_50700701_68_dialog_content = "Você não está brava ainda porque eu me recusei a te ensinar sobre aparelhos, não é, Princesa?",
  ui_story_5070_50700701_69_dialog_content = "Eu era jovem e estúpido naquela época, então por que não me perdoa, Alteza?",
  ui_story_5070_50700701_70_dialog_content = "O que você quer dizer com \"naquela época\"? Eu não vejo isso mudando...",
  ui_story_5070_50700701_71_dialog_content = "Pff—Ah, desculpe.",
  ui_story_5070_50700701_72_dialog_content = "É raro ver Dantang com esse tipo de expressão. Parece que estou vendo um lado diferente do habitual.",
  ui_story_5070_50700701_73_dialog_content = "Nossa, você também...",
  ui_story_5070_50700701_74_dialog_content = "Perdoe-me, por favor, desculpe minha gafe.",
  ui_story_5070_50700701_75_dialog_content = "Este não é o momento nem o lugar para eu bater papo.",
  ui_story_5070_50700701_76_dialog_content = "Ministra Armilla é encarregada das funções de navegação...",
  ui_story_5070_50700701_77_dialog_content = "Mas como convidado, você tomou a iniciativa de explorar a superfície do oceano, PlayerName.",
  ui_story_5070_50700701_78_dialog_content = "Já me sinto envergonhado e culpado o suficiente, quanto mais interromper vocês dois.",
  ui_story_5070_50700701_79_dialog_content = "Não se preocupe. Afinal, eu posso sentir a aproximação dos Eclipsitas, então aceitar essa tarefa...",
  ui_story_5070_50700701_80_dialog_content = "Espere!",
  ui_story_5070_50700701_81_dialog_content = "Você pode não querer se intrometer, princesa.",
  ui_story_5070_50700701_82_dialog_content = "Mas certas coisas lá fora não são tão educadas quanto você.",
  ui_story_5070_50700701_83_dialog_content = "Eles estão vindo incomodar PlayerName neste exato momento.",
  ui_story_5070_50700702_1_dialog_content = "Ufa, finalmente resolvido! Eu não esperava que tantos Eclipsitas aparecessem de repente.",
  ui_story_5070_50700702_2_dialog_content = "Na verdade, isso é um bom presságio.",
  ui_story_5070_50700702_3_dialog_content = "Eclipsitas ativos são boas notícias?!",
  ui_story_5070_50700702_4_dialog_content = "Isso significa que estamos perto o suficiente de Astra, onde os Eclipsitas vagam.",
  ui_story_5070_50700702_5_dialog_content = "Instrumentos não mentem, mas o mesmo não se pode dizer dos nossos olhos.",
  ui_story_5070_50700702_6_dialog_content = "De acordo com os cálculos, deveríamos estar perto de Astra, mas é difícil verificar isso no vasto mar.",
  ui_story_5070_50700702_7_dialog_content = "Eles se jogando em nossa direção prova que estamos no caminho certo.",
  ui_story_5070_50700702_8_dialog_content = "Eles não apenas se sacrificaram, mas também me ofereceram provas.",
  ui_story_5070_50700702_9_dialog_content = "Matei-os com absoluta gratidão em mente.",
  ui_story_5070_50700702_10_dialog_content = "Não faço ideia de como os Eclipsitas se sentirão ao ouvir seus pensamentos...",
  ui_story_5070_50700702_11_dialog_content = "Já que os cálculos estão corretos, isso significa que o Shadowind está no rumo certo.",
  ui_story_5070_50700702_12_dialog_content = "O vento está empurrando o navio do ângulo certo, então podemos economizar combustível.",
  ui_story_5070_50700702_13_dialog_content = "Vá trabalhar, Sol Habilidoso!",
  ui_story_5070_50700702_14_dialog_content = "... Embora seja o que a Senhora Xuan Ji disse, devemos ficar de guarda, já que esses espíritos malignos simplesmente não desistem.",
  ui_story_5070_50700702_15_dialog_content = "Alteza, por favor, fique perto de mim.",
  ui_story_5070_50700702_16_dialog_content = "Espíritos maliciosos são muito mais comuns em Astra do que em Longzhou.",
  ui_story_5070_50700702_17_dialog_content = "Espírito maligno? Já ouvi isso antes, é o termo usado em Longzhou?",
  ui_story_5070_50700702_18_dialog_content = "De fato. As criaturas chamadas Eclipsitas em Astra são chamadas de espíritos malignos em Longzhou.",
  ui_story_5070_50700702_19_dialog_content = "Sr. Zhong Xu...",
  ui_story_5070_50700702_20_dialog_content = "Tudo bem não descansar na cabine? Eu acabei de ver Liqing gritando para você trazer remédio.",
  ui_story_5070_50700702_21_dialog_content = "Liqing sempre se dedicou de coração ao tratamento de seus pacientes.",
  ui_story_5070_50700702_22_dialog_content = "Embora eu não possa mais caminhar, ainda posso usar minha espada, então ficarei bem.",
  ui_story_5070_50700702_23_dialog_content = "...",
  ui_story_5070_50700702_24_dialog_content = "Zhong Xu... Senhor.",
  ui_story_5070_50700702_25_dialog_content = "Princesa Dantang, você não precisa ser tão cuidadosa perto de um vagabundo como eu. Todos vocês deveriam relaxar um pouco.",
  ui_story_5070_50700702_26_dialog_content = "Jovem amigo, você deveria descansar e deixar o dever de vigia comigo.",
  ui_story_5070_50700702_27_dialog_content = "Eh? Não se preocupe comigo, já que essas águas são tão perigosas, é sempre bom ter mais pessoas de guarda.",
  ui_story_5070_50700702_28_dialog_content = "Obrigado pela sua vigilância. As coisas vão melhorar na costa de Longzhou.",
  ui_story_5070_50700702_29_dialog_content = "Afinal, essas criaturas das trevas são muito menos ativas em Longzhou do que em Astra.",
  ui_story_5070_50700702_30_dialog_content = "O império organiza um grande ritual regularmente para suprimir os espíritos malignos. Os reinos vassalos também têm suas próprias maneiras de lidar com eles.",
  ui_story_5070_50700702_31_dialog_content = "Os espíritos malignos geralmente se escondem nas montanhas, aparecendo apenas quando sua sobrevivência está em risco para capturar aqueles que estão viajando sozinhos.",
  ui_story_5070_50700702_32_dialog_content = "Você provavelmente não está ciente de que os espíritos malignos em muitos lugares têm estado inquietos nos últimos meses.",
  ui_story_5070_50700702_33_dialog_content = "Ataques a civis estão ocorrendo com maior frequência. Alguns desses monstros até infiltraram-se nas cidades e causaram estragos.",
  ui_story_5070_50700702_34_dialog_content = "As defesas dos diversos estados responderam incansavelmente, mas em vão.",
  ui_story_5070_50700702_35_dialog_content = "Agora, as pessoas vivem com medo, sem saber se é o demônio ou outros elementos...",
  ui_story_5070_50700702_36_dialog_content = "Você não gosta de Fiendlings?",
  ui_story_5070_50700702_37_dialog_content = "O quê? Não, eu só estou preocupado, só isso...",
  ui_story_5070_50700702_38_dialog_content = "Espere, o que é um Diabólico?",
  ui_story_5070_50700702_39_dialog_content = "Você cresceu em Astra, então o nome é desconhecido para você. Eles são semelhantes aos semi-humanos de Astra.",
  ui_story_5070_50700702_40_dialog_content = "A única diferença é que os semi-humanos naturalmente possuem características animais.",
  ui_story_5070_50700702_41_dialog_content = "Enquanto os Fiendlings adquiriram suas formas semi-humanas após aprenderem as Artes da Força.",
  ui_story_5070_50700702_42_dialog_content = "Alguns se sentem enojados com os Fiendlings, mas outros gostam deles por causa de suas habilidades e pelo que representam.",
  ui_story_5070_50700702_43_dialog_content = "Por exemplo, os navegantes estão ansiosos para abrir suas portas para qualquer Fiendling em forma de peixe dócil que apareça.",
  ui_story_5070_50700702_44_dialog_content = "... Embora eu tenha tido muitas aventuras no mar, não me dou bem com peixes, então nunca receberei suas bênçãos.",
  ui_story_5070_50700702_45_dialog_content = "Peixes grandes são perigosos, então espero que não encontremos nenhum.",
  ui_story_5070_50700702_46_dialog_content = "Ah, entendi.",
  ui_story_5070_50700702_47_dialog_content = "É como no Astra, onde algumas pessoas acreditam que certos animais trazem boa sorte, enquanto outros anunciam a desgraça.",
  ui_story_5070_50700702_48_dialog_content = "Exatamente, mas a afirmação de que os Fiendlings concedem bênçãos não é totalmente infundada.",
  ui_story_5070_50700702_49_dialog_content = "No passado, alguns Fiendlings protegeram ativamente a paz em certas áreas após aperfeiçoarem suas formas semi-humanas.",
  ui_story_5070_50700702_50_dialog_content = "Até mesmo o tribunal imperial estava disposto a reconhecê-los com decretos imperiais e permitiu que o povo construísse templos para adorá-los.",
  ui_story_5070_50700702_51_dialog_content = "Uau, não sei se terei a chance de ver esses Fiendlings.",
  ui_story_5070_50700702_52_dialog_content = "Você sabe muito sobre isso, Zhong Xu.",
  ui_story_5070_50700702_53_dialog_content = "Seja banindo demônios ou realizando rituais...",
  ui_story_5070_50700702_54_dialog_content = "Ninguém a bordo pode rivalizar com ele em termos de conhecimento e experiência.",
  ui_story_5070_50700702_55_dialog_content = "Você pode perguntar ao Sir Zhong Xu se deseja saber mais alguma coisa, PlayerName.",
  ui_story_5070_50700702_56_dialog_content = "Espero apenas que os espíritos malignos no mar ajam lentamente, para nos dar tempo de nos coordenar.",
  ui_story_5070_50700702_57_dialog_content = "(É uma pena que os Eclipsitas não fossem tão inteligentes, pois levou várias batalhas até finalmente conseguirmos passar pela área.)",
  ui_story_5070_50700702_58_dialog_content = "(Eu ainda não percebi.)",
  ui_story_5070_50700702_59_dialog_content = "(Mas os Eclipsitas estavam longe de ser os únicos perigos no oceano.)",
  ui_story_5070_50700801_1_dialog_content = "<color=#e8d9bb>Estrondo-!</color>",
  ui_story_5070_50700801_2_dialog_content = "<color=#e8d9bb>Respingo—!</color>",
  ui_story_5070_50700801_3_dialog_content = "PlayerName! PlayerName! Acorda!",
  ui_story_5070_50700801_4_dialog_content = "Ah... Xuan Ji?",
  ui_story_5070_50700801_5_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5070_50700801_6_dialog_content = "Nossa... Qual é o problema?",
  ui_story_5070_50700801_7_dialog_content = "O fogo está se espalhando rápido! Rápido, tragam essas bolsas de água para cá!",
  ui_story_5070_50700801_8_dialog_content = "Ah! A evacuação não terminou! Pare de empurrar! Não se amontoe na cabine!",
  ui_story_5070_50700801_9_dialog_content = "Cale a boca! Proteja o cofre de combustível; se pegar fogo aqui, estamos acabados!",
  ui_story_5070_50700801_10_dialog_content = "Que tumulto... O que está acontecendo no navio?",
  ui_story_5070_50700801_11_dialog_content = "Entramos no mar distante há pouco tempo, onde o clima se tornou cada vez mais imprevisível.",
  ui_story_5070_50700801_12_dialog_content = "A sorte também não está do nosso lado. Pegamos o palito mais curto possível.",
  ui_story_5070_50700801_13_dialog_content = "—Tempestade de trovões.",
  ui_story_5070_50700801_14_dialog_content = "Nós poderíamos lidar com tempestades comuns sem problemas, mas um raio acabou de atingir o navio e causou uma explosão.",
  ui_story_5070_50700801_15_dialog_content = "Agora temos combate a incêndios e evacuações em andamento.",
  ui_story_5070_50700801_16_dialog_content = "Relâmpagos, explosões?",
  ui_story_5070_50700801_17_dialog_content = "Não verificamos a proteção contra raios e incêndios antes de sairmos? Como isso é possível?",
  ui_story_5070_50700801_18_dialog_content = "Eles são eficazes apenas contra incêndios naturais.",
  ui_story_5070_50700801_19_dialog_content = "O problema é que talvez não seja o único problema que estamos enfrentando.",
  ui_story_5070_50700801_20_dialog_content = "Hã?",
  ui_story_5070_50700801_21_dialog_content = "Agora não é hora de explicar, até porque não sei exatamente o que está acontecendo com os raios e o fogo.",
  ui_story_5070_50700801_22_dialog_content = "Posso ajudar em alguma coisa?",
  ui_story_5070_50700801_23_dialog_content = "Bem, a ideia era levar você para um lugar seguro, mas agora você se tornou um par extra de mãos para ajudar.",
  ui_story_5070_50700801_24_dialog_content = "Então vamos colocar você para trabalhar.",
  ui_story_5070_50700801_25_dialog_content = "Me siga.",
  ui_story_5070_50700801_26_dialog_content = "Por que o fogo ainda não está controlado? O que vocês estão fazendo?!",
  ui_story_5070_50700801_27_dialog_content = "Tente você mesmo! Já estamos arriscando nossas vidas para impedir que o fogo se espalhe para fora!",
  ui_story_5070_50700801_28_dialog_content = "Droga, por que o fogo está começando de baixo? A cabana é toda de madeira; ela não vai aguentar!",
  ui_story_5070_50700801_29_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5070_50700801_30_dialog_content = "<color=#e8d9bb>A explosão alta está bem à frente desta vez; a porta da cabine da frente se arrebenta, com chamas invadindo!</color>",
  ui_story_5070_50700801_31_dialog_content = "<color=#e8d9bb>Vuuush—</color>",
  ui_story_5070_50700801_32_dialog_content = "<color=#e8d9bb>O pedaço de madeira em chamas para a poucos centímetros do construtor naval, se despedaçando em vários fragmentos no ar.</color>",
  ui_story_5070_50700801_33_dialog_content = "Tanto o fogo quanto a água são impiedosos. A última coisa que você deve fazer quando algo inesperado acontece é entrar em pânico.",
  ui_story_5070_50700801_34_dialog_content = "Tudo bem ter medo, mas não deixe seus companheiros pagarem o preço do seu medo.",
  ui_story_5070_50700801_35_dialog_content = "Sr. Zhong Xu! M-Muito obrigado, senhor, por nos salvar!",
  ui_story_5070_50700801_36_dialog_content = "Para ser sincero, não consigo lidar com os problemas deste navio sozinho. Preciso do seu apoio, senhor.",
  ui_story_5070_50700801_37_dialog_content = "Por favor, nos diga, o que devemos fazer agora?",
  ui_story_5070_50700801_38_dialog_content = "Neste navio, você deve seguir as ordens do capitão, não as minhas.",
  ui_story_5070_50700801_39_dialog_content = "Sr. Zhong Xu, obrigado por nos ajudar.",
  ui_story_5070_50700801_40_dialog_content = "Capitão, desculpe por fazer você lidar com nossos problemas enquanto conduz o navio...",
  ui_story_5070_50700801_41_dialog_content = "Sem mais. Um capitão que não assume as maiores responsabilidades no navio não é um capitão digno.",
  ui_story_5070_50700801_42_dialog_content = "Eu verifiquei a condição do navio. Devemos ser capazes de parar este incêndio se agirmos agora.",
  ui_story_5070_50700801_43_dialog_content = "Sim!",
  ui_story_5070_50700801_44_dialog_content = "A tempestade ainda está intensa... Dr. Liqing, por favor, leve os evacuados para mais longe!",
  ui_story_5070_50700801_45_dialog_content = "Todos os outros devem preparar sacos de linho e quebrar objetos em chamas com ganchos de fogo.",
  ui_story_5070_50700801_46_dialog_content = "Reforços chegarão mais tarde.",
  ui_story_5070_50700801_47_dialog_content = "*Tosse* O ar aqui está ficando mais quente. Não vamos conseguir ficar aqui por muito mais tempo.",
  ui_story_5070_50700801_48_dialog_content = "Eu trouxe algumas outras coisas, Xuan Ji. Tem algo que possamos usar?",
  ui_story_5070_50700801_49_dialog_content = "A madeira da qual a cabine é feita não será resistente o suficiente, considerando a pressão da água...",
  ui_story_5070_50700801_50_dialog_content = "Xuan Ji?",
  ui_story_5070_50700801_51_dialog_content = "De volta com as coisas tão rápido, PlayerName?",
  ui_story_5070_50700801_52_dialog_content = "Na verdade, faz um bom tempo, mas você estava tão concentrado que não percebeu.",
  ui_story_5070_50700801_53_dialog_content = "Embora você tenha me pedido para encontrar materiais úteis...",
  ui_story_5070_50700801_54_dialog_content = "Tudo o que consegui encontrar por perto eram caixas vazias e peças descartadas.",
  ui_story_5070_50700801_55_dialog_content = "Você realmente acha que podemos fazer algo para apagar o incêndio apenas com essas coisas?",
  ui_story_5070_50700801_56_dialog_content = "Teremos que fazer isso. O incêndio bloqueou a passagem para o porão de carga, então a improvisação é nossa única opção.",
  ui_story_5070_50700801_57_dialog_content = "Mas para artesãos, não é necessário usar componentes predeterminados ou os melhores.",
  ui_story_5070_50700801_58_dialog_content = "Podemos tornar a madeira mais resistente com revestimento, substituir pregos faltantes por encaixes de espiga e mortise e modificar a estrutura para tornar o conjunto todo mais forte.",
  ui_story_5070_50700801_59_dialog_content = "Combine tudo o que vimos e aprendemos para criar o que você precisar.",
  ui_story_5070_50700801_60_dialog_content = "A adaptação flexível é a verdadeira essência dos gadgets.",
  ui_story_5070_50700801_61_dialog_content = "Pronto! Podemos ir ajudar agora.",
  ui_story_5070_50700801_62_dialog_content = "Capitão! O incêndio acima finalmente está sob controle, mas dentro da cabine...",
  ui_story_5070_50700801_63_dialog_content = "Tudo bem.",
  ui_story_5070_50700801_64_dialog_content = "Desculpe mantê-lo esperando—",
  ui_story_5070_50700801_65_dialog_content = "Levou algum tempo para improvisar algo, mas a satisfação é garantida!",
  ui_story_5070_50700801_66_dialog_content = "Senhora Xuan Ji, o que é isso... coisa?",
  ui_story_5070_50700801_67_dialog_content = "Você pode ligar isso agora, PlayerName.",
  ui_story_5070_50700801_68_dialog_content = "Vamos!",
  ui_story_5070_50700801_69_dialog_content = "<color=#e8d9bb>Estalo, estalo</color>",
  ui_story_5070_50700801_70_dialog_content = "<color=#e8d9bb>As tiras de madeira e placas de metal antes dispersas e soltas se torcem, unem e encaixam espontaneamente.</color>",
  ui_story_5070_50700801_71_dialog_content = "<color=#e8d9bb>Com uma extremidade pendurada na água do mar do lado do navio e a outra apoiada no convés, parece um dragão mecânico orgulhosamente emergindo do mar.</color>",
  ui_story_5070_50700801_72_dialog_content = "Mesmo sendo feito de tiras de caixa e peças descartadas, ainda é suficiente para apagar o incêndio.",
  ui_story_5070_50700801_73_dialog_content = "Vamos chamar de Dragão da Água!",
  ui_story_5070_50700801_74_dialog_content = "<color=#e8d9bb>Jatos de água poderosos saem da boca do dragão e fumaça branca se espalha pela cabine, apagando as chamas ferozes em grandes áreas.</color>",
  ui_story_5070_50700801_75_dialog_content = "Não fique aí parado. Comece a se mexer agora.",
  ui_story_5070_50700801_76_dialog_content = "Xuan Ji, você está no comando aqui.",
  ui_story_5070_50700801_77_dialog_content = "Eu não vou deixar você para baixo!",
  ui_story_5070_50700801_78_dialog_content = "Especialmente com PlayerName aqui também... PlayerName?",
  ui_story_5070_50700801_79_dialog_content = "Estou com uma sensação engraçada.",
  ui_story_5070_50700801_80_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5070_50700801_81_dialog_content = "<color=#e8d9bb>As chamas anteriormente apaziguadas se inflamam novamente.</color>",
  ui_story_5070_50700801_82_dialog_content = "Não, isso nunca vai acabar.",
  ui_story_5070_50700801_83_dialog_content = "Vou usar minha habilidade psíquica para encontrar a origem da explosão. Talvez eu consiga encontrar uma solução também.",
  ui_story_5070_50700801_84_dialog_content = "Aumento de Força!",
  ui_story_5070_50700801_85_dialog_content = "(Não é aqui. Preciso continuar descendo.)",
  ui_story_5070_50700801_86_dialog_content = "(A fonte é... O porão? O que tem lá...?)",
  ui_story_5070_50700801_87_dialog_content = "Nossa!",
  ui_story_5070_50700801_88_dialog_content = "<size=45>Graaah!!</size>",
  ui_story_5070_50700801_89_dialog_content = "<color=#e8d9bb>O convés abaixo é atingido pela fera mecânica, se abrindo e revelando um mar de chamas abaixo.</color>",
  ui_story_5070_50700801_90_dialog_content = "PlayerName!",
  ui_story_5070_50700801_91_dialog_content = "(Caído em—!)",
  ui_story_5070_50700801_92_dialog_content = "A Cinzas!",
  ui_story_5070_50700801_93_dialog_content = "!",
  ui_story_5070_50700801_94_dialog_content = "Ai... Minhas costas doem mesmo. Mas...",
  ui_story_5070_50700801_95_dialog_content = "Eu claramente caí bem onde o fogo começou, mas como é que as chamas não estão nem um pouco quentes?",
  ui_story_5070_50700801_96_dialog_content = "Jovem amigo, como estão seus ferimentos?",
  ui_story_5070_50700801_97_dialog_content = "Zhong Xu?! Por que você me seguiu até aqui?! É muito perigoso. Você está bem...?",
  ui_story_5070_50700801_98_dialog_content = "Felizmente, a Ministra Armilla modificou minha cadeira de rodas. Ela ainda está bem depois de sofrer aquele impacto.",
  ui_story_5070_50700801_99_dialog_content = "Essa não é a pergunta...",
  ui_story_5070_50700801_100_dialog_content = "Também sou bastante habilidoso nas Artes da Força Flamejante e posso controlar o incêndio neste navio.",
  ui_story_5070_50700801_101_dialog_content = "Você não vai se queimar com as chamas de jeito nenhum.",
  ui_story_5070_50700801_102_dialog_content = "Incrível! Isso não significa que você pode se mover livremente no fogo?",
  ui_story_5070_50700801_103_dialog_content = "A propósito, este lugar fica perto do porão. Com a habilidade de Zhong Xu, talvez possamos até lidar diretamente com a fonte do incêndio!",
  ui_story_5070_50700801_104_dialog_content = "Espere um minuto.",
  ui_story_5070_50700801_105_dialog_content = "Você tem alguns poderes especiais, mas sua aptidão física é insuficiente. Você deve ir para algum lugar seguro primeiro.",
  ui_story_5070_50700801_106_dialog_content = "Como poderia deixar passar uma oportunidade tão aleatória?",
  ui_story_5070_50700801_107_dialog_content = "Isso não é sua responsabilidade.",
  ui_story_5070_50700801_108_dialog_content = "Como enviada de outra terra, você é muito importante e deve priorizar sua própria segurança em primeiro lugar. Ninguém vai criticá-la severamente por fazer isso.",
  ui_story_5070_50700801_109_dialog_content = "Não há necessidade de se colocar em perigo.",
  ui_story_5070_50700801_110_dialog_content = "Eu sei que você está apenas preocupado comigo, mas se você está sempre se preocupando com coisas que ainda nem aconteceram...",
  ui_story_5070_50700801_111_dialog_content = "Você seria capaz de realizar alguma coisa?",
  ui_story_5070_50700801_112_dialog_content = "Além disso, o Zhong Xu que acabou de pular comigo disse isso... Não é um pouco difícil de acreditar?",
  ui_story_5070_50700801_113_dialog_content = "Zhong Xu não é responsável por me salvar, certo?",
  ui_story_5070_50700801_114_dialog_content = "...",
  ui_story_5070_50700801_115_dialog_content = "Hahaha, você faz um bom ponto.",
  ui_story_5070_50700801_116_dialog_content = "Eu nunca pensei que estaria dizendo a outra pessoa para tomar cuidado.",
  ui_story_5070_50700801_117_dialog_content = "Você é uma pessoa realmente incrível.",
  ui_story_5070_50700801_118_dialog_content = "Vamos juntos!",
  ui_story_5070_50700801_119_dialog_content = "Vou confirmar a localização da origem do incêndio.",
  ui_story_5070_50700801_120_dialog_content = "Aumento de Força!",
  ui_story_5070_50700801_121_dialog_content = "Espere aí, tem algo estranho nesta fonte de fogo. E...",
  ui_story_5070_50700801_122_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5070_50700801_123_dialog_content = "<size=45>Cuidado!</size>",
  ui_story_5070_50700801_124_dialog_content = "<color=#e8d9bb>Uma explosão repentina de chamas engole tudo.</color>",
  ui_story_5070_50700802_1_dialog_content = "*Tosse* *tosse*... Há fumaça por toda parte.",
  ui_story_5070_50700802_2_dialog_content = "Mal consigo respirar e está difícil me concentrar... mas eu juro que senti alguém aqui agora mesmo...",
  ui_story_5070_50700802_3_dialog_content = "...",
  ui_story_5070_50700802_4_dialog_content = "*Tosse* Quem é você...?",
  ui_story_5070_50700802_5_dialog_content = "<color=#e8d9bb>Uma luz branca peculiar brilha no meio da fumaça.</color>",
  ui_story_5070_50700802_6_dialog_content = "Jovem amigo!",
  ui_story_5070_50700802_7_dialog_content = "Zhong Xu... *cof*...",
  ui_story_5070_50700802_8_dialog_content = "Me dê sua mão!",
  ui_story_5070_50700802_9_dialog_content = "Espere, ali...",
  ui_story_5070_50700802_10_dialog_content = "<color=#e8d9bb>Uma bola de fogo explode à frente.</color>",
  ui_story_5070_50700802_11_dialog_content = "Vamos sair daqui primeiro.",
  ui_story_5070_50700802_12_dialog_content = "Como está o PlayerName, Sr. Zhong Xu? Ele está bem?",
  ui_story_5070_50700802_13_dialog_content = "Ei! Saiam da frente! Todos vocês!",
  ui_story_5070_50700802_14_dialog_content = "Deixe o médico passar!",
  ui_story_5070_50700901_1_dialog_content = "Argh...",
  ui_story_5070_50700901_2_dialog_content = "Miau!",
  ui_story_5070_50700901_3_dialog_content = "... Por que tem um gato na minha cama?",
  ui_story_5070_50700901_4_dialog_content = "V-Você não é aquele gato que está sempre perto do Doutor Liqing... Tinytail, certo?",
  ui_story_5070_50700901_5_dialog_content = "Miau!",
  ui_story_5070_50700901_6_dialog_content = "O que está fazendo aqui?",
  ui_story_5070_50700901_7_dialog_content = "Ah sim, eu preciso perguntar sobre o incêndio ontem... Estão todos bem?!",
  ui_story_5070_50700901_8_dialog_content = "Miau! Miau!",
  ui_story_5070_50700901_9_dialog_content = "Ei... Saia do caminho, Tinytail. Isso é perigoso.",
  ui_story_5070_50700901_10_dialog_content = "Ah, eu só fui buscar umas ervas e você já está de pé?",
  ui_story_5070_50700901_11_dialog_content = "Deite-se neste instante.",
  ui_story_5070_50700901_12_dialog_content = "Miau...",
  ui_story_5070_50700901_13_dialog_content = "Muito bem, Tinytail!",
  ui_story_5070_50700901_14_dialog_content = "Eu sabia que PlayerName seria um paciente difícil como Zhong Xu.",
  ui_story_5070_50700901_15_dialog_content = "Foi mesmo você quem fez o Tinytail atrapalhar meu caminho?",
  ui_story_5070_50700901_16_dialog_content = "Claro, não subestime aquela fumaça que te fez engasgar.",
  ui_story_5070_50700901_17_dialog_content = "Você estaria em grandes apuros se a fumaça venenosa entrasse em seus pulmões.",
  ui_story_5070_50700901_18_dialog_content = "Deite-se e espere.",
  ui_story_5070_50700901_19_dialog_content = "4,5g de fritilária, 3g de tricossanthes e 2,4g cada de pólen, wolfiporia, laranja mandarim e platycodon.",
  ui_story_5070_50700901_20_dialog_content = "O que é isso?",
  ui_story_5070_50700901_21_dialog_content = "É a receita de um anti-inflamatório que irá desintoxicar seus pulmões.",
  ui_story_5070_50700901_22_dialog_content = "Não se esqueça de aumentar a ingestão de água, descansar mais e respirar ar fresco. Quanto à comida, coma algo leve.",
  ui_story_5070_50700901_23_dialog_content = "Venha me ver imediatamente se você sentir tosse, catarro ou peito congestionado. Entendeu?",
  ui_story_5070_50700901_24_dialog_content = "Por que você está olhando assim para mim?",
  ui_story_5070_50700901_25_dialog_content = "Liqing parece bastante confiável no momento.",
  ui_story_5070_50700901_26_dialog_content = "Basicamente, é como... Como seria a frase em Longzhou? Estilo médico poderoso!",
  ui_story_5070_50700901_27_dialog_content = "Sério?! Aham... Quer dizer, isso não era de se esperar?",
  ui_story_5070_50700901_28_dialog_content = "Tudo bem, aqui está o seu remédio. Tome enquanto ainda está quente.",
  ui_story_5070_50700901_29_dialog_content = "Tss... Q-quite um sabor complexo.",
  ui_story_5070_50700901_30_dialog_content = "Mestre Bu diz: \"Bom remédio é amargo. É o preço que se paga pela recuperação.\"",
  ui_story_5070_50700901_31_dialog_content = "... É realmente tão ruim assim?",
  ui_story_5070_50700901_32_dialog_content = "Não é exatamente desagradável, é apenas a primeira vez que provei algo tão complexo...",
  ui_story_5070_50700901_33_dialog_content = "Não estou realmente acostumado.",
  ui_story_5070_50700901_34_dialog_content = "O que vou fazer com vocês, jovens?",
  ui_story_5070_50700901_35_dialog_content = "Aqui, pegue esta fruta cristalizada. Isso vai ajudar depois de tomar seu remédio.",
  ui_story_5070_50700901_36_dialog_content = "Mas você só vai conseguir esta aqui. Eu só consegui esconder uma única mala ao embarcar no navio.",
  ui_story_5070_50700901_37_dialog_content = "Obrigado, Liqing. Isso é muito atencioso da sua parte.",
  ui_story_5070_50700901_38_dialog_content = "Não tem jeito, afinal sou um ótimo médico!",
  ui_story_5070_50700901_39_dialog_content = "Descanse bem. Preciso ver os outros.",
  ui_story_5070_50700901_40_dialog_content = "Alguém mais está ferido?",
  ui_story_5070_50700901_41_dialog_content = "Fique quieto. Sua condição foi a mais séria ontem, então esqueça os outros!",
  ui_story_5070_50700901_42_dialog_content = "Não se preocupe, vai ficar tudo bem.",
  ui_story_5070_50700901_43_dialog_content = "Tenho que dar a todos um remédio refrescante e desintoxicante como precaução.",
  ui_story_5070_50700901_44_dialog_content = "Falando dos outros...",
  ui_story_5070_50700901_45_dialog_content = "Muitos vieram visitar enquanto você estava dormindo. Agora que você acordou, posso chamá-los a todos.",
  ui_story_5070_50700901_46_dialog_content = "Não, não, não. Eu sei que todos estão bem, então não precisa se preocupar...",
  ui_story_5070_50700901_47_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5070_50700901_48_dialog_content = "Sem formalidades necessárias!",
  ui_story_5070_50700901_49_dialog_content = "*Suspiro*",
  ui_story_5070_50700901_50_dialog_content = "Dantang?",
  ui_story_5070_50700901_51_dialog_content = "Senhora Xuan Ji, por favor, não pressione Sua Alteza dessa maneira.",
  ui_story_5070_50700901_52_dialog_content = "Você não está sendo um pouco superprotetor, Jiu? Relaxe, Sua Alteza é preciosa, mas não é frágil também.",
  ui_story_5070_50700901_53_dialog_content = "Xuan Ji? Jiu? Por que todos vocês estão aqui?",
  ui_story_5070_50700901_54_dialog_content = "Para ver o herói de ontem, é claro.",
  ui_story_5070_50700901_55_dialog_content = "Estou feliz que você não se machucou gravemente, senão eu não saberia como compensar você.",
  ui_story_5070_50700901_56_dialog_content = "Não há motivo para você se desculpar. Ninguém pensaria que eu escorregaria justo naquele momento.",
  ui_story_5070_50700901_57_dialog_content = "E todos estão bem, o que prova que sua invenção conseguiu apagar o fogo...",
  ui_story_5070_50700901_58_dialog_content = "Bem, você está saudável o suficiente para falar bastante, então deve estar bem.",
  ui_story_5070_50700901_59_dialog_content = "Então, como é ver a recuperação do PlayerName pessoalmente, Princesa Dantang?",
  ui_story_5070_50700901_60_dialog_content = "Bem melhor do que bisbilhotar por aí, né?",
  ui_story_5070_50700901_61_dialog_content = "Você deve ter me confundido com outra pessoa, Ministra Armilla.",
  ui_story_5070_50700901_62_dialog_content = "É meu dever me preocupar com a saúde de um enviado importante como PlayerName.",
  ui_story_5070_50700901_63_dialog_content = "Não preciso, como você disse, bisbilhotar.",
  ui_story_5070_50700901_64_dialog_content = "Sim, sim, acredito que toda aquela fumaça de ontem ainda está afetando meus olhos.",
  ui_story_5070_50700901_65_dialog_content = "Deixarei você cumprir seu dever então, Princesa Dantang. Por favor, continue cuidando de PlayerName!",
  ui_story_5070_50700901_66_dialog_content = "Eu...",
  ui_story_5070_50700901_67_dialog_content = "Tudo bem, Dantang. Estou perfeitamente saudável agora e não há nada com que se preocupar.",
  ui_story_5070_50700901_68_dialog_content = "Não tem nada me incomodando também, hum... Exceto por aquele cheiro de remédio. É realmente algo...",
  ui_story_5070_50700901_69_dialog_content = "Remédio? Eu tenho uma solução para isso.",
  ui_story_5070_50700901_70_dialog_content = "Quando você estiver fora de perigo imediato, a cura através da comida é a opção superior.",
  ui_story_5070_50700901_71_dialog_content = "Considerando que o Liqing também está presente, gostaria de preparar uma deliciosa refeição medicinal para todos. O que você acha da ideia?",
  ui_story_5070_50700901_72_dialog_content = "Deixar gostoso?! Sem problemas!",
  ui_story_5070_50700901_73_dialog_content = "Eu conheço a receita de muitos tônicos e até comprei ingredientes especiais para esta viagem.",
  ui_story_5070_50700901_74_dialog_content = "A raiz de lótus promove a saúde, o melão de inverno nutre a pele, a wolfiporia nutre a mente...",
  ui_story_5070_50700901_75_dialog_content = "Eu posso fazer tantas coisas!",
  ui_story_5070_50700901_76_dialog_content = "...",
  ui_story_5070_50700901_77_dialog_content = "Xuan Ji não vai vir comer algo...? Xuan Ji?",
  ui_story_5070_50700901_78_dialog_content = "Sim? Alguma coisa que eu possa ajudar?",
  ui_story_5070_50700901_79_dialog_content = "Não. Você parece um pouco distraído e não disse nada por um bom tempo.",
  ui_story_5070_50700901_80_dialog_content = "É tão óbvio assim?",
  ui_story_5070_50700901_81_dialog_content = "Acho que ainda preciso trabalhar na minha compostura. Nota mental: Fazer uma máscara que possa ajudar a manter a expressão facial desejada.",
  ui_story_5070_50700901_82_dialog_content = "Na verdade, estive pensando sobre a noite passada.",
  ui_story_5070_50700901_83_dialog_content = "Quando o Sr. Zhong Xu te tirou da fumaça...",
  ui_story_5070_50700901_84_dialog_content = "Você continuava murmurando sobre incêndios e figuras.",
  ui_story_5070_50700901_85_dialog_content = "O que você viu?",
  ui_story_5070_50700901_86_dialog_content = "Não é exatamente enxergar, é mais como sentir.",
  ui_story_5070_50700901_87_dialog_content = "Parecia haver algo realmente estranho no porão, como fogo, mas eu não conseguia sentir o calor que as chamas deveriam emitir.",
  ui_story_5070_50700901_88_dialog_content = "Não tinha calor, mas ainda parecia mais substancial do que todas as chamas ao redor juntas.",
  ui_story_5070_50700901_89_dialog_content = "Era como... Um mini sol.",
  ui_story_5070_50700901_90_dialog_content = "... Eu sei que minha descrição é um pouco estranha.",
  ui_story_5070_50700901_91_dialog_content = "De qualquer forma, suspeito que o raio foi apenas o catalisador, e essa coisa foi a verdadeira causa do incêndio.",
  ui_story_5070_50700901_92_dialog_content = "Quanto à figura, eu não consegui dar uma boa olhada, mas ela permaneceu perto do porão o tempo todo...",
  ui_story_5070_50700901_93_dialog_content = "Tudo isso é um pouco estranho.",
  ui_story_5070_50700901_94_dialog_content = "Entendido.",
  ui_story_5070_50700901_95_dialog_content = "Mas vamos controlar o impulso da próxima vez, PlayerName.",
  ui_story_5070_50700901_96_dialog_content = "Pare de escanear mentalmente qualquer coisa incomum que você pegou...",
  ui_story_5070_50700901_97_dialog_content = "Não posso te tirar do perigo o tempo todo, mesmo que eu quisesse.",
  ui_story_5070_50700901_98_dialog_content = "Desculpe... Vou prestar atenção.",
  ui_story_5070_50700901_99_dialog_content = "Bem, tenho que correr agora.",
  ui_story_5070_50700901_100_dialog_content = "Espere um pouco.",
  ui_story_5070_50700901_101_dialog_content = "Aconteceu algo mais ruim enquanto eu dormia?",
  ui_story_5070_50700901_102_dialog_content = "...",
  ui_story_5070_50700901_103_dialog_content = "Bem, acho que realmente preciso fazer a máscara de expressão virar uma agenda.",
  ui_story_5070_50700901_104_dialog_content = "Supondo que eu consiga voltar para minha oficina em Longzhou.",
  ui_story_5070_50700901_105_dialog_content = "Há algo errado com a viagem?",
  ui_story_5070_50700901_106_dialog_content = "Há um ditado na navegação:",
  ui_story_5070_50700901_X106_dialog_content = "\"Navegue pelas estrelas à noite, pelo sol durante o dia, pela escuridão com a bússola e saia da área o mais rápido possível quando nada disso funcionar.\"",
  ui_story_5070_50700901_107_dialog_content = "Observar estrelas e sol? Você quer dizer determinar a direção de um navio pelas estrelas, como antes do Xuan Ji?",
  ui_story_5070_50700901_108_dialog_content = "Certo. Se não houver estrela ou lua, você ainda tem uma bússola para direção.",
  ui_story_5070_50700901_109_dialog_content = "Mas se até mesmo os instrumentos falharem, você não terá como saber para onde está indo.",
  ui_story_5070_50700901_110_dialog_content = "Se você não sair logo, ficará perdido no mar.",
  ui_story_5070_50700901_111_dialog_content = "Após o alvoroço da noite passada, tentei de tudo para encontrar nossa direção na tempestade.",
  ui_story_5070_50700901_112_dialog_content = "...Nada é eficaz?",
  ui_story_5070_50700901_113_dialog_content = "<color=#e8d9bb>Xuan Ji acena levemente.</color>",
  ui_story_5070_50700901_114_dialog_content = "Nada funcionou, até agora.",
  ui_story_5070_50700901_115_dialog_content = "Isso não aconteceria com o Shadowind em uma viagem normal.",
  ui_story_5070_50700901_116_dialog_content = "Mas estamos tão longe e sem um mapa abrangente, que não podemos nem contar com o sol mesmo quando ele aparece.",
  ui_story_5070_50700901_117_dialog_content = "Então, tenho quase certeza neste exato momento...",
  ui_story_5070_50700901_118_dialog_content = "O Shadowind está fora do curso.",
  ui_story_5070_50700902_1_dialog_content = "Estamos perdidos e ainda temos que lidar com os Eclipsitas... A viagem tem sido bem agitada.",
  ui_story_5070_50700902_2_dialog_content = "Precisamos nos orientar o mais rápido possível.",
  ui_story_5070_50700902_3_dialog_content = "Entendo o raciocínio, mas qual é a conexão com mover a Armadilha do Dragão de Água?",
  ui_story_5070_50700902_4_dialog_content = "Dávamos um propósito a cada dispositivo que criávamos, mas isso não significava que era a única coisa para a qual eles eram úteis.",
  ui_story_5070_50700902_5_dialog_content = "<color=#e8d9bb>Em um estrondo ensurdecedor, a água do mar é bombeada para barris de madeira previamente preparados através de tubos de latão.</color>",
  ui_story_5070_50700902_6_dialog_content = "Veja, além da água do mar, também pegamos um monte de peixes e camarões.",
  ui_story_5070_50700902_7_dialog_content = "O mar pode ser grande, mas possui diferentes criaturas vivendo em diferentes partes.",
  ui_story_5070_50700902_8_dialog_content = "Então, se conseguirmos pegar algumas espécies marinhas icônicas da região...",
  ui_story_5070_50700902_9_dialog_content = "Devemos obter uma pista educada sobre onde estamos aproximadamente, comparando-as com as imagens no guia.",
  ui_story_5070_50700902_10_dialog_content = "Então, até mesmo esse ângulo pode ser considerado.",
  ui_story_5070_50700902_11_dialog_content = "Pegou algo especial?",
  ui_story_5070_50700902_12_dialog_content = "Infelizmente, apenas criaturas simples boas apenas para as refeições medicinais que a princesa queria fazer.",
  ui_story_5070_50700902_13_dialog_content = "No entanto, há um aviso de que há riscos envolvidos nisso.",
  ui_story_5070_50700902_14_dialog_content = "Os marinheiros pescam para nós todos os dias, então qual é o risco?",
  ui_story_5070_50700902_15_dialog_content = "Na verdade, eu só mencionei metade disso.",
  ui_story_5070_50700902_16_dialog_content = "Embora os dispositivos possam ser adaptados para muitas coisas, eles não foram projetados para isso.",
  ui_story_5070_50700902_17_dialog_content = "Então é possível que algo inesperado aconteça...",
  ui_story_5070_50700902_18_dialog_content = "Pegue o Caranguejo de Fogo, por exemplo. Ele é ótimo para soldagem.",
  ui_story_5070_50700902_19_dialog_content = "Mas péssimo para grelhar carne.",
  ui_story_5070_50700902_20_dialog_content = "Você tem ideia de como o gosto da carne carbonizada é ruim?",
  ui_story_5070_50700902_21_dialog_content = "Prefiro não saber. Nunca.",
  ui_story_5070_50700902_22_dialog_content = "E quando exatamente você usaria caranguejos de fogo para cozinhar?",
  ui_story_5070_50700902_23_dialog_content = "Muito parecido com usar uma bomba para pegar peixes agora mesmo.",
  ui_story_5070_50700902_24_dialog_content = "É uma emergência terrível.",
  ui_story_5070_50700902_25_dialog_content = "Mesmo não sendo tão familiarizado com os ditados de Longzhou.",
  ui_story_5070_50700902_26_dialog_content = "Mas algo me diz que assar caranguejos com fogo não se encaixa no contexto.",
  ui_story_5070_50700902_27_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5070_50700902_28_dialog_content = "O que o navio atingiu?",
  ui_story_5070_50700902_29_dialog_content = "Desligue o Dragão de Água.",
  ui_story_5070_50700902_30_dialog_content = "A ação de bombeamento é tão intensa que provavelmente atraiu algo enorme no oceano.",
  ui_story_5070_50700902_31_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5070_50700902_32_dialog_content = "O navio está inclinando! Todos, agarrem-se em algo e segurem firme!",
  ui_story_5070_50700902_33_dialog_content = "Eu... Eu consegui.",
  ui_story_5070_50700902_34_dialog_content = "Finalmente vim ao convés para tomar um pouco de ar fresco e logo tive que me deparar com algo assim!",
  ui_story_5070_50700902_35_dialog_content = "Graças a Deus eu não me afastei das cercas de boi. Não me diga que aquela adivinhação realmente significava... Ai!",
  ui_story_5070_50700902_36_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5070_50700902_37_dialog_content = "A inclinação está piorando. Não podemos fazer nada assim.",
  ui_story_5070_50700902_38_dialog_content = "Todos, movam-se para o outro lado! Precisamos equilibrar o navio!",
  ui_story_5070_50700902_39_dialog_content = "Vou usar o Caranguejo de Fogo para impulsionar o queimador do Shadowind. Segure firme e logo ganharemos velocidade.",
  ui_story_5070_50700902_40_dialog_content = "Sucesso! A sombra no mar ficou para trás.",
  ui_story_5070_50700902_41_dialog_content = "Fui atacado por caranguejos de fogo tantas vezes que é estranho ser salvo por eles nesta ocasião.",
  ui_story_5070_50700902_42_dialog_content = "O que eu te disse? Um gadget é tão bom ou mau quanto aqueles que o operam.",
  ui_story_5070_50700902_43_dialog_content = "Cabe ao usuário usá-lo para salvar uma vida ou acabar com ela.",
  ui_story_5070_50700902_44_dialog_content = "Talvez eu deva mudar minha opinião sobre esses \"caranguejos grandes e assustadores\"...",
  ui_story_5070_50700902_45_dialog_content = "Esta é a primeira vez que o Shadowind se move com tanta velocidade. Será sustentável?",
  ui_story_5070_50700902_46_dialog_content = "Apenas nos seus sonhos.",
  ui_story_5070_50700902_47_dialog_content = "Obtemos o poder que temos agora, tudo por causa da Força Flamejante dentro do Caranguejo de Fogo.",
  ui_story_5070_50700902_48_dialog_content = "Vai acabar muito rápido se não repormos, então...",
  ui_story_5070_50700902_49_dialog_content = "Senhora Xuan Ji! O cara perto da caldeira me disse que todos os caranguejos de fogo não estão se movendo mais!",
  ui_story_5070_50700902_50_dialog_content = "Como agora mesmo?",
  ui_story_5070_50700902_51_dialog_content = "Bem, morreu mais rápido do que eu esperava.",
  ui_story_5070_50700902_52_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5070_50700902_53_dialog_content = "Aumento de Força!",
  ui_story_5070_50700902_54_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5070_50700902_55_dialog_content = "Funcionou?",
  ui_story_5070_50700902_56_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5070_50700902_57_dialog_content = "Por favor, desista. Não somos nem comida, nem brinquedos!",
  ui_story_5070_50700902_58_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5070_50700902_59_dialog_content = "Não. Eu só posso fazê-lo parar por um tempo. Ainda seremos ultrapassados, a menos que o Shadowind aumente a distância.",
  ui_story_5070_50700902_60_dialog_content = "E o que eu senti do corpo dele debaixo d'água é muitas vezes maior do que a sombra na superfície...",
  ui_story_5070_50700902_61_dialog_content = "Exatamente, quão maior é?",
  ui_story_5070_50700902_62_dialog_content = "O quê?",
  ui_story_5070_50700902_63_dialog_content = "Podemos avaliar a silhueta na água.",
  ui_story_5070_50700902_X63_dialog_content = "E então calcule o tamanho com base no seu mindlink, PlayerName.",
  ui_story_5070_50700902_64_dialog_content = "Por fim, descubra o alcance da ameaça de acordo com o peso do Shadowind e o ângulo de inclinação do impacto...",
  ui_story_5070_50700902_65_dialog_content = "Eu sei o que está debaixo d'água!",
  ui_story_5070_50700902_66_dialog_content = "Você consegue mantê-lo afastado por um tempo, PlayerName? Eu preciso pegar algo na minha cabine que provavelmente possa distraí-lo.",
  ui_story_5070_50700902_67_dialog_content = "Ok. Deixe comigo.",
  ui_story_5070_50700902_68_dialog_content = "Aumento de Força!",
  ui_story_5070_50700902_69_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5070_50700902_70_dialog_content = "Aumento de Força!",
  ui_story_5070_50700902_71_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5070_50700902_72_dialog_content = "(Tss... Quantas vezes?? Você deve estar brincando. E não é Xuan Ji melhor?)",
  ui_story_5070_50700902_73_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5070_50700902_74_dialog_content = "Aumento de Força...!",
  ui_story_5070_50700902_75_dialog_content = "Voltei, PlayerName!",
  ui_story_5070_50700902_76_dialog_content = "Brilhante—",
  ui_story_5070_50700902_77_dialog_content = "<color=#e8d9bb>Bang!!!</color>",
  ui_story_5070_50700902_78_dialog_content = "(O impacto mais violento até então ocorreu, e fui arremessado pelo ar.)",
  ui_story_5070_50700902_79_dialog_content = "Pegue meu guarda-sol!",
  ui_story_5070_50700902_80_dialog_content = "(Não! Não vou conseguir distrair o monstro marinho agora...!)",
  ui_story_5070_50700902_81_dialog_content = "Xuan Ji! Me dê o que você está segurando!",
  ui_story_5070_50700902_82_dialog_content = "?!",
  ui_story_5070_50700902_83_dialog_content = "Que tipo de aventureiro você é... Ok, aqui vai!",
  ui_story_5070_50700902_84_dialog_content = "(Uma vantagem de estar no alto é que você pode jogar mais longe!)",
  ui_story_5070_50700902_85_dialog_content = "Pare de perseguir! Este é um brinquedo mais adequado para você!",
  ui_story_5070_50700902_86_dialog_content = "<color=#e8d9bb>Plop!</color>",
  ui_story_5070_50700902_87_dialog_content = "<color=#e8d9bb>A pedra tirada de Xuan Ji cai no mar.</color>",
  ui_story_5070_50700902_88_dialog_content = "(Eu senti o monstro marinho virando e vi Xuan Ji abrir o guarda-chuva para tentar me pegar.)",
  ui_story_5070_50700902_89_dialog_content = "(Não há tempo, mas não importa porque... Aquela pessoa ainda está lá embaixo!)",
  ui_story_5070_50700902_90_dialog_content = "A Cinzas!",
  ui_story_5070_50700902_91_dialog_content = "<color=#e8d9bb>Com chamas escarlates subindo aos céus e o motor ressoando em alta velocidade, o Shadowind acelera mais uma vez.</color>",
  ui_story_5070_50700902_92_dialog_content = "(Caí em chamas silenciosas e calmas.)",
  ui_story_5070_50700902_93_dialog_content = "Ufa, dessa vez, perdemos o monstro do mar de vez. Finalmente acabou...",
  ui_story_5070_50700902_94_dialog_content = "Amigo jovem.",
  ui_story_5070_50700902_95_dialog_content = "Realmente admiro sua grande coragem.",
  ui_story_5070_50700902_96_dialog_content = "Mas você não acha que foi muito imprudente se colocar em perigo dessa forma?",
  ui_story_5070_50700902_97_dialog_content = "(Qu-que tom sério!)",
  ui_story_5070_50700902_98_dialog_content = "Eu... Desculpe por preocupar todos. No entanto, na verdade, estou bastante certo.",
  ui_story_5070_50700902_99_dialog_content = "Porque eu vi Zhong Xu aqui.",
  ui_story_5070_50700902_100_dialog_content = "Muito obrigado.",
  ui_story_5070_50700902_101_dialog_content = "... Tudo bem. Você deveria agradecer à Ministra Armilla em vez de mim.",
  ui_story_5070_50700902_102_dialog_content = "Sem as modificações que ela fez na minha cadeira de rodas, eu não seria capaz de me mover livremente neste navio instável.",
  ui_story_5070_50700902_103_dialog_content = "PlayerName!",
  ui_story_5070_50700902_104_dialog_content = "Eu sabia que você tinha sorte! Você pode alcançar qualquer coisa, desde que tente.",
  ui_story_5070_50700902_105_dialog_content = "Haha, obrigado por acreditar em mim. Mas, como um pedaço de rocha poderia atrair o monstro marinho?",
  ui_story_5070_50700902_106_dialog_content = "Porque isso não é uma pedra comum, mas sim uma pedra luminosa, quanto mais escuro estiver ao redor dela, mais brilhante ela fica.",
  ui_story_5070_50700902_107_dialog_content = "Não há muito escrito sobre esse monstro, exceto que ele habitava no fundo do mar.",
  ui_story_5070_50700902_108_dialog_content = "E criaturas assim são sempre atraídas pela luz.",
  ui_story_5070_50700902_109_dialog_content = "Então, achei que seria uma excelente isca.",
  ui_story_5070_50700902_110_dialog_content = "Felizmente, funcionou.",
  ui_story_5070_50700902_111_dialog_content = "Tá todo mundo bem?",
  ui_story_5070_50700902_112_dialog_content = "Estamos bem, além de estarmos a segundos de virar comida de monstro.",
  ui_story_5070_50700902_113_dialog_content = "Navegar pelo oceano é realmente difícil...",
  ui_story_5070_50700902_114_dialog_content = "Ainda bem que essas coisas não estão no céu, caso contrário, Soroz e eu também estaríamos em perigo.",
  ui_story_5070_50700902_115_dialog_content = "Bem, devemos ficar seguros por um tempo após aquele encontro angustiante.",
  ui_story_5070_50700902_116_dialog_content = "É raro encontrar tais gigantes no mar, afinal.",
  ui_story_5070_50700902_117_dialog_content = "Pelo menos não teremos outro ataque para nos preocupar até sairmos do território deles.",
  ui_story_5070_50700902_118_dialog_content = "Então você está dizendo que agora podemos usar quantas Armadilhas de Dragão de Água quisermos?",
  ui_story_5070_50700902_119_dialog_content = "Até o máximo, mesmo.",
  ui_story_5070_50700902_120_dialog_content = "Chame todos que não estiverem ocupados para vir aqui. Vamos aproveitar essa oportunidade para nos esforçarmos ao máximo e trabalhar juntos para pegar mais peixes.",
  ui_story_5070_50700902_121_dialog_content = "Estamos navegando há algum tempo e já é hora de reabastecer nossas provisões no Shadowind.",
  ui_story_5070_50700902_122_dialog_content = "Ok... ok, já tá saindo.",
  ui_story_5070_50700902_123_dialog_content = "Ops.",
  ui_story_5070_50700902_124_dialog_content = "Foi mal. Desculpe, não quis esbarrar em você...",
  ui_story_5070_50700902_125_dialog_content = "Sol, o Hábil? Tudo bem, eu também não te vi chegar.",
  ui_story_5070_50700902_126_dialog_content = "O que você está segurando? Cheira bem.",
  ui_story_5070_50700902_127_dialog_content = "É isca. O capitão nos disse para pescar alguns peixes.",
  ui_story_5070_50700902_128_dialog_content = "Com um aroma tão delicioso, deve ser fácil pegar peixes grandes.",
  ui_story_5070_50700902_129_dialog_content = "... Onde ela está?",
  ui_story_5070_50700902_130_dialog_content = "Capitão! Venha ver o que pescamos!",
  ui_story_5070_50700902_131_dialog_content = "O que está fazendo, PlayerName?",
  ui_story_5070_50700902_132_dialog_content = "Agora há pouco... Sol o Habilidoso?",
  ui_story_5070_50700902_133_dialog_content = "...",
  ui_story_5070_50700902_134_dialog_content = "Deixa pra lá, esquece.",
  ui_story_5070_50700902_135_dialog_content = "<size=25>Enquanto a isca permanecer, o peixe virá à tona, não importa quão fundo ele nade.</size>",
  ui_story_5070_50700902_136_dialog_content = "O que você disse?",
  ui_story_5070_50700902_137_dialog_content = "Nada! Vamos, vamos conferir a festa ali.",
  ui_story_5070_50700902_138_dialog_content = "Tudo bem então... Eh? Como você conseguiu juntar tanta madeira?",
  ui_story_5070_50700902_139_dialog_content = "Estes são destroços de navios naufragados.",
  ui_story_5070_50700902_140_dialog_content = "Mas o tipo de madeira, tinta e grau de corrosão são todos diferentes. É óbvio que são de navios diferentes.",
  ui_story_5070_50700902_141_dialog_content = "Temo que haja uma concentração de naufrágios em algum lugar por aqui.",
  ui_story_5070_50700902_142_dialog_content = "Poderia até ser um cemitério de navios.",
  ui_story_5070_50701001_1_dialog_content = "<color=#e8d9bb>Plop!</color>",
  ui_story_5070_50701001_2_dialog_content = "Yuebai?!",
  ui_story_5070_50701001_3_dialog_content = "Yuebai acabou de pular de cabeça no mar?!",
  ui_story_5070_50701001_4_dialog_content = "Não se preocupe. Yuebai nada melhor do que todos neste navio juntos.",
  ui_story_5070_50701001_5_dialog_content = "Nós, como passageiros, devemos confiar no capitão, então apenas esperemos e vejamos.",
  ui_story_5070_50701001_6_dialog_content = "(Há muitos tipos de perigo no mar. Rochas, redemoinhos, feras marinhas ferozes...)",
  ui_story_5070_50701001_7_dialog_content = "(Mas todos eles têm uma coisa em comum. Todos são responsáveis por destruir inúmeros navios em várias águas.)",
  ui_story_5070_50701001_8_dialog_content = "(Após um navio afundar, seus destroços serão empurrados pela corrente oceânica e acabarão no mesmo lugar debaixo d'água, formando um cemitério de navios.)",
  ui_story_5070_50701001_9_dialog_content = "(O lugar é aqui?)",
  ui_story_5070_50701001_10_dialog_content = "(Nunca pensei que um dia navegaria com um navio até um cemitério como este.)",
  ui_story_5070_50701001_11_dialog_content = "(Os esqueletos de navios quebrados estão empilhados, gradualmente cobertos por corais e algas marinhas, erodindo e apodrecendo.",
  ui_story_5070_50701001_12_dialog_content = "(É como se o mar estivesse realizando um funeral para se despedir desses navios.)",
  ui_story_5070_50701001_13_dialog_content = "(... Aquele navio!)",
  ui_story_5070_50701001_14_dialog_content = "Em um momento, Ministra Armilla, jovem amigo, você pode resgatar mais desses fragmentos de navio para mim?",
  ui_story_5070_50701001_15_dialog_content = "Esses fragmentos me parecem um pouco familiares.",
  ui_story_5070_50701001_16_dialog_content = "Até onde eu posso ver, não há diferença alguma entre esses pedaços de madeira.",
  ui_story_5070_50701001_17_dialog_content = "Qualquer coisa pode te dizer algo se você olhar atentamente o suficiente.",
  ui_story_5070_50701001_18_dialog_content = "Eu posso não ser tão bom quanto Zhong Xu, mas ainda posso aproveitar bastante.",
  ui_story_5070_50701001_19_dialog_content = "Veja, esta peça tem o nome do navio nela.",
  ui_story_5070_50701001_20_dialog_content = "E este aqui tem Buracos da Sorte.",
  ui_story_5070_50701001_21_dialog_content = "Não é apenas uma lacuna quebrada?",
  ui_story_5070_50701001_22_dialog_content = "Não, esses furos foram feitos deliberadamente.",
  ui_story_5070_50701001_23_dialog_content = "Para guardar amuletos da sorte, como moedas ou espelhos, dentro.",
  ui_story_5070_50701001_24_dialog_content = "É para garantir uma navegação tranquila.",
  ui_story_5070_50701001_25_dialog_content = "Mas, como foi encontrado em um naufrágio, é provável que a tripulação e os passageiros tenham desaparecido... O destino é caprichoso.",
  ui_story_5070_50701001_26_dialog_content = "Quanto mais destroços são retirados, mais sinto que este lugar é realmente perigoso...",
  ui_story_5070_50701001_27_dialog_content = "Para que essa expressão, Zhong Xu...? O que você está vendo?",
  ui_story_5070_50701001_28_dialog_content = "Um desses navios pertencia a piratas.",
  ui_story_5070_50701001_29_dialog_content = "Piratas?!",
  ui_story_5070_50701001_30_dialog_content = "Já tive muitos contatos com eles, então acredito que estou certo.",
  ui_story_5070_50701001_31_dialog_content = "Mas os piratas vagam pelo mar o ano inteiro e são muito mais cautelosos com águas perigosas do que pessoas comuns.",
  ui_story_5070_50701001_32_dialog_content = "Eu me pergunto se eles foram trazidos aqui pelo vento ou perseguidos por algo.",
  ui_story_5070_50701001_33_dialog_content = "Isso parece um pouco assustador... Já sentimos a pressão dos Eclipsitas, tempestades e monstros marinhos!",
  ui_story_5070_50701001_34_dialog_content = "E agora precisamos nos preocupar com o que destruiu o navio dos piratas e se isso é uma ameaça para nós?!",
  ui_story_5070_50701001_35_dialog_content = "<color=#e8d9bb>Splash...</color>",
  ui_story_5070_50701001_36_dialog_content = "É a Yuebai! Ela apareceu!",
  ui_story_5070_50701001_37_dialog_content = "Sei onde isso é.",
  ui_story_5070_50701001_38_dialog_content = "Abaixo de nós está um navio de pesca oceânica que naufragou há vários anos.",
  ui_story_5070_50701001_39_dialog_content = "Com base na rota que deveria ter sido seguida, este deve ser um ponto de encontro entre as águas do oceano e Longzhou.",
  ui_story_5070_50701001_40_dialog_content = "Então isso não significa...",
  ui_story_5070_50701001_41_dialog_content = "Sim, isso significa que não estamos longe de Longzhou.",
  ui_story_5070_50701001_42_dialog_content = "Isso é ótimo!",
  ui_story_5070_50701001_43_dialog_content = "É muito cedo para relaxar.",
  ui_story_5070_50701001_44_dialog_content = "Este lugar é famoso por ser um local de morte no mar. Não há cartas náuticas correspondentes para estas águas e não está na rota estabelecida do Shadowind.",
  ui_story_5070_50701001_45_dialog_content = "Mesmo que saibamos sua localização aproximada, não conseguiremos determinar para qual direção devemos navegar.",
  ui_story_5070_50701001_46_dialog_content = "Também estamos ficando sem comida, então não temos tempo a perder.",
  ui_story_5070_50701001_47_dialog_content = "Você poderia pedir a Zhong Xu e Xuan Ji para colocar o motor em máxima velocidade, e assim podemos sair daqui?",
  ui_story_5070_50701001_48_dialog_content = "Não. Há muitos redemoinhos por aqui. Um erro e podemos acabar descansando no cemitério de navios no fundo do mar.",
  ui_story_5070_50701001_49_dialog_content = "Mesmo que eles estejam aqui, nossa situação ainda será desesperadora. A menos que...",
  ui_story_5070_50701001_50_dialog_content = "A menos que...?",
  ui_story_5070_50701001_51_dialog_content = "A menos que alguém tenha percebido que o Shadowind saiu do curso há um tempo e já planejou uma contramedida.",
  ui_story_5070_50701001_52_dialog_content = "A primeira pessoa a perceber o bocejo... Xuan Ji?",
  ui_story_5070_50701001_53_dialog_content = "...",
  ui_story_5070_50701001_54_dialog_content = "Ei, não me olhe assim.",
  ui_story_5070_50701001_55_dialog_content = "Eu tenho uma ideia, mas...",
  ui_story_5070_50701001_56_dialog_content = "É tudo ou nada.",
  ui_story_5070_50701001_57_dialog_content = "Mesmo estando em apuros, ainda podemos avançar aos poucos no Shadowind.",
  ui_story_5070_50701001_58_dialog_content = "Mas se tentarmos isso e falharmos, o navio inteiro será consumido pelas chamas.",
  ui_story_5070_50701001_59_dialog_content = "E nos tornamos comida de peixe.",
  ui_story_5070_50701001_60_dialog_content = "É muito arriscado, a menos que seja o último recurso.",
  ui_story_5070_50701001_61_dialog_content = "Capitão! Capitão! Más notícias, neblina à frente!",
  ui_story_5070_50701001_62_dialog_content = "Não conseguimos ver muito ao nosso redor agora; o que devemos fazer?",
  ui_story_5070_50701001_63_dialog_content = "Tentar navegar em uma névoa tão densa é como caminhar em direção a uma morte certa de olhos fechados.",
  ui_story_5070_50701001_64_dialog_content = "Mas já não temos escolha.",
  ui_story_5070_50701001_65_dialog_content = "Está bem.",
  ui_story_5070_50701001_66_dialog_content = "Guardei algo especial no porão quando embarquei.",
  ui_story_5070_50701001_67_dialog_content = "Pode fornecer energia para todos os tipos de gadgets.",
  ui_story_5070_50701001_68_dialog_content = "Caranguejo de Fogo, Dragão de Água, até mesmo o queimador que impulsiona o Shadowind...",
  ui_story_5070_50701001_69_dialog_content = "Todos podem ter um desempenho como nunca antes sob seu poder.",
  ui_story_5070_50701001_70_dialog_content = "Mas é instável e muito desafiador de controlar.",
  ui_story_5070_50701001_71_dialog_content = "Está registrado que em vários testes, a produção foi tão excessiva...",
  ui_story_5070_50701001_72_dialog_content = "O alvo não era durável o suficiente e se autodestruiu.",
  ui_story_5070_50701001_73_dialog_content = "Então, mesmo que decidamos usá-lo, preciso testá-lo debaixo d'água primeiro.",
  ui_story_5070_50701001_74_dialog_content = "O Shadowind também terá que passar por modificações para que possa pelo menos suportar o impacto operacional.",
  ui_story_5070_50701001_75_dialog_content = "Caso contrário, não será nossa última esperança, mas sim a nossa morte.",
  ui_story_5070_50701001_76_dialog_content = "Vou te dar uma lista dos materiais do Shadowind mais tarde. Apenas faça o que você precisa fazer.",
  ui_story_5070_50701001_77_dialog_content = "Também vou avisar os carpinteiros navais para seguirem suas ordens.",
  ui_story_5070_50701001_78_dialog_content = "Talvez minhas Artes da Força Flamejante também sejam úteis.",
  ui_story_5070_50701001_79_dialog_content = "Por que eu não vou cuidar do peixe que acabamos de pescar e prepará-lo de uma maneira que você ache inovadora?",
  ui_story_5070_50701001_80_dialog_content = "Mas eu... O que posso fazer?",
  ui_story_5070_50701001_81_dialog_content = "Tenho que procurar coisas no porão, PlayerName.",
  ui_story_5070_50701001_82_dialog_content = "Você se importaria de encontrar o pequenino e pegar algumas poções para resistir aos vapores tóxicos?",
  ui_story_5070_50701001_83_dialog_content = "Você está me dizendo que Xuan Ji trouxe um Flame Sprite a bordo?!",
  ui_story_5070_50701001_84_dialog_content = "Eu estava me perguntando por que eu continuava sentindo esse cheiro a bordo! Quase pensei que havia algo errado com meu nariz!",
  ui_story_5070_50701001_85_dialog_content = "Então ela está por trás disso. Que coisa perigosa a se fazer...",
  ui_story_5070_50701001_86_dialog_content = "De acordo com o Mestre Bu, um ser antigo e senciente como esse poderia controlar o yin e o yang e transformar o dia em noite!",
  ui_story_5070_50701001_87_dialog_content = "Suspiro, isso vai ser um aborrecimento.",
  ui_story_5070_50701001_88_dialog_content = "Tome este remédio e diga a ela para não explodir este navio.",
  ui_story_5070_50701001_89_dialog_content = "Eu tenho o remédio, Xuan Ji.",
  ui_story_5070_50701001_90_dialog_content = "Mas do que exatamente você está falando?",
  ui_story_5070_50701001_91_dialog_content = "Acabei de recontar sua descrição, e Liqing imediatamente começou a fazer um escândalo.",
  ui_story_5070_50701001_92_dialog_content = "Todos os outros pareciam entender. Sou só eu que me sinto completamente no escuro?",
  ui_story_5070_50701001_93_dialog_content = "Bem, isso não é para você dizer, PlayerName.",
  ui_story_5070_50701001_94_dialog_content = "Não tenho certeza se sei mais do que você sobre este navio.",
  ui_story_5070_50701001_95_dialog_content = "Eu?",
  ui_story_5070_50701001_96_dialog_content = "Você saberá assim que eu tirar.",
  ui_story_5070_50701001_97_dialog_content = "Tirar? De onde?",
  ui_story_5070_50701001_98_dialog_content = "Falando nisso, eu queria perguntar há um tempo... Por que há tantas vacas de madeira no porão?",
  ui_story_5070_50701001_99_dialog_content = "São bois de madeira, o artefato mais comum em Longzhou e que existem há gerações.",
  ui_story_5070_50701001_100_dialog_content = "Eles são principalmente usados para transportar mercadorias, embora também sejam adequados para transportar bagagens.",
  ui_story_5070_50701001_101_dialog_content = "Basta abrir assim e você consegue tirar as coisas.",
  ui_story_5070_50701001_102_dialog_content = "É bem espaçoso por dentro. Provavelmente daria para caber uma pessoa ali.",
  ui_story_5070_50701001_103_dialog_content = "Quer tentar?",
  ui_story_5070_50701001_104_dialog_content = "De jeito nenhum! Não tenho interesse em me tornar uma mercadoria.",
  ui_story_5070_50701001_105_dialog_content = "Foi o que eu pensei também.",
  ui_story_5070_50701001_106_dialog_content = "Vamos conferir a estrela do show de hoje então.",
  ui_story_5070_50701001_107_dialog_content = "Essa caixinha?",
  ui_story_5070_50701001_108_dialog_content = "Não subestime isso.",
  ui_story_5070_50701001_109_dialog_content = "Qianyun, minha escola, é uma das melhores fabricantes de dispositivos em Ye e até mesmo em toda Longzhou.",
  ui_story_5070_50701001_110_dialog_content = "Orgulha-se de um legado de técnicas secretas e artefatos por séculos.",
  ui_story_5070_50701001_111_dialog_content = "Mas você pode juntar tudo isso e ainda assim talvez não se compare a isso.",
  ui_story_5070_50701001_112_dialog_content = "Um dos maiores motivos para eu visitar Astra é...",
  ui_story_5070_50701001_113_dialog_content = "Para encontrar o tesouro inestimável perdido no exterior há muitos anos...",
  ui_story_5070_50701001_114_dialog_content = "A Chama Zhuyin.",
  ui_story_5070_50701001_115_dialog_content = "Do ponto de vista de Astra, também é uma relíquia antiga preciosa.",
  ui_story_5070_50701001_116_dialog_content = "Relíquia antiga?!",
  ui_story_5070_50701001_117_dialog_content = "Quer ver o quão poderoso é?",
  ui_story_5070_50701001_118_dialog_content = "É um pouco arriscado no Shadowind. Vamos testá-lo em um bote pequeno, bem longe.",
  ui_story_5070_50701001_119_dialog_content = "Veja a verdadeira obra-prima dos tempos antigos que fornecia energia para tudo.",
  ui_story_5070_50701002_1_dialog_content = "Certamente se encaixa como uma relíquia antiga. É ainda mais poderoso do que eu esperava.",
  ui_story_5070_50701002_2_dialog_content = "Você também sentiu isso com seus poderes psíquicos, certo, PlayerName? Como se sente?",
  ui_story_5070_50701002_3_dialog_content = "Bem legal.",
  ui_story_5070_50701002_4_dialog_content = "Não só pode impulsionar infinitamente as Feras Mecânicas, que já estão sem energia, mas também pode...",
  ui_story_5070_50701002_5_dialog_content = "Também evapora toda a umidade ao redor, criando um vácuo.",
  ui_story_5070_50701002_6_dialog_content = "Em resposta, parece mais substancial do que todas as outras chamas, até mesmo como...",
  ui_story_5070_50701002_7_dialog_content = "Um sol em miniatura?",
  ui_story_5070_50701002_8_dialog_content = "Totalmente... Espere, essa não é a minha própria descrição?",
  ui_story_5070_50701002_9_dialog_content = "A Chama Zhuyin... Isso poderia ter causado a explosão no navio naquele dia!",
  ui_story_5070_50701002_10_dialog_content = "Ops, pegos.",
  ui_story_5070_50701002_11_dialog_content = "Você não concordou que eu desse uma olhada usando minha habilidade? Eu apenas obedeci!",
  ui_story_5070_50701002_12_dialog_content = "Afinal, ver é acreditar. Isso te mostra mais do que eu jamais poderia explicar!",
  ui_story_5070_50701002_13_dialog_content = "Não é à toa que Liqing teve uma reação tão forte.",
  ui_story_5070_50701002_14_dialog_content = "Quem poderia imaginar que haveria algo tão perigoso a bordo?",
  ui_story_5070_50701002_15_dialog_content = "Vedei cuidadosamente antes de trazê-lo a bordo para garantir sua segurança.",
  ui_story_5070_50701002_16_dialog_content = "Mas alguém abriu intencionalmente no dia do incêndio.",
  ui_story_5070_50701002_17_dialog_content = "Eu trouxe a bordo em segredo.",
  ui_story_5070_50701002_18_dialog_content = "Até Yuebai não sabia o que era, e eu até dei um aviso prévio para ela.",
  ui_story_5070_50701002_19_dialog_content = "Mas alguém sabia disso e tentou se aproximar.",
  ui_story_5070_50701002_20_dialog_content = "Será que aquela figura que vi mais cedo poderia ser...?!",
  ui_story_5070_50701002_21_dialog_content = "Temo que sim.",
  ui_story_5070_50701002_22_dialog_content = "Para esse tipo de coisa... Precisamos avisar os outros imediatamente.",
  ui_story_5070_50701002_23_dialog_content = "Acontece que o teste da Chama Zhuyin foi bem-sucedido, então o Shadowind pode sair daqui imediatamente.",
  ui_story_5070_50701002_24_dialog_content = "Aproveite o momento para pegar aquele cara malévolo—",
  ui_story_5070_50701002_25_dialog_content = "Eu não me lembro de declarar o teste como bem-sucedido.",
  ui_story_5070_50701002_26_dialog_content = "O quê? Todos esses Animais Mecânicos não foram ativados sem problemas?",
  ui_story_5070_50701002_27_dialog_content = "Não há dúvida de que a Chama Zhuyin é uma fonte de energia, mas você não viu o que aconteceu com as feras mecânicas?",
  ui_story_5070_50701002_28_dialog_content = "... Estilhaçado em pedaços e caiu no mar.",
  ui_story_5070_50701002_29_dialog_content = "As feras não eram grandes, e mesmo assim isso era tudo que eu conseguia fazer com algum tipo de certeza.",
  ui_story_5070_50701002_30_dialog_content = "Então, mesmo que você fortaleça o Shadowind com todos os materiais que conseguir encontrar...",
  ui_story_5070_50701002_31_dialog_content = "Não vai resistir à Chama Zhuyin em seu poder máximo.",
  ui_story_5070_50701002_32_dialog_content = "Será que Xuan Ji realmente também não consegue resolver?",
  ui_story_5070_50701002_33_dialog_content = "Isso não é totalmente verdade.",
  ui_story_5070_50701002_34_dialog_content = "Mas até então, eu tenho um pedido, PlayerName.",
  ui_story_5070_50701002_35_dialog_content = "Por favor, mantenha o experimento fracassado e alguém de olho na Chama em segredo.",
  ui_story_5070_50701002_36_dialog_content = "Talvez... Mas o que devemos fazer agora?",
  ui_story_5070_50701002_37_dialog_content = "Apenas espere.",
  ui_story_5070_50701002_38_dialog_content = "<color=#e8d9bb>No dia seguinte...</color>",
  ui_story_5070_50701002_39_dialog_content = "Todos, venham pegar uma cópia da planta. Sigam as marcações e comecem a trabalhar nos locais designados.",
  ui_story_5070_50701002_40_dialog_content = "Que tipo de planta é esta?",
  ui_story_5070_50701002_41_dialog_content = "Eh... essa planta...",
  ui_story_5070_50701002_42_dialog_content = "Lido com navios a minha vida inteira e nunca vi algo assim em um navio...",
  ui_story_5070_50701002_43_dialog_content = "Ignorar o grande buraco no convés é uma coisa, mas aumentá-lo deliberadamente?",
  ui_story_5070_50701002_44_dialog_content = "Está quase expondo o núcleo do Shadowind. Isso é muito bizarro... Sol, o que você acha disso?",
  ui_story_5070_50701002_45_dialog_content = "Eu... também não entendo...",
  ui_story_5070_50701002_46_dialog_content = "Por que se preocupar com tudo isso? A senhora Xuan Ji é muito mais habilidosa do que nós, certo?",
  ui_story_5070_50701002_47_dialog_content = "Vamos trabalhar agora; assim que terminarmos, podemos sair daqui com certeza.",
  ui_story_5070_50701002_48_dialog_content = "<color=#e8d9bb>Terceiro dia</color>",
  ui_story_5070_50701002_49_dialog_content = "Pessoal, venham pescar comigo.",
  ui_story_5070_50701002_50_dialog_content = "Ah, quantos dias estamos sobrevivendo com peixe? E agora, até o tempero está acabando. Eles têm um gosto... Palavras nem conseguem descrever isso.",
  ui_story_5070_50701002_51_dialog_content = "Aguente só mais alguns dias. As coisas vão melhorar assim que a reforma do navio estiver concluída.",
  ui_story_5070_50701002_52_dialog_content = "<color=#e8d9bb>Dia Cinco</color>",
  ui_story_5070_50701002_53_dialog_content = "A névoa em nosso local de pesca está ficando mais espessa; mal conseguimos pegar peixes agora.",
  ui_story_5070_50701002_54_dialog_content = "Não terminamos a renovação do Shadowind? Por que a Senhora Xuan Ji não nos deu mais instruções...",
  ui_story_5070_50701002_55_dialog_content = "Li, não conte a ninguém, mas ouvi do Sun, o Habilidoso, que nossos esforços nesta reforma são inúteis.",
  ui_story_5070_50701002_56_dialog_content = "Você não percebeu que a Senhora Xuan Ji sai em um pequeno barco todos os dias? Ele diz que é para exploração, mas parece que ele está tentando esconder o quanto ele não tem ideia do que está fazendo!",
  ui_story_5070_50701002_57_dialog_content = "Que bobagem vocês estão falando? E você, Sun, não deixe o Capitão Yuebai te pegar espalhando boatos infundados...",
  ui_story_5070_50701002_58_dialog_content = "Ei! PlayerName! PlayerName!",
  ui_story_5070_50701002_59_dialog_content = "Você tem saído com a Senhora Xuan Ji nos últimos dias. Você ouviu algo sobre como vamos sair daqui?",
  ui_story_5070_50701002_60_dialog_content = "Bem, tudo o que posso dizer é que há um jeito... Eu-Eu tenho que dar algo para Xuan Ji, então estou indo!",
  ui_story_5070_50701002_61_dialog_content = "Ufa...",
  ui_story_5070_50701002_62_dialog_content = "Venha rápido, PlayerName. Fiz modificações estruturais semelhantes de acordo com sua descrição do Colosso.",
  ui_story_5070_50701002_63_dialog_content = "O quê? Parece que você deu mais uma rodada com a equipe.",
  ui_story_5070_50701002_64_dialog_content = "Haha... Afinal, estamos aqui há vários dias. Todos estão um pouco nervosos e querem sair daqui o mais rápido possível.",
  ui_story_5070_50701002_65_dialog_content = "Este modelo, bem, comparado com a Colossus, parece mais um Shadowind com asas. Deixe-me ver...",
  ui_story_5070_50701002_66_dialog_content = "Você não tem nenhuma pergunta para mim, PlayerName?",
  ui_story_5070_50701002_67_dialog_content = "O quê?",
  ui_story_5070_50701002_68_dialog_content = "Eu pedi para você guardar um segredo sem te dar uma explicação concreta.",
  ui_story_5070_50701002_69_dialog_content = "Então, instruí os outros a fazerem tantas modificações apenas para ficar em um bote o dia todo e evitar todas as perguntas.",
  ui_story_5070_50701002_70_dialog_content = "Até eu suspeitaria que estou tramando algo de ruim.",
  ui_story_5070_50701002_71_dialog_content = "Por que você confiou em mim, PlayerName?",
  ui_story_5070_50701002_72_dialog_content = "Eu realmente não acredito em você.",
  ui_story_5070_50701002_73_dialog_content = "Pensei assim...",
  ui_story_5070_50701002_74_dialog_content = "Mas eu acredito em máquinas.",
  ui_story_5070_50701002_75_dialog_content = "Hã?",
  ui_story_5070_50701002_76_dialog_content = "Com certeza, não foi exatamente relaxante lidar com aquelas Feras Mecânicas que surgiram do nada.",
  ui_story_5070_50701002_77_dialog_content = "Mas na primeira vez que nos encontramos, uma libélula me ajudou a pegar a carta.",
  ui_story_5070_50701002_78_dialog_content = "Caranguejos de fogo para impulsionar o motor, dragões de água para apagar incêndios...",
  ui_story_5070_50701002_79_dialog_content = "Fui ajudado por criaturas mecânicas várias vezes.",
  ui_story_5070_50701002_80_dialog_content = "Você mesmo disse, Xuan Ji: A maquinaria não é uma tecnologia sempre em mudança e onipotente.",
  ui_story_5070_50701002_81_dialog_content = "Acredito em maquinário, sobre o qual você nunca mentiria.",
  ui_story_5070_50701002_82_dialog_content = "Então, eu também acredito que você encontrará uma maneira de nos levar com segurança a Longzhou.",
  ui_story_5070_50701002_83_dialog_content = "Isso é.",
  ui_story_5070_50701002_84_dialog_content = "Bem, não posso refutar isso de jeito nenhum.",
  ui_story_5070_50701002_85_dialog_content = "Levando em consideração o que você disse, PlayerName...",
  ui_story_5070_50701002_86_dialog_content = "Seria uma falha minha como artesão não mostrar a você o potencial do meu ofício.",
  ui_story_5070_50701002_87_dialog_content = "Estou ansioso para isso. Mas estaria mentindo se dissesse que não estou curioso.",
  ui_story_5070_50701002_88_dialog_content = "O que exatamente você está esperando, Xuan Ji?",
  ui_story_5070_50701002_89_dialog_content = "Bom, na verdade...",
  ui_story_5070_50701002_90_dialog_content = "<color=#e8d9bb>Explosão de assobio</color>",
  ui_story_5070_50701002_91_dialog_content = "Qual é esse som vindo do Shadowind? Por que a buzina está tocando?",
  ui_story_5070_50701002_92_dialog_content = "Esse é o sinal para comunicação entre navios no mar.",
  ui_story_5070_50701002_93_dialog_content = "Poderia haver outro navio?!",
  ui_story_5070_50701002_94_dialog_content = "<color=#e8d9bb>Há pouco tempo</color>",
  ui_story_5070_50701002_95_dialog_content = "Jiu, Yuebai, vem ver isso.",
  ui_story_5070_50701002_96_dialog_content = "É um navio lá fora?",
  ui_story_5070_50701002_97_dialog_content = "Alteza, por favor, afaste-se do lado do navio.",
  ui_story_5070_50701002_98_dialog_content = "Não é isso que você deveria se preocupar, Jiu.",
  ui_story_5070_50701002_99_dialog_content = "Sua segurança é de extrema importância, então devemos tomar todos os cuidados necessários.",
  ui_story_5070_50701002_100_dialog_content = "Não consigo ver o que está acontecendo no navio, mas alguns navios mercantes estão vindo em nossa direção.",
  ui_story_5070_50701002_101_dialog_content = "Nunca pensei que encontraríamos outros navios nessas águas.",
  ui_story_5070_50701002_102_dialog_content = "Devemos entrar em contato com eles? Eu me pergunto se eles têm muitos suprimentos. Se não tiverem...",
  ui_story_5070_50701002_103_dialog_content = "Provavelmente já é tarde demais para evitá-los agora, de qualquer maneira.",
  ui_story_5070_50701002_104_dialog_content = "Toque a buzina e veja como eles reagem.",
  ui_story_5070_50701002_105_dialog_content = "<color=#e8d9bb>Explosão de apito</color>",
  ui_story_5070_50701002_106_dialog_content = "<color=#e8d9bb>Explosão de apito</color>",
  ui_story_5070_50701002_107_dialog_content = "Resposta recebida!",
  ui_story_5070_50701002_108_dialog_content = "É um navio que também está preso aqui? Perfeito, podemos pensar em uma saída juntos.",
  ui_story_5070_50701002_109_dialog_content = "Talvez possamos trocar um pouco de comida e água com eles também.",
  ui_story_5070_50701002_110_dialog_content = "Então, vamos voltar ao navio e descobrir isso.",
  ui_story_5070_50701002_111_dialog_content = "Estou de olho neles. Eles estão claramente se aproximando do Shadowind.",
  ui_story_5070_50701002_112_dialog_content = "Hã... Eles não estão indo um pouco rápido?",
  ui_story_5070_50701002_113_dialog_content = "Eles não estão apenas deixando de desacelerar, mas na verdade estão acelerando?!",
  ui_story_5070_50701002_114_dialog_content = "<color=#e8d9bb>Bang—!</color>",
  ui_story_5070_50701002_115_dialog_content = "Como... Como aquele navio poderia simplesmente atacar o Shadowind?!",
  ui_story_5070_50701002_116_dialog_content = "Essa não...",
  ui_story_5070_50701002_117_dialog_content = "É um barco pirata!",
  ui_story_5070_50701002_118_dialog_content = "Rápido, PlayerName, Shadowind está em apuros!",
  ui_story_5070_50701101_1_dialog_content = "Por que vocês, delinquentes insolentes! Como ousam fazer isso com Jiu...",
  ui_story_5070_50701101_2_dialog_content = "Espere!",
  ui_story_5070_50701101_3_dialog_content = "<color=#e8d9bb>Vuuush—</color>",
  ui_story_5070_50701101_4_dialog_content = "<color=#e8d9bb>O convés aos pés de Dantang é atingido, queimando um grande buraco.</color>",
  ui_story_5070_50701101_5_dialog_content = "...",
  ui_story_5070_50701101_6_dialog_content = "Sua Alteza, sei que não é meu lugar dizer isso; arrisco-me a lembrá-lo...",
  ui_story_5070_50701101_7_dialog_content = "Pode ser bom ganhar uma discussão, mas no mar, é melhor prevenir do que remediar.",
  ui_story_5070_50701101_8_dialog_content = "Parece que Dantang está sendo atacado! Vamos subir lá rapidamente—",
  ui_story_5070_50701101_9_dialog_content = "Espere, eles sabem quem somos, então acho que nada de ruim vai acontecer com a princesa e Jiu.",
  ui_story_5070_50701101_10_dialog_content = "Mas ainda não sabemos o que eles estão planejando, então só seremos capturados se subirmos agora.",
  ui_story_5070_50701101_11_dialog_content = "Apenas fique escondido e entenda a situação antes de tomar uma atitude.",
  ui_story_5070_50701101_12_dialog_content = "Hum... A voz de quem estava falando com Dantang pareceu um pouco familiar?",
  ui_story_5070_50701101_13_dialog_content = "Esse é o Sol Habilidoso.",
  ui_story_5070_50701101_14_dialog_content = "Ele?!",
  ui_story_5070_50701101_15_dialog_content = "Shhh.",
  ui_story_5070_50701101_16_dialog_content = "Continue ouvindo.",
  ui_story_5070_50701101_17_dialog_content = "Você não é o verdadeiro Sol Habilidoso, certo?",
  ui_story_5070_50701101_18_dialog_content = "Hehe, Sun, o Habilidoso, não passa de uma fachada.",
  ui_story_5070_50701101_19_dialog_content = "Mas para pessoas humildes como você, só conhecem a mim como Sun, o Habilidoso.",
  ui_story_5070_50701101_20_dialog_content = "Você... Não acredito que realmente se aliou aos piratas!",
  ui_story_5070_50701101_21_dialog_content = "Você esqueceu o favor que a família Lin nos fez? Seu traidor traiçoeiro...",
  ui_story_5070_50701101_22_dialog_content = "Cale-se!",
  ui_story_5070_50701101_23_dialog_content = "Controle-se se não quiser se afogar lá embaixo junto com a Srta. Jiu.",
  ui_story_5070_50701101_24_dialog_content = "Lembre-se: o guerreiro mais habilidoso deste navio já bateu as botas.",
  ui_story_5070_50701101_25_dialog_content = "Acho que não há muito espaço para luta do seu lado.",
  ui_story_5070_50701101_26_dialog_content = "Isso é porque você recorreu a táticas deploráveis!",
  ui_story_5070_50701101_27_dialog_content = "Jiu não estaria em desvantagem sem aquele raio peculiar!",
  ui_story_5070_50701101_28_dialog_content = "Recorrendo a insultos, hein? Princesa, eu realmente sugiro que você cuide da sua língua.",
  ui_story_5070_50701101_29_dialog_content = "É uma criação mecânica maravilhosa, comparável com... Não, ela ofusca totalmente o Shadowind!",
  ui_story_5070_50701101_30_dialog_content = "Qualquer um pode se gabar.",
  ui_story_5070_50701101_31_dialog_content = "Quão honrado você pode ser ao se esconder em seu barco e só atacar à distância?",
  ui_story_5070_50701101_32_dialog_content = "(Isso mesmo, Princesa Dantang. Continue irritando-o intencionalmente.)",
  ui_story_5070_50701101_33_dialog_content = "(Precisamos obter o máximo de informações possível antes que Jiu e os outros retornem.)",
  ui_story_5070_50701101_34_dialog_content = "Além de lançar um ataque surpresa, tudo o que seus homens fizeram depois de embarcar em nosso navio foi capturar Zhong Xu e Liqing.",
  ui_story_5070_50701101_35_dialog_content = "Vocês são um grupo de covardes que só têm coragem de atacar um homem deficiente e uma criança.",
  ui_story_5070_50701101_36_dialog_content = "Vamos nos separar.",
  ui_story_5070_50701101_37_dialog_content = "Essa criação obviamente possui uma saída poderosa para projetar o raio letal.",
  ui_story_5070_50701101_38_dialog_content = "Preciso ir dar uma olhada mais de perto.",
  ui_story_5070_50701101_39_dialog_content = "Eu?",
  ui_story_5070_50701101_40_dialog_content = "Fique no barco e fique de olho no Shadowind.",
  ui_story_5070_50701101_41_dialog_content = "Certifique-se de se manter escondido. Eu tenho que ir—",
  ui_story_5070_50701101_42_dialog_content = "Isso não é chamado de divisão de trabalho.",
  ui_story_5070_50701101_43_dialog_content = "?",
  ui_story_5070_50701101_44_dialog_content = "Isso é apenas me deixar em algum lugar seguro, enquanto você assume os riscos.",
  ui_story_5070_50701101_45_dialog_content = "De alguma forma...",
  ui_story_5070_50701101_46_dialog_content = "Mas o tempo é precioso.",
  ui_story_5070_50701101_47_dialog_content = "Eu quero voltar para o Shadowind. Embora eu não possa lutar como você...",
  ui_story_5070_50701101_48_dialog_content = "Deve haver algo que eu possa fazer lá em cima.",
  ui_story_5070_50701101_49_dialog_content = "Mesmo que você seja descoberto, talvez eu consiga ganhar algum tempo para você.",
  ui_story_5070_50701101_50_dialog_content = "Isso é chamado de divisão de trabalho.",
  ui_story_5070_50701101_51_dialog_content = "E se eu rejeitar essa ideia?",
  ui_story_5070_50701101_52_dialog_content = "Então vou esperar você ir e depois me esgueirar para dentro do navio.",
  ui_story_5070_50701101_53_dialog_content = "Não me diga que se lançar de cabeça no perigo é uma característica dos Celestitas.",
  ui_story_5070_50701101_54_dialog_content = "Querer proteger todos que estão atrás deles e fazer tudo sozinhos é uma coisa de artesão?",
  ui_story_5070_50701101_55_dialog_content = "Acho que isso nos torna iguais.",
  ui_story_5070_50701101_56_dialog_content = "Você confia em mim, PlayerName...",
  ui_story_5070_50701101_57_dialog_content = "Então, se eu não confiar em você em troca, PlayerName, isso seria bastante injusto.",
  ui_story_5070_50701101_58_dialog_content = "Bem, então, boa sorte.",
  ui_story_5070_50701102_1_dialog_content = "Aumento de Força! Lembrei de algo que esqueceu—",
  ui_story_5070_50701102_2_dialog_content = "Ei! Será que o chefe esqueceu da minha recompensa? Tenho que ir lembrá-lo...",
  ui_story_5070_50701102_3_dialog_content = "<color=#e8d9bb>Bate, baque, baque!</color>",
  ui_story_5070_50701102_4_dialog_content = "(Ótimo, esses piratas de Longzhou não têm conhecimento ou experiência com as habilidades telepáticas dos Celestitas.)",
  ui_story_5070_50701102_5_dialog_content = "(Então, posso dar uma cutucada silenciosa assim, sugerindo que aqueles que estão preocupados possam sair dali por um tempo...)",
  ui_story_5070_50701102_6_dialog_content = "Por que o cara da porta sumiu? Ainda estamos patrulhando ou o quê?",
  ui_story_5070_50701102_7_dialog_content = "Tudo bem. Isso não vai atrapalhar nossa tarefa de qualquer maneira.",
  ui_story_5070_50701102_8_dialog_content = "Estamos apenas de olho em um aleijado e uma criança, ambos em jaulas. Você realmente precisa ficar tão tenso?",
  ui_story_5070_50701102_9_dialog_content = "(Tantos piratas! E na jaula mecânica... Zhong Xu e Liqing?!)",
  ui_story_5070_50701102_10_dialog_content = "(Eh? O que Liqing está fazendo?)",
  ui_story_5070_50701102_11_dialog_content = "*Cheira...*",
  ui_story_5070_50701102_12_dialog_content = "(Isso tem cheiro de... PlayerName!)",
  ui_story_5070_50701102_13_dialog_content = "(Aqui! Olhe pra cá—! Nossos olhos se encontraram!)",
  ui_story_5070_50701102_14_dialog_content = "Miau...",
  ui_story_5070_50701102_15_dialog_content = "O que você está fazendo? Tentando miar como um gato?",
  ui_story_5070_50701102_16_dialog_content = "Estou entediado. Você não pode me deixar sair para passear agora, pode?",
  ui_story_5070_50701102_17_dialog_content = "(O que significa Liqing?)",
  ui_story_5070_50701102_18_dialog_content = "Miau...",
  ui_story_5070_50701102_19_dialog_content = "(Tinytail! E ao lado de Zhong Xu... São Yixin, Yimeng e Yinuo, certo?)",
  ui_story_5070_50701102_20_dialog_content = "(De onde eles vieram?)",
  ui_story_5070_50701102_21_dialog_content = "Você ouve isso?! Tem algo acontecendo na porta?",
  ui_story_5070_50701102_22_dialog_content = "Ah, você provavelmente ouviu errado.",
  ui_story_5070_50701102_23_dialog_content = "Primeiro, você disse que o aleijado de cabelo vermelho parecia familiar, e agora está dizendo que algo está acontecendo na porta. Vamos lá, você pode me dar um descanso?",
  ui_story_5070_50701102_24_dialog_content = "Vou verificar.",
  ui_story_5070_50701102_25_dialog_content = "(!!!)",
  ui_story_5070_50701102_26_dialog_content = "(Sem tempo para me esconder. Só tenho uma chance nisso!)",
  ui_story_5070_50701102_27_dialog_content = "Por favor, me ajude a ganhar algum tempo!",
  ui_story_5070_50701102_28_dialog_content = "Miau!",
  ui_story_5070_50701102_29_dialog_content = "O que é isso?!",
  ui_story_5070_50701102_30_dialog_content = "De onde diabos veio esse gato selvagem? Some daqui! Sss... e ele realmente morde!",
  ui_story_5070_50701102_31_dialog_content = "(Agora é a hora, para todos na sala...)",
  ui_story_5070_50701102_32_dialog_content = "Provoque-os com Aumento de Força!",
  ui_story_5070_50701102_33_dialog_content = "Ah—por que minha cabeça está de repente latejando de dor?!",
  ui_story_5070_50701102_34_dialog_content = "Gato—! Um gato está arranhando meu rosto!",
  ui_story_5070_50701102_35_dialog_content = "PlayerName! Resgate Zhong Xu primeiro!",
  ui_story_5070_50701102_36_dialog_content = "Miau...",
  ui_story_5070_50701102_37_dialog_content = "Você trouxe a chave? Obrigado, Tinytail.",
  ui_story_5070_50701102_38_dialog_content = "Aguarde, Zhong Xu. Estou destravando agora mesmo.",
  ui_story_5070_50701102_39_dialog_content = "Obrigado, mas você não precisa se apressar, pois estou bem.",
  ui_story_5070_50701102_40_dialog_content = "Você pode não estar preocupado, mas eu estou! Você é muito lento, PlayerName! Eu vou fazer isso!",
  ui_story_5070_50701102_41_dialog_content = "Liqing?! Como você saiu?",
  ui_story_5070_50701102_42_dialog_content = "As aberturas dessa gaiola são tão grandes! Não consegue passar de lado?!",
  ui_story_5070_50701102_43_dialog_content = "Isso é algo que aurorianos comuns podem fazer...?",
  ui_story_5070_50701102_44_dialog_content = "Aurorianos normais não podem, mas eu não sou um auroriano comum.",
  ui_story_5070_50701102_45_dialog_content = "Não é comum?!",
  ui_story_5070_50701102_46_dialog_content = "Eu não te disse?",
  ui_story_5070_50701102_47_dialog_content = "Eu sou um gato.",
  ui_story_5070_50701102_48_dialog_content = "?!",
  ui_story_5070_50701102_49_dialog_content = "Para ser preciso, eu sou um gato Fiendling. Tinytail ali é meu irmão mais velho.",
  ui_story_5070_50701102_50_dialog_content = "I-Irmão...",
  ui_story_5070_50701102_51_dialog_content = "PlayerName? Qual o problema?",
  ui_story_5070_50701102_52_dialog_content = "Não há Fiendlings em Astra, então entendo por que você está tão chocado.",
  ui_story_5070_50701102_53_dialog_content = "Zhong Xu...",
  ui_story_5070_50701102_54_dialog_content = "O que foi?",
  ui_story_5070_50701102_55_dialog_content = "Você tem três gatos ao seu redor, mas... você não pode ser um Fiendling, certo?",
  ui_story_5070_50701102_56_dialog_content = "Você não vai de repente se transformar em um gato também?",
  ui_story_5070_50701102_57_dialog_content = "Hahaha! Eu realmente sou apenas uma pessoa comum, então tenho medo que você fique decepcionado.",
  ui_story_5070_50701102_58_dialog_content = "Não, não! Melhor dizer que é ótimo... E ainda é o mesmo e confiável Zhong Xu de sempre.",
  ui_story_5070_50701102_59_dialog_content = "Ah... você, vocês todos...",
  ui_story_5070_50701102_60_dialog_content = "PlayerName, esses malandros voltaram a si.",
  ui_story_5070_50701102_61_dialog_content = "E não são apenas eles. Um grupo está se aproximando da entrada. Eles devem estar vindo do convés.",
  ui_story_5070_50701102_62_dialog_content = "Cerque-os!",
  ui_story_5070_50701102_63_dialog_content = "O único lutador capaz aqui é o aleijado, mas ele é habilidoso apenas com as Artes da Força Flamejante.",
  ui_story_5070_50701102_64_dialog_content = "Enquanto abafarmos suas chamas, ele é inútil.",
  ui_story_5070_50701102_65_dialog_content = "Esses caras!",
  ui_story_5070_50701102_66_dialog_content = "Espere, Zhong Xu. Certifique-se de estar seguro primeiro, enquanto Liqing e eu elaboramos um plano.",
  ui_story_5070_50701102_67_dialog_content = "Huh? PlayerName, você não sabia? Na verdade...",
  ui_story_5070_50701102_68_dialog_content = "Eu agradeço suas boas intenções.",
  ui_story_5070_50701102_69_dialog_content = "O Lin Guildmaster... Ele era fraco e frágil, mas sempre me protegeu assim.",
  ui_story_5070_50701102_70_dialog_content = "Já tive negócios com essas pessoas por muitos anos, então acho que é destino ter sido capturado aqui.",
  ui_story_5070_50701102_71_dialog_content = "Talvez até os céus acreditem que é hora de eu resolver as coisas com esses piratas de uma vez por todas.",
  ui_story_5070_50701102_72_dialog_content = "Então, você pode por favor esperar um momento e deixar esses inimigos comigo?",
  ui_story_5070_50701102_73_dialog_content = "Ok. Vou fazer o meu melhor para apoiar—",
  ui_story_5070_50701102_74_dialog_content = "Isso não será necessário. Seus poderes estranhos provavelmente são mais úteis para a Princesa Dantang e a Ministra Armilla.",
  ui_story_5070_50701102_75_dialog_content = "Quanto a mim, eu só conheço um jeito de lutar e só preciso desse único jeito de lutar.",
  ui_story_5070_50701102_76_dialog_content = "Se você realmente quer me ajudar, então me devolva minha espada que foi levada mais cedo.",
  ui_story_5070_50701102_77_dialog_content = "Tudo bem, é esse aqui, não é...? É pesado!",
  ui_story_5070_50701102_78_dialog_content = "Eu agradeço.",
  ui_story_5070_50701102_79_dialog_content = "(No instante em que ele pegou a espada, os olhos de Zhong Xu pareceram mudar.)",
  ui_story_5070_50701102_80_dialog_content = "Ha, o que esse aleijado está falando? Ele realmente acha que pode lidar com todos nós sozinho!?",
  ui_story_5070_50701102_81_dialog_content = "Ele está muito além de sua capacidade—",
  ui_story_5070_50701102_82_dialog_content = "<color=#e8d9bb>Swish!</color>",
  ui_story_5070_50701102_83_dialog_content = "Hum...",
  ui_story_5070_50701102_84_dialog_content = "<color=#e8d9bb>O sorriso arrogante ainda não havia desaparecido de seu rosto, mas o corpo do pirata já havia caído no chão.</color>",
  ui_story_5070_50701102_85_dialog_content = "O que... o que ele acabou de fazer?",
  ui_story_5070_50701102_86_dialog_content = "Não entrem em pânico! Ele é apenas rápido com a espada! Somos tantos—Ah!",
  ui_story_5070_50701102_87_dialog_content = "Em vez de me dar esse elogio inadequado, eu preferiria que você apenas caísse.",
  ui_story_5070_50701102_88_dialog_content = "Ei! Quem disse que tudo ficaria bem, contanto que mantenhamos o fogo dele sob controle?",
  ui_story_5070_50701102_89_dialog_content = "Esse cara... Ele nem sequer usou seu fogo!",
  ui_story_5070_50701102_90_dialog_content = "O ímpeto dos piratas foi suprimido apenas por Zhong Xu sozinho.",
  ui_story_5070_50701102_91_dialog_content = "Claro, estamos falando sobre Zhong Xu aqui!",
  ui_story_5070_50701102_92_dialog_content = "Vá... VÁ PARA O INFERNO!",
  ui_story_5070_50701102_93_dialog_content = "Zhong Xu! Atrás de você!",
  ui_story_5070_50701102_94_dialog_content = "<color=#e8d9bb>Swish!</color>",
  ui_story_5070_50701102_95_dialog_content = "Ahhh!",
  ui_story_5070_50701102_96_dialog_content = "Minha preocupação foi em vão, já que Zhong Xu sacou sua espada mais rápido do que eu pude gritar.",
  ui_story_5070_50701102_97_dialog_content = "Viu? Mesmo em uma cadeira de rodas, esse grupo desorganizado não é nada para Zhong Xu.",
  ui_story_5070_50701102_98_dialog_content = "O naufrágio tirou minhas pernas de mim.",
  ui_story_5070_50701102_99_dialog_content = "<color=#e8d9bb>Swish!</color>",
  ui_story_5070_50701102_100_dialog_content = "E você também pode tentar suprimir minhas chamas ardentes.",
  ui_story_5070_50701102_101_dialog_content = "<color=#e8d9bb>Swish!</color>",
  ui_story_5070_50701102_102_dialog_content = "Mas enquanto eu ainda tiver um braço e uma espada.",
  ui_story_5070_50701102_103_dialog_content = "<color=#e8d9bb>Swish!</color>",
  ui_story_5070_50701102_104_dialog_content = "Continuarei a brandir minha espada e eliminar inimigos.",
  ui_story_5070_50701102_105_dialog_content = "Esta é a única maneira de lutar que eu conheço.",
  ui_story_5070_50701102_106_dialog_content = "Monstro... Um maldito monstro—!",
  ui_story_5070_50701102_107_dialog_content = "As pessoas costumavam me chamar assim há muitos anos atrás.",
  ui_story_5070_50701102_108_dialog_content = "Você... Espere, não me diga...",
  ui_story_5070_50701102_109_dialog_content = "Eu me lembro agora!",
  ui_story_5070_50701102_110_dialog_content = "Cabelo vermelho e uma túnica longa.",
  ui_story_5070_50701102_111_dialog_content = "Com apenas uma espada, ele consegue eliminar um navio cheio de piratas sozinho.",
  ui_story_5070_50701102_112_dialog_content = "O general que exterminou o último grupo de piratas que dominava as águas ao redor do Reino Ji... é você!",
  ui_story_5070_50701102_113_dialog_content = "O Grande General pessoalmente honrado pelo Imperador!",
  ui_story_5070_50701102_114_dialog_content = "Isso tudo está no passado agora.",
  ui_story_5070_50701102_115_dialog_content = "<color=#e8d9bb>Swish—</color>",
  ui_story_5070_50701102_116_dialog_content = "<color=#e8d9bb>O último inimigo cai no chão.</color>",
  ui_story_5070_50701102_117_dialog_content = "Agora sou apenas um andarilho...",
  ui_story_5070_50701102_118_dialog_content = "Ou um homem de meia-idade que possa oferecer ajuda aos mais jovens.",
  ui_story_5070_50701201_1_dialog_content = "<color=#e8d9bb>Enquanto isso, no navio inimigo</color>",
  ui_story_5070_50701201_2_dialog_content = "(Esse navio é construído como o Shadowind?!)",
  ui_story_5070_50701201_3_dialog_content = "<color=#e8d9bb>Zuuup...</color>",
  ui_story_5070_50701201_4_dialog_content = "!",
  ui_story_5070_50701201_5_dialog_content = "Devo me sentir honrado por ser cumprimentado dessa maneira.",
  ui_story_5070_50701201_6_dialog_content = "É claramente um ferrão de escorpião, mas não está soltando toxinas...",
  ui_story_5070_50701201_7_dialog_content = "Mas o raio de Lúmina do povo Astra?",
  ui_story_5070_50701201_8_dialog_content = "Graagh!",
  ui_story_5070_50701201_9_dialog_content = "A cauda é uma lança, as pinças são lâminas, com um casco grosso de metal...",
  ui_story_5070_50701201_10_dialog_content = "Ativação completa!",
  ui_story_5070_50701201_11_dialog_content = "<color=#e8d9bb>Ding—</color>",
  ui_story_5070_50701201_12_dialog_content = "Parece pedra, mas é leve como jade.",
  ui_story_5070_50701201_13_dialog_content = "Nenhum sinal de dano após o bombardeio. Acho que é feito de materiais raros.",
  ui_story_5070_50701201_14_dialog_content = "Sabe...",
  ui_story_5070_50701201_15_dialog_content = "Clic-clac...",
  ui_story_5070_50701201_16_dialog_content = "Essa coisa deve consumir muita energia.",
  ui_story_5070_50701201_17_dialog_content = "Mas não ficou mais fraco e até ficou mais forte depois de todas essas lutas.",
  ui_story_5070_50701201_18_dialog_content = "Que incrível deve ser o núcleo... Não deve haver mais do que alguns no mundo.",
  ui_story_5070_50701201_19_dialog_content = "Que coincidência, porém, que há outro no Shadowind.",
  ui_story_5070_50701201_20_dialog_content = "Se eu desmontar esse monstro, será que vou encontrar a fonte de energia...",
  ui_story_5070_50701201_21_dialog_content = "Ser outra Chama Zhuyin?",
  ui_story_5070_50701201_22_dialog_content = "Provavelmente você nem consegue desmontá-lo.",
  ui_story_5070_50701201_23_dialog_content = "Ah, finalmente se revelando.",
  ui_story_5070_50701201_24_dialog_content = "Primeiro, você se disfarçou de Sol, depois enviou esse grandalhão feio para cima de mim.",
  ui_story_5070_50701201_25_dialog_content = "Eu estava começando a pensar que você só fazia coisas quando tinha algo para se esconder.",
  ui_story_5070_50701201_26_dialog_content = "Heh, não vou me incomodar em discutir com você.",
  ui_story_5070_50701201_27_dialog_content = "Afinal, as palavras afiadas do perdedor apenas significam impotência.",
  ui_story_5070_50701201_28_dialog_content = "Perdedor? Pelo contrário.",
  ui_story_5070_50701201_29_dialog_content = "O motivo é que você tinha certeza de sua inferioridade e se convenceu de que era o perdedor.",
  ui_story_5070_50701201_30_dialog_content = "Você planejou e maquinou para conseguir o que pertencia a outras pessoas.",
  ui_story_5070_50701201_31_dialog_content = "Você roubou primeiro o projeto do Caranguejo de Fogo.",
  ui_story_5070_50701201_32_dialog_content = "Então, passaram a contrabandear peças e levaram os piratas a saquear o comerciante Lin.",
  ui_story_5070_50701201_33_dialog_content = "Agora você usou o mesmo truque para roubar a Chama Zhuyin para seu grotesco remendo.",
  ui_story_5070_50701201_34_dialog_content = "Eu tenho uma pergunta, no entanto.",
  ui_story_5070_50701201_35_dialog_content = "Vamos ouvir isso.",
  ui_story_5070_50701201_36_dialog_content = "Qianyun sempre se orgulhou de ser íntegro e ter uma reputação ilibada.",
  ui_story_5070_50701201_37_dialog_content = "Então, quando começou a promover roubo e táticas dissimuladas como essa?",
  ui_story_5070_50701201_38_dialog_content = "Hah...",
  ui_story_5070_50701201_39_dialog_content = "Ah, você me reconheceu.",
  ui_story_5070_50701201_40_dialog_content = "Mas tudo o que você se importa é com mecânica. Eu me pergunto se meu rosto ainda toca uma campainha.",
  ui_story_5070_50701201_41_dialog_content = "Já faz um tempo, Xuan Ji... minha irmã mais nova.",
  ui_story_5070_50701201_42_dialog_content = "Zhui Hu.",
  ui_story_5070_50701201_43_dialog_content = "Nem consegue me chamar de \"irmã mais velha\", hein? A ilustre Ministra Armilla realmente é diferente do passado.",
  ui_story_5070_50701201_44_dialog_content = "Você foi expulso há muito tempo e não tem o direito de se chamar de nada.",
  ui_story_5070_50701201_45_dialog_content = "Heh, palavras afiadas novamente... Sabe de uma coisa? Vou deixar passar desta vez.",
  ui_story_5070_50701201_46_dialog_content = "Afinal, você foi considerado um gênio pela seita desde a infância, sempre tendo as coisas do seu jeito. Mas agora, você não tem como lidar com as obras de um discípulo abandonado...",
  ui_story_5070_50701201_47_dialog_content = "Deve arder um pouco.",
  ui_story_5070_50701201_48_dialog_content = "Mas tudo bem. Embora você possa não se importar com os nossos velhos tempos, eu me importo.",
  ui_story_5070_50701201_49_dialog_content = "Então, considerando nosso passado compartilhado crescendo na seita, se você admitir honestamente a derrota, estou disposto a deixá-lo ir.",
  ui_story_5070_50701201_50_dialog_content = "Irmã mais nova, talvez você não saiba disso... mas a era dos estrategistas está prestes a começar!",
  ui_story_5070_50701201_51_dialog_content = "No cenário político em constante mudança dos oito reinos vassalos no futuro, talentos como você sempre encontrarão um ponto de apoio.",
  ui_story_5070_50701201_52_dialog_content = "Este navio sob seus pés. Considere-o meu presente de despedida para você. Que tal?",
  ui_story_5070_50701201_53_dialog_content = "De nada.",
  ui_story_5070_50701201_54_dialog_content = "Você não está atrás apenas da Chama Zhuyin, mas também do Shadowind.",
  ui_story_5070_50701201_55_dialog_content = "Mas eu não achei que você simplesmente me deixaria à deriva no mar para morrer.",
  ui_story_5070_50701201_56_dialog_content = "Realmente, não consigo esconder nada dos seus olhos perspicazes.",
  ui_story_5070_50701201_57_dialog_content = "Já que este navio é uma cópia do Shadowind, embora apenas na aparência e em nada comparável.",
  ui_story_5070_50701201_58_dialog_content = "Afinal, o núcleo do Shadowind foi criado através dos esforços combinados de muitos especialistas. É difícil para mim replicá-lo sozinho.",
  ui_story_5070_50701201_59_dialog_content = "Na verdade, minha missão original era apenas adquirir as plantas do Shadowind.",
  ui_story_5070_50701201_60_dialog_content = "Mas já que há uma chance de tomar o navio inteiro, por que não?",
  ui_story_5070_50701201_61_dialog_content = "Embora o atual Shadowind esteja bagunçado devido às suas alterações caprichosas...",
  ui_story_5070_50701201_62_dialog_content = "Mas eu não me importo em enfrentar essa bagunça.",
  ui_story_5070_50701201_63_dialog_content = "(Missão, você disse...)",
  ui_story_5070_50701201_64_dialog_content = "Comparado a conversar com aqueles jovens teimosos locais na masmorra, essa maneira de fazer as coisas é muito mais satisfatória.",
  ui_story_5070_50701201_65_dialog_content = "Então você também planejou o roubo do navio Lin?",
  ui_story_5070_50701201_66_dialog_content = "Rápido na compreensão, não é?",
  ui_story_5070_50701201_67_dialog_content = "Com essa técnica conveniente de disfarce e imitação...",
  ui_story_5070_50701201_68_dialog_content = "Era moleza se passar por um passageiro ou trabalhador do navio e derrubar as defesas do navio por dentro.",
  ui_story_5070_50701201_69_dialog_content = "Fiz preparações meticulosas na Baía dos Pavilhões Gêmeos, esperando reencenar o que aconteceu no Shadowind...",
  ui_story_5070_50701201_70_dialog_content = "Até que descobri que havia algo especial escondido na cabana.",
  ui_story_5070_50701201_71_dialog_content = "Eu nunca esperava que você, minha querida irmã mais nova, pudesse realmente encontrar a lendária Chama Zhuyin.",
  ui_story_5070_50701201_72_dialog_content = "E desde que criei essa fera mecânica, uma criação suprema que incorpora as forças de todas as escolas, não consegui encontrar uma fonte de energia adequada.",
  ui_story_5070_50701201_73_dialog_content = "Pode parecer uma coincidência, mas para mim, é o favor do destino!",
  ui_story_5070_50701201_74_dialog_content = "Suspirar...",
  ui_story_5070_50701201_75_dialog_content = "... O que você quer dizer com isso?",
  ui_story_5070_50701201_76_dialog_content = "Você nunca mudou.",
  ui_story_5070_50701201_77_dialog_content = "Neste momento, por que você ainda está tentando agir como o gênio da nossa seita e o mestre das máquinas?",
  ui_story_5070_50701201_78_dialog_content = "Ainda não aceitou a realidade, irmãzinha?",
  ui_story_5070_50701201_79_dialog_content = "Nem mesmo você pode deixar um arranhão na minha fera mecânica, minha maior criação!",
  ui_story_5070_50701201_80_dialog_content = "\"Sua\" fera mecânica?",
  ui_story_5070_50701201_81_dialog_content = "Você apenas copiou o design, roubou o núcleo e juntou peças poderosas.",
  ui_story_5070_50701201_82_dialog_content = "Há algo original nessa obra \"sua\"?",
  ui_story_5070_50701201_83_dialog_content = "Por que você está soando exatamente como aqueles velhos rígidos da seita?",
  ui_story_5070_50701201_84_dialog_content = "A arte das máquinas é apenas uma habilidade técnica; contanto que a criação em si seja forte o suficiente, não há necessidade de se preocupar com mais nada.",
  ui_story_5070_50701201_85_dialog_content = "Mesmo que seja eles, diante do meu Stinger aperfeiçoado, não terão escolha a não ser se curvar em derrota!",
  ui_story_5070_50701201_86_dialog_content = "É por isso que nossos mestres disseram que você nunca entendeu o significado dos aparelhos.",
  ui_story_5070_50701201_87_dialog_content = "Se eles te virem agora, provavelmente vão se arrepender de não poderem te expulsar pela segunda vez.",
  ui_story_5070_50701201_88_dialog_content = "...Eu não deveria ter perdido tanto tempo tentando falar com sensatez com você.",
  ui_story_5070_50701201_89_dialog_content = "Esmague-a, Stinger. Mostre a ela o verdadeiro poder que uma Fera Mecânica deve ter!",
  ui_story_5070_50701201_90_dialog_content = "Os piratas no Shadowind finalmente foram resolvidos. Estão todos bem?",
  ui_story_5070_50701201_91_dialog_content = "Estamos basicamente bem, mas alguns de nossos construtores navais estão feridos e alguns de nossos passageiros estão desaparecidos.",
  ui_story_5070_50701201_92_dialog_content = "Jiu caiu ao mar por causa de seus ferimentos e ainda não há sinais dela...",
  ui_story_5070_50701201_93_dialog_content = "Sua Alteza! Está tudo bem?",
  ui_story_5070_50701201_94_dialog_content = "Jiu! Por que está preocupado comigo? Quão machucado você está?",
  ui_story_5070_50701201_95_dialog_content = "Eu acidentalmente engoli algumas goladas de água.",
  ui_story_5070_50701201_96_dialog_content = "Mas eu falhei no meu dever como seu guarda-costas ao deixar seu lado neste momento. Por favor, me castigue.",
  ui_story_5070_50701201_97_dialog_content = "Pare com isso. Você poderia ter desviado do raio se não estivesse me protegendo...",
  ui_story_5070_50701201_98_dialog_content = "Como posso até mesmo repreendê-lo? Venha examinar Jiu, Liqing...",
  ui_story_5070_50701201_99_dialog_content = "Obrigado.",
  ui_story_5070_50701201_100_dialog_content = "Com Jiu de volta, só falta a Ministra Armilla...",
  ui_story_5070_50701201_101_dialog_content = "Xuan Ji provavelmente está naquele navio oposto.",
  ui_story_5070_50701201_102_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5070_50701201_103_dialog_content = "É aquele brilho peculiar de novo...",
  ui_story_5070_50701201_104_dialog_content = "Certo, vamos ver.",
  ui_story_5070_50701201_105_dialog_content = "Contra o que ela está lutando?! Por que ela apenas desvia sem contra-atacar?!",
  ui_story_5070_50701201_106_dialog_content = "Não aguento mais isso! Zhong Xu, vamos ajudá-la.",
  ui_story_5070_50701201_107_dialog_content = "Se eu a salvar no último minuto, ela ficaria com vergonha demais para me chamar de pequeno novamente!",
  ui_story_5070_50701201_108_dialog_content = "Talvez não seja necessário.",
  ui_story_5070_50701201_109_dialog_content = "De jeito nenhum... Ela também te ofendeu? Você realmente planeja deixá-la morrer?",
  ui_story_5070_50701201_110_dialog_content = "O que estou dizendo é que a Ministra Armilla não precisa da nossa ajuda.",
  ui_story_5070_50701201_111_dialog_content = "Sim. Ela não parecia estar correndo por toda parte apenas para se esconder.",
  ui_story_5070_50701201_112_dialog_content = "Acho que ela estava intencionalmente usando os ataques do lado oposto para destruir o ambiente ao redor.",
  ui_story_5070_50701201_113_dialog_content = "Eu quero destruir o abrigo daquela Fera Mecânica!",
  ui_story_5070_50701201_114_dialog_content = "Mas por que ela faria isso?",
  ui_story_5070_50701201_115_dialog_content = "Eu não sei... Na verdade, talvez eu saiba.",
  ui_story_5070_50701201_116_dialog_content = "Então, mesmo que você fortaleça o Shadowind com todos os materiais que conseguir encontrar...",
  ui_story_5070_50701201_117_dialog_content = "Não vai resistir à Chama Zhuyin em seu poder máximo.",
  ui_story_5070_50701201_118_dialog_content = "Ignorar o grande buraco no convés é uma coisa, mas aumentá-lo deliberadamente?",
  ui_story_5070_50701201_119_dialog_content = "Está quase expondo o núcleo do Shadowind. Isso é muito bizarro... Sol, o que você acha disso?",
  ui_story_5070_50701201_120_dialog_content = "Por favor, mantenha o experimento fracassado e alguém de olho na Chama em segredo.",
  ui_story_5070_50701201_121_dialog_content = "Talvez... Mas o que devemos fazer agora?",
  ui_story_5070_50701201_122_dialog_content = "Apenas espere.",
  ui_story_5070_50701201_123_dialog_content = "(...De jeito nenhum.)",
  ui_story_5070_50701201_124_dialog_content = "(Se for o que eu estou pensando, Xuan Ji, você não tem mais o direito de me chamar de imprudente.)",
  ui_story_5070_50701201_125_dialog_content = "(Você seria o maior aventureiro a bordo!)",
  ui_story_5070_50701201_126_dialog_content = "O que você está olhando, PlayerName? Tem algo dentro daquele buraco enorme no convés?",
  ui_story_5070_50701201_127_dialog_content = "Não agora.",
  ui_story_5070_50701201_128_dialog_content = "Mas será iminente.",
  ui_story_5070_50701201_129_dialog_content = "Todos! Me ajudem!",
  ui_story_5070_50701201_130_dialog_content = "Precisamos atrair essas Feras Mecânicas para o Shadowind!",
  ui_story_5070_50701201_131_dialog_content = "Relâmpago Flash—",
  ui_story_5070_50701201_132_dialog_content = "Eu não disse que era inútil?",
  ui_story_5070_50701201_133_dialog_content = "Cada parte do Stinger é criada com os designs de ponta que encontrei ao redor do mundo.",
  ui_story_5070_50701201_134_dialog_content = "Todos os seus ataques são inúteis!",
  ui_story_5070_50701201_135_dialog_content = "Não tenho certeza sobre isso.",
  ui_story_5070_50701201_136_dialog_content = "?!",
  ui_story_5070_50701201_137_dialog_content = "PlayerName? Se você conseguiu se conectar com minha mente, deve ter se saído bem por aí.",
  ui_story_5070_50701201_138_dialog_content = "Haha... Obrigado, Zhong Xu. Mas podemos discutir isso depois.",
  ui_story_5070_50701201_139_dialog_content = "Ouvi o que você estava dizendo agora há pouco. Acontece que a explosão naquele dia foi causada por esse impostor Sol, o Habilidoso.",
  ui_story_5070_50701201_140_dialog_content = "Atingido por um raio por roubar. As pessoas de Longzhou chamariam isso de retribuição divina.",
  ui_story_5070_50701201_141_dialog_content = "Ela realmente acha que é destino? Eu não gostaria de receber esse tipo de raio.",
  ui_story_5070_50701201_142_dialog_content = "Nem eu!",
  ui_story_5070_50701201_143_dialog_content = "Além disso, a fera mecânica dela é muito feia. Todo esse contorcer é simplesmente nojento!",
  ui_story_5070_50701201_144_dialog_content = "Eu disse que era uma grande e feia bagunça.",
  ui_story_5070_50701201_145_dialog_content = "... Eu nunca imaginei que o Shadowind seria comparado com algo assim.",
  ui_story_5070_50701201_146_dialog_content = "... Já chega!",
  ui_story_5070_50701201_147_dialog_content = "Stinger! Vá até o Shadowind e acabe com todos esses tolos ignorantes!",
  ui_story_5070_50701202_1_dialog_content = "Meu... mais poderoso animal mecânico... Como isso pôde acontecer...",
  ui_story_5070_50701202_2_dialog_content = "Você—!",
  ui_story_5070_50701202_3_dialog_content = "Vai continuar com isso? Eu não me lembro de você ser um bom lutador.",
  ui_story_5070_50701202_4_dialog_content = "Ha... Haha, hahaha!",
  ui_story_5070_50701202_5_dialog_content = "Não se empolgue ainda! Irmã mais velha, você não deve ter esquecido quais são os poderes do meu Ferrão, certo?",
  ui_story_5070_50701202_6_dialog_content = "Chama Zhuyin! É a verdadeira arte do artesanato que fornece energia infinita às criações mecânicas!",
  ui_story_5070_50701202_7_dialog_content = "Levante-se, Stinger! A batalha ainda não acabou!",
  ui_story_5070_50701202_8_dialog_content = "Cuidado, pessoal! O grandão está se mexendo de novo!",
  ui_story_5070_50701202_9_dialog_content = "Então as coisas ainda não acabaram. Por favor, recue, Alteza.",
  ui_story_5070_50701202_10_dialog_content = "Você é quem está comemorando prematuramente.",
  ui_story_5070_50701202_11_dialog_content = "Aquele olhar de novo... Não me dê esse olhar superior nunca mais! Eu—",
  ui_story_5070_50701202_12_dialog_content = "PlayerName, tente mantê-la parada! Eu só preciso de um pouco de tempo!",
  ui_story_5070_50701202_13_dialog_content = "Aumento de Força!",
  ui_story_5070_50701202_14_dialog_content = "Eca-!",
  ui_story_5070_50701202_15_dialog_content = "Vou deixá-la brevemente tonta, e vocês empurram a fera para dentro agora!",
  ui_story_5070_50701202_16_dialog_content = "Empurrar? Empurrar para onde? O buraco no convés?!",
  ui_story_5070_50701202_17_dialog_content = "Isso não é apenas um buraco.",
  ui_story_5070_50701202_18_dialog_content = "Fiz isso especialmente para isso.",
  ui_story_5070_50701202_19_dialog_content = "Um... Dois... Três!",
  ui_story_5070_50701202_20_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5070_50701202_21_dialog_content = "Conseguimos! Aquele cara era realmente pesado.",
  ui_story_5070_50701202_22_dialog_content = "Eu vou assumir daqui.",
  ui_story_5070_50701202_23_dialog_content = "Com algumas modificações, podemos conectá-lo ao Shadowind.",
  ui_story_5070_50701202_24_dialog_content = "Argh... O-o que você vai fazer...!",
  ui_story_5070_50701202_25_dialog_content = "Tenho certeza de que você viu meu rascunho de mudanças para o Shadowind em seu disfarce de Sol, certo?",
  ui_story_5070_50701202_26_dialog_content = "Não brinque assim... Isso nem é possível...",
  ui_story_5070_50701202_27_dialog_content = "Para suportar um navio de grande porte como o Shadowind com uma estrutura dessas...",
  ui_story_5070_50701202_28_dialog_content = "É necessário um núcleo com o mesmo nível de potência da Chama Zhuyin em plena aceleração.",
  ui_story_5070_50701202_29_dialog_content = "Com os materiais do Shadowind apenas, ele não consegue nem suportar o impacto...",
  ui_story_5070_50701202_30_dialog_content = "Você está certo, é um sonho impossível apenas com isso.",
  ui_story_5070_50701202_31_dialog_content = "Mas para criar a fera mecânica mais poderosa...",
  ui_story_5070_50701202_32_dialog_content = "Você não usou materiais que pudessem resistir à Chama Zhuyin em seu máximo poder?",
  ui_story_5070_50701202_33_dialog_content = "Espere, você quer dizer... Enlouqueceu?! É absolutamente...",
  ui_story_5070_50701202_34_dialog_content = "É por isso que eu disse que você está muito ocupado com designs para entender a tecnologia dos gadgets.",
  ui_story_5070_50701202_35_dialog_content = "Enquanto houver materiais disponíveis, a engenhosidade é ilimitada no que pode criar.",
  ui_story_5070_50701202_36_dialog_content = "Do que você está falando?",
  ui_story_5070_50701202_37_dialog_content = "Fique tranquilo, pequenino. Você descobrirá em breve.",
  ui_story_5070_50701202_38_dialog_content = "Mergulhe com todos os seus sentidos nesta experiência única na vida.",
  ui_story_5070_50701202_39_dialog_content = "Estou prestes a usar a fera como fonte de energia para regular a produção da Chama Zhuyin.",
  ui_story_5070_50701202_X39_dialog_content = "E faça o Shadowind...",
  ui_story_5070_50701202_40_dialog_content = "Faça um voo curto!",
  ui_story_5070_50701202_41_dialog_content = "<color=#e8d9bb>Explosão de assobio</color>",
  ui_story_5070_50701202_42_dialog_content = "<color=#e8d9bb>Sob o comando de Xuan Ji, aqueles que ainda conseguem se mover assumem temporariamente as funções dos carpinteiros navais.</color>",
  ui_story_5070_50701202_43_dialog_content = "<color=#e8d9bb>Com o som do assobio, todos os mecanismos modificados no Shadowind entram em ação de uma só vez.</color>",
  ui_story_5070_50701202_44_dialog_content = "<color=#e8d9bb>O navio treme, engrenagens internas se chocam e se estendem... Feixes de Lumina se desdobram em ambos os lados do navio como uma multidão de asas!</color>",
  ui_story_5070_50701202_45_dialog_content = "Você faria a honra, PlayerName?",
  ui_story_5070_50701202_46_dialog_content = "Aumento de Força!",
  ui_story_5070_50701202_47_dialog_content = "(Sinta a Chama Zhuyin e estimule seu poder ao máximo! E então...)",
  ui_story_5070_50701202_48_dialog_content = "(Shadowind, mova-se!)",
  ui_story_5070_50701202_49_dialog_content = "De jeito nenhum... Não acredito nisso!",
  ui_story_5070_50701202_50_dialog_content = "Droga... é apenas um golpe momentâneo de sorte! Nós... ainda não acabou!",
  ui_story_5070_50701202_51_dialog_content = "<color=#e8d9bb>Plop!</color>",
  ui_story_5070_50701202_52_dialog_content = "Ela pulou no mar!",
  ui_story_5070_50701202_53_dialog_content = "Não se importe com ela.",
  ui_story_5070_50701202_54_dialog_content = "As asas só podem sustentar o navio por um tempo limitado. Temos que aproveitar essa oportunidade e sair daqui.",
  ui_story_5070_50701202_55_dialog_content = "<color=#e8d9bb>Crec...</color>",
  ui_story_5070_50701202_56_dialog_content = "(O Shadowind só ficou no ar brevemente, e eu já podia ouvir o som de maquinaria sobrecarregada.)",
  ui_story_5070_50701202_57_dialog_content = "(Com um impulso final, a luz intensa começou a se dissipar no ar.)",
  ui_story_5070_50701202_58_dialog_content = "(Isso vai servir.)",
  ui_story_5070_50701202_59_dialog_content = "O sol, uma brisa leve e ondas calmas... Conseguimos sair!",
  ui_story_5070_50701202_60_dialog_content = "<color=#e8d9bb>Bang!!!</color>",
  ui_story_5070_50701202_61_dialog_content = "<color=#e8d9bb>O Shadowind cai pesadamente de volta ao mar.</color>",
  ui_story_5070_50701202_62_dialog_content = "<color=#e8d9bb>Mas desta vez, o ambiente está calmo, sem mais redemoinhos ou correntes ocultas.</color>",
  ui_story_5070_50701202_63_dialog_content = "Conseguimos!",
  ui_story_5070_50701202_64_dialog_content = "Você é incrível, Xuan Ji!",
  ui_story_5070_50701202_65_dialog_content = "É um gadget incrível.",
  ui_story_5070_50701202_66_dialog_content = "Mas desta vez, vou deixar a humildade de lado e aceitar seu elogio.",
  ui_story_5070_50701202_67_dialog_content = "Falando nisso, embora não tenha durado muito, o Shadowind realmente voou pelo céu.",
  ui_story_5070_50701202_68_dialog_content = "E desta vez, Xuan Ji se tornou legitimamente o navegador do Shadowind.",
  ui_story_5070_50701202_69_dialog_content = "Fiz, não foi?",
  ui_story_5070_50701202_70_dialog_content = "Nunca esquecerei essa sensação.",
  ui_story_5070_50701202_71_dialog_content = "(Após atravessar o oceano, Xuan Ji rapidamente usou o astrolábio e outros equipamentos para ajudar o Shadowind a voltar ao rumo certo.)",
  ui_story_5070_50701202_72_dialog_content = "(No dia seguinte, encontramos os destroços do navio de Zhui Hu não muito longe.)",
  ui_story_5070_50701202_73_dialog_content = "Afundou no mar assim como o navio da Lin Guild, que afundou devido às suas tramoias. Causa e efeito estão em jogo aqui.",
  ui_story_5070_50701202_74_dialog_content = "Mas pessoas como Zhui Hu e seus apoiadores não morrerão tão facilmente. Eles também não desistirão tão facilmente.",
  ui_story_5070_50701202_75_dialog_content = "Ninguém sabe quais outros planos eles vão criar.",
  ui_story_5070_50701202_76_dialog_content = "De qualquer forma, encontraremos uma maneira de lidar com isso. Sempre há um contra-ataque para qualquer tipo de inimigo.",
  ui_story_5070_50701202_77_dialog_content = "Mesmo que não, podemos improvisar na hora.",
  ui_story_5070_50701202_78_dialog_content = "Zhui Hu não foi seu professor uma vez, Xuan Ji?",
  ui_story_5070_50701202_79_dialog_content = "Mesmo que ele tenha sido expulso, ele pelo menos foi discípulo de uma grande seita.",
  ui_story_5070_50701202_80_dialog_content = "Ele tinha que ser muito mais forte do que pessoas normais para criar algo assim.",
  ui_story_5070_50701202_81_dialog_content = "Como ele poderia ter sido contratado para atuar como pirata ou contrabandista?",
  ui_story_5070_50701202_82_dialog_content = "Eu tenho um palpite.",
  ui_story_5070_50701202_83_dialog_content = "Mas eu não sei se é bom ou ruim seguir essa linha de pensamento.",
  ui_story_5070_50701202_84_dialog_content = "Zhui Hu aprendeu muitas técnicas, mas nunca percebeu o que realmente é a tecnologia dos gadgets.",
  ui_story_5070_50701202_85_dialog_content = "Estamos falando do resultado de séculos de prática e determinação.",
  ui_story_5070_50701202_86_dialog_content = "Isso não pode ser compreendido através de subterfúgios e roubo.",
  ui_story_5070_50701202_87_dialog_content = "Trouxe tudo que você pediu, Xuan Ji.",
  ui_story_5070_50701202_88_dialog_content = "Mas só temos esses poucos envelopes para nos comunicar com meu tio-avô neste navio.",
  ui_story_5070_50701202_89_dialog_content = "Qual propósito você tem para eles?",
  ui_story_5070_50701202_90_dialog_content = "Bem, vou descobrir quando eu vê-los.",
  ui_story_5070_50701202_91_dialog_content = "Ah, como está o Jiu?",
  ui_story_5070_50701202_92_dialog_content = "Vejo que você ainda se importa.",
  ui_story_5070_50701202_93_dialog_content = "Liqing examinou-a e ela deve se recuperar totalmente em alguns dias.",
  ui_story_5070_50701202_94_dialog_content = "(O tom da conversa voltou à sua natureza leve e animada de sempre.)",
  ui_story_5070_50701202_95_dialog_content = "(Eu vi Xuan Ji guardar cuidadosamente aquelas cartas...)",
  ui_story_5070_50701202_X95_dialog_content = "(Embora ela nunca tenha respondido à pergunta, \"Qual a utilidade?\".)",
  ui_story_5070_50701301_1_dialog_content = "(Os dois últimos dias a bordo do navio passaram voando.)",
  ui_story_5070_50701301_2_dialog_content = "(Todos estavam fisicamente e mentalmente exaustos por todas as crises e batalhas.)",
  ui_story_5070_50701301_3_dialog_content = "(Felizmente, logo após os reparos serem concluídos — Longzhou surgiu à vista.)",
  ui_story_5070_50701301_4_dialog_content = "Esta viagem teve muitas reviravoltas, mas tudo acabou bem.",
  ui_story_5070_50701301_5_dialog_content = "O Shadowind retornou. Esta viagem está oficialmente encerrada.",
  ui_story_5070_50701301_6_dialog_content = "Em nome do Shadowind, quero agradecer a todos por nos ajudarem ao longo do caminho.",
  ui_story_5070_50701301_7_dialog_content = "Não ignore seus próprios méritos nisso.",
  ui_story_5070_50701301_8_dialog_content = "Chegamos com segurança e reestabelecemos a rota. Nós e o Shadowind concluímos nossas missões.",
  ui_story_5070_50701301_9_dialog_content = "Princesa Dantang, alguém acabou de informar que o enviado do Reino Ji está esperando no porto para escoltá-la de volta ao palácio.",
  ui_story_5070_50701301_10_dialog_content = "Tenho todas as informações, então preciso relatar o mais rápido possível.",
  ui_story_5070_50701301_11_dialog_content = "Vejo uma série de reuniões e banquetes em um futuro próximo.",
  ui_story_5070_50701301_12_dialog_content = "Você também terá que estar pronto, PlayerName.",
  ui_story_5070_50701301_13_dialog_content = "Hã? Eu?",
  ui_story_5070_50701301_14_dialog_content = "Ah, é verdade! Eu totalmente esqueci que vim para Longzhou como enviado de Astra!",
  ui_story_5070_50701301_15_dialog_content = "O-O que eu faço? De repente estou nervoso.",
  ui_story_5070_50701301_16_dialog_content = "Não se preocupe, apenas encare isso como ver outro lado de Longzhou.",
  ui_story_5070_50701301_17_dialog_content = "Finalmente estou de volta. Por um momento, pensei que passaria minha vida em Astra...",
  ui_story_5070_50701301_18_dialog_content = "Agora que penso nisso, sinto que tudo mudou, mesmo que não tenha passado mais do que meio ano desde que estive longe de Longzhou.",
  ui_story_5070_50701301_19_dialog_content = "Chega. Agora, vamos descobrir o que faremos em seguida!",
  ui_story_5070_50701301_20_dialog_content = "Vamos comer algo delicioso? Ou ter uma boa noite de sono?",
  ui_story_5070_50701301_21_dialog_content = "Retorne à Guilda Lin.",
  ui_story_5070_50701301_22_dialog_content = "Com a ajuda da Princesa Dantang e dos outros, pode ser provado que a Guilda Lin foi injustamente condenada pela acusação de contrabando.",
  ui_story_5070_50701301_23_dialog_content = "Depois de tudo que aconteceu, deve haver muitos assuntos que precisam de tratamento urgente.",
  ui_story_5070_50701301_24_dialog_content = "O guildmaster... O guildmaster deve estar ainda me esperando!",
  ui_story_5070_50701301_25_dialog_content = "Ei! Espere!",
  ui_story_5070_50701301_26_dialog_content = "Não se preocupe.",
  ui_story_5070_50701301_27_dialog_content = "Eu relatei tudo assim que pousamos e enviei servos para levar as provas e o dinheiro para os Escritórios de Comércio Marítimo...",
  ui_story_5070_50701301_28_dialog_content = "O Guildmaster já deve ter sido libertado. Agora é a hora do seu reencontro.",
  ui_story_5070_50701301_29_dialog_content = "Olhe para lá.",
  ui_story_5070_50701301_30_dialog_content = "... É tudo culpa da Xuan Ji. Ela fez a cadeira de rodas do Zhong Xu muito rápida.",
  ui_story_5070_50701301_31_dialog_content = "Irmão Zhong!",
  ui_story_5070_50701301_32_dialog_content = "Lin?",
  ui_story_5070_50701301_33_dialog_content = "Nunca imaginei que você ainda viria me cumprimentar agora que perdi minhas pernas.",
  ui_story_5070_50701301_34_dialog_content = "Suas palavras... Não sei como responder a isso...",
  ui_story_5070_50701301_35_dialog_content = "Eu nem sei se devo expressar gratidão primeiro ou pedir desculpas a você.",
  ui_story_5070_50701301_36_dialog_content = "Não há necessidade de tais palavras entre nós.",
  ui_story_5070_50701301_37_dialog_content = "Se você realmente quer fazer algo, dê as boas-vindas primeiro a Liqing e ao Capitão Yuebai.",
  ui_story_5070_50701301_38_dialog_content = "Eu... É o suficiente para mim ver que você está bem!",
  ui_story_5070_50701301_39_dialog_content = "Ah, Jiu, por favor envie uma carta pra mim.",
  ui_story_5070_50701301_40_dialog_content = "Devo informar minha família sobre a missão concluída e meu retorno em segurança.",
  ui_story_5070_50701301_41_dialog_content = "Sim. Todos ficarão felizes por você, Sua Alteza.",
  ui_story_5070_50701301_42_dialog_content = "Algum problema, PlayerName?",
  ui_story_5070_50701301_43_dialog_content = "Muitas pessoas desembarcaram: Dantang, Jiu, Zhong Xu, Liqing, Xuan Ji e eu...",
  ui_story_5070_50701301_44_dialog_content = "Mas por que eu sempre sinto que estou esquecendo algo?",
  ui_story_5070_50701301_45_dialog_content = "Eh, esquece. Provavelmente não é importante. Vamos lá!",
  ui_story_5070_50701301_46_dialog_content = "Senhora Xuan Ji, é permitido descarregar esses bois de madeira aqui?",
  ui_story_5070_50701301_47_dialog_content = "Claro, valeu.",
  ui_story_5070_50701301_48_dialog_content = "Sem problemas. Devemos nosso retorno seguro a você, Senhora Xuan Ji, e aprendemos bastante no caminho.",
  ui_story_5070_50701301_49_dialog_content = "Seria incrível se pudéssemos navegar juntos novamente na próxima vez.",
  ui_story_5070_50701301_50_dialog_content = "Sim, espero que nos encontremos novamente.",
  ui_story_5070_50701301_X50_dialog_content = "Hum? Seu...",
  ui_story_5070_50701301_X51_dialog_content = "Estive fora por tanto tempo que quase esqueci como todos os dias parecem primavera ao longo da costa sul do Reino Ji.",
  ui_story_5070_50701301_X52_dialog_content = "Nunca pensei que realmente seria capaz de retornar a Longzhou com o que eu estava procurando...",
  ui_story_5070_50701301_51_dialog_content = "...",
  ui_story_5070_50701301_52_dialog_content = "Ok, você já viu bastante.",
  ui_story_5070_50701301_53_dialog_content = "Então você não tem coisas mais importantes para fazer agora?",
  ui_story_5070_50701301_54_dialog_content = "Espere, o que tem neste boi de madeira...?",
  ui_story_5070_50701301_55_dialog_content = "Ugh!",
  ui_story_5070_50701301_56_dialog_content = "Está claro lá fora? Bom dia.",
  ui_story_5070_50701301_57_dialog_content = "O que você está fazendo se escondendo aí dentro?",
  ui_story_5070_50701301_58_dialog_content = "É porque... Ah, você poderia me dar uma mão e me tirar daqui primeiro? Obrigado.",
  ui_story_5070_50701301_59_dialog_content = "Ai... Estou tão dolorido por me esconder ali.",
  ui_story_5070_50701301_60_dialog_content = "Quem diria que durante essa jornada não enfrentaríamos apenas tempestades e Eclipsitas, mas também seríamos atacados por piratas.",
  ui_story_5070_50701301_61_dialog_content = "Felizmente, eu adivinhei nossa sorte antes de zarpar.",
  ui_story_5070_50701301_62_dialog_content = "Levei dias de pesquisa para entender a adivinhação do Cavalo Yin e do Boi Yin. Provavelmente corresponde ao seu boi de madeira.",
  ui_story_5070_50701301_63_dialog_content = "Foi assim que encontrei um lugar perfeito para me esconder. Caso contrário, essa jornada cheia de desastres teria tirado minha vida.",
  ui_story_5070_50701301_64_dialog_content = "Ugh...",
  ui_story_5070_50701301_65_dialog_content = "Isso me lembra, eu te devo por usar este lugar.",
  ui_story_5070_50701301_66_dialog_content = "Que tal uma adivinhação grátis?",
  ui_story_5070_50701301_67_dialog_content = "Está tudo bem.",
  ui_story_5070_50701301_68_dialog_content = "Nós, artesãos, valorizamos muito mais nossas criações do que o destino.",
  ui_story_5070_50701301_69_dialog_content = "Mesmo que você preveja algo terrível, isso não significa que eu não deva fazer o que precisa ser feito!",
  ui_story_5070_50701301_70_dialog_content = "Tudo bem. Boa sorte para você então.",
  ui_story_5070_50701301_71_dialog_content = "Adeus.",
  ui_story_5070_50701301_72_dialog_content = "(Vamos ver... Enquanto eu estava no boi de madeira mais cedo, eu desenhei...)",
  ui_story_5070_50701301_73_dialog_content = "(Tigre Yang e Dragão Yin? Interessante.)",
  ui_story_5070_50701301_74_dialog_content = "(Era um boi morto e um cavalo silencioso no navio, então eu permaneci escondido e consegui escapar do perigo por pouco.)",
  ui_story_5070_50701301_X74_dialog_content = "(Agora, é um sinal de perigo.)",
  ui_story_5070_50701301_75_dialog_content = "(Xuan Ji está sempre dizendo a todos para ficarem longe do perigo, mas ela está entrando na toca do tigre?)",
  ui_story_5070_50701301_76_dialog_content = "Envie uma carta.",
  ui_story_5070_50701301_77_dialog_content = "Bom te ver novamente. Duas cartas, ambas para serem enviadas ao Reino Ye, certo?",
  ui_story_5070_50701301_78_dialog_content = "Fique tranquilo. Eles serão entregues a tempo.",
  ui_story_5070_50701301_79_dialog_content = "<color=#e8d9bb>Não muito longe do Posto</color>",
  ui_story_5070_50701301_80_dialog_content = "Vá informar ao nosso senhor; Frost Blade escoltou com segurança a princesa de volta a Longzhou.",
  ui_story_5070_50701301_81_dialog_content = "Cuide das pessoas no correio; não deixe pontas soltas para o nosso senhor."
}
return config
